            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pengumuman resmi berikut: 新工場の稼働___、安全点検を二週間かけて実施した。', '{"options":["にあたって","にかかわらず","につれて","かねない"],"translation":"Menjelang beroperasinya pabrik baru, pemeriksaan keselamatan dilakukan selama dua minggu.","sentence_template":"新工場の稼働[blank]、安全点検を二週間かけて実施した。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, '稼働 (pengoperasian) + にあたって menyatakan persiapan krusial menjelang dimulainya operasional.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang paling tepat untuk surat edaran: 社名変更___、取引先各位へご案内状を送付いたしました。', '{"options":["にあたり","に伴って","に限らず","の上で"],"translation":"Sehubungan dengan perubahan nama perusahaan, kami telah mengirimkan surat pemberitahuan kepada seluruh mitra bisnis.","sentence_template":"社名変更[blank]、取引先各位へご案内状を送付いたしました。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, '～にあたり adalah varian formal tertulis yang lazim pada surat pemberitahuan bisnis.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman direksi berikut. Langkah apa yang diambil sebelum merilis layanan baru?', '{"audio_text":"新サービスの提供開始にあたり、個人情報の保護体制を全面的に見直しました。","options":[{"id":"opt_1","text":"Menunda peluncuran layanan hingga tahun depan"},{"id":"opt_2","text":"Meninjau ulang sistem perlindungan data pribadi secara menyeluruh"},{"id":"opt_3","text":"Mengurangi jumlah staf layanan pelanggan"},{"id":"opt_4","text":"Memindahkan kantor pusat ke kota lain"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '個人情報の保護体制を全面的に見直しました berarti meninjau ulang sistem perlindungan data pribadi secara menyeluruh.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang pelaksanaan survei, kami meminta persetujuan responden."', '{"tokens":["実施","回答者の","得た。","かねない。","アンケートの","にあたって、","同意を","にもかかわらず、"],"target_translation":"Menjelang pelaksanaan survei, kami meminta persetujuan responden.","romaji":"Ankeeto no jisshi ni atatte, kaitousha no doui o eta."}'::jsonb, '["アンケートの","実施","にあたって、","回答者の","同意を","得た。"]'::jsonb, '実施にあたって menyatakan persiapan etis sebelum survei dilaksanakan.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pada kesempatan pembukaan pameran ini, terima kasih atas kehadiran Anda."', '{"display_text":"本展示会の開催にあたり、ご来場いただき誠にありがとうございます。","romaji":"Hon tenjikai no kaisai ni atari, goraijou itadaki makoto ni arigatou gozaimasu.","phonetic_breakdown":["ほんてんじかいの","かいさいに","あたり","ごらいじょういただき","まことに","ありがとうございます"]}'::jsonb, '{"expected_transcript":"本展示会の開催にあたり、ご来場いただき誠にありがとうございます。"}'::jsonb, '開催にあたり sering digunakan pada sambutan pembukaan pameran atau konferensi.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat panduan akademik: 博士論文を提出する___、所定の書式を厳守すること。', '{"options":["にあたっては","つつあっては","ざるを得ずに","わけにはいかず"],"translation":"Dalam rangka menyerahkan disertasi doktor, wajib mematuhi format yang ditetapkan.","sentence_template":"博士論文を提出する[blank]、所定の書式を厳守すること。"}'::jsonb, '{"selected":"にあたっては"}'::jsonb, '～にあたっては memberi penekanan syarat khusus yang harus dipenuhi pada momen tersebut.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan arahan manajer proyek. Apa yang ditekankan sebelum rapat dengan klien?', '{"audio_text":"顧客との最終交渉にあたり、想定される質問への回答を事前に共有しておきたい。","options":[{"id":"opt_1","text":"Memesan ruang rapat yang lebih besar"},{"id":"opt_2","text":"Membatalkan kontrak yang sudah berjalan"},{"id":"opt_3","text":"Berbagi jawaban atas pertanyaan yang diperkirakan muncul"},{"id":"opt_4","text":"Mengundang media massa ke sesi negosiasi"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '想定される質問への回答を事前に共有する berarti membagikan jawaban atas pertanyaan yang diprediksi sebelumnya.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dalam rangka pindah kantor, kami memperbarui sistem keamanan."', '{"tokens":["移転","セキュリティシステムを","した。","移転した","オフィスの","にあたり、","更新","に限らず、"],"target_translation":"Dalam rangka pindah kantor, kami memperbarui sistem keamanan.","romaji":"Ofisu no iten ni atari, sekyuriti shisutemu o koushin shita."}'::jsonb, '["オフィスの","移転","にあたり、","セキュリティシステムを","更新","した。"]'::jsonb, '移転 (relokasi kantor) + にあたり tepat dipakai untuk perubahan besar perusahaan.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pidato kepala departemen. Apa harapan beliau untuk proyek tahun ini?', '{"audio_text":"新年度の事業展開にあたって、部署の垣根を越えた連携を期待しています。","options":[{"id":"opt_1","text":"Setiap divisi bekerja secara terpisah tanpa koordinasi"},{"id":"opt_2","text":"Menghentikan seluruh proyek pengembangan tahun ini"},{"id":"opt_3","text":"Mengurangi jam kerja lembur di akhir pekan"},{"id":"opt_4","text":"Terjalinnya kolaborasi lintas divisi dalam ekspansi bisnis"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '部署の垣根を越えた連携 berarti kolaborasi yang melampaui sekat antardivisi.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang wawancara kerja, saya meneliti profil perusahaan secara mendalam."', '{"tokens":["受ける","企業の","深く調べた。","にもかかわらず、","面接を","にあたって、","情報を","受けた"],"target_translation":"Menjelang wawancara kerja, saya meneliti profil perusahaan secara mendalam.","romaji":"Mensetsu o ukeru ni atatte, kigyou no jouhou o fukaku shirabeta."}'::jsonb, '["面接を","受ける","にあたって、","企業の","情報を","深く調べた。"]'::jsonb, 'Verba bentuk kamus 受ける + にあたって menyatakan persiapan sebelum momen penting.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih frasa yang sesuai untuk kontrak: 本規約の改定___、利用者の皆様に三十日前までに通知します。', '{"options":["にあたり","に伴って","かねず","つつあり"],"translation":"Menjelang revisi ketentuan ini, kami akan memberi tahu pengguna paling lambat 30 hari sebelumnya.","sentence_template":"本規約の改定[blank]、利用者の皆様に三十日前までに通知します。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, '改定にあたり lazim dipakai dalam pengumuman pembaruan syarat dan ketentuan.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang penandatanganan perjanjian, mari kita pastikan setiap pasalnya."', '{"display_text":"合意書の署名にあたって、各条項を丁寧に確認いたしましょう。","romaji":"Gouisho no shomei ni atatte, kaku joukou o teinei ni kakunin itashimashou.","phonetic_breakdown":["ごういしょの","しょめいに","あたって","かくじょうこうを","ていねいに","かくにんいたしましょう"]}'::jsonb, '{"expected_transcript":"合意書の署名にあたって、各条項を丁寧に確認いたしましょう。"}'::jsonb, '各条項 (setiap pasal) dan 署名 (penandatanganan) adalah kosakata kunci dokumen bisnis N2.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 創業五十周年を___にあたり、記念誌を刊行する運びとなった。', '{"options":["迎える","迎えた","迎えて","迎えよう"],"translation":"Dalam rangka menyongsong ulang tahun berdirinya perusahaan ke-50, diputuskan untuk menerbitkan buku kenangan.","sentence_template":"創業五十周年を[blank]にあたり、記念誌を刊行する運びとなった。"}'::jsonb, '{"selected":"迎える"}'::jsonb, 'Di depan にあたり, kata kerja harus dalam bentuk kamus (迎える).', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman universitas. Kapan mahasiswa harus mengikuti orientasi?', '{"audio_text":"海外留学への出発にあたっては、危機管理オリエンテーションの受講が必須となります。","options":[{"id":"opt_1","text":"Sebelum keberangkatan studi ke luar negeri"},{"id":"opt_2","text":"Setelah kembali ke Jepang dari luar negeri"},{"id":"opt_3","text":"Saat mendaftar beasiswa di tahun pertama"},{"id":"opt_4","text":"Ketika wisuda sarjana berlangsung"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '出発にあたっては menegaskan syarat wajib menjelang keberangkatan.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Pada kesempatan peluncuran aplikasi, kami mengadakan sesi uji coba gratis."', '{"tokens":["リリース","無料体験会を","した。","に伴って、","アプリの","にあたり、","開催","開催する"],"target_translation":"Pada kesempatan peluncuran aplikasi, kami mengadakan sesi uji coba gratis.","romaji":"Apuri no ririisu ni atari, muryou taikenkai o kaisai shita."}'::jsonb, '["アプリの","リリース","にあたり、","無料体験会を","開催","した。"]'::jsonb, 'Kata benda リリース + にあたり diikuti aksi promosi 開催した.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam rangka memulai kehidupan baru di Jepang, saya bertekad belajar lebih giat."', '{"display_text":"日本での新生活を始めるにあたって、さらに努力する決意です。","romaji":"Nihon de no shinseikatsu o hajimeru ni atatte, sara ni doryoku suru ketsui desu.","phonetic_breakdown":["にほんでの","しんせいかつを","はじめるに","あたって","さらに","どりょくするけついです"]}'::jsonb, '{"expected_transcript":"日本での新生活を始めるにあたって、さらに努力する決意です。"}'::jsonb, '決意です (bertekad) sangat cocok dipasangkan dengan momen awal ～を始めるにあたって.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih istilah bisnis yang tepat: 新規事業の___にあたり、綿密な予算案が策定された。', '{"options":["立ち上げ","見送り","廃止","延期"],"translation":"Menjelang perintisan bisnis baru, rancangan anggaran yang cermat telah disusun.","sentence_template":"新規事業の[blank]にあたり、綿密な予算案が策定された。"}'::jsonb, '{"selected":"立ち上げ"}'::jsonb, '立ち上げ (tachiage) berarti peluncuran atau perintisan proyek/bisnis baru.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang pembukaan rapat umum, mohon matikan suara ponsel Anda."', '{"display_text":"総会の開会にあたり、携帯電話の電源をお切りください。","romaji":"Soukai no kaikai ni atari, keitai denwa no dengen o okiri kudasai.","phonetic_breakdown":["そうかいの","かいかいに","あたり","けいたいでんわの","でんげんを","おきりください"]}'::jsonb, '{"expected_transcript":"総会の開会にあたり、携帯電話の電源をお切りください。"}'::jsonb, 'お切りください adalah bentuk sopan untuk meminta hadirin mematikan perangkat.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Manakah pernyataan yang sesuai dengan isi audio?', '{"audio_text":"新制度を導入するにあたって、現場の担当者から広く意見を募った。","options":[{"id":"opt_1","text":"Perusahaan tidak meminta masukan sebelum mengubah sistem"},{"id":"opt_2","text":"Perusahaan menjaring masukan luas dari staf lapangan menjelang penerapan sistem baru"},{"id":"opt_3","text":"Sistem baru dibatalkan karena penolakan staf lapangan"},{"id":"opt_4","text":"Staf lapangan diminta membuat sistem sendiri tanpa panduan"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '意見を募る (menjaring pendapat) dilakukan menjelang penerapan sistem baru (導入するにあたって).', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan partikel penegas: 契約を更新する___、現行の料金体系を見直す必要がある。', '{"options":["にあたっては","にかかわらず","につれては","わけには"],"translation":"Dalam hal memperbarui kontrak, perlu meninjau kembali struktur tarif yang berlaku saat ini.","sentence_template":"契約を更新する[blank]、現行の料金体系を見直す必要がある。"}'::jsonb, '{"selected":"にあたっては"}'::jsonb, '～にあたっては menekankan persyaratan penting pada momen pembaruan kontrak.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang dimulainya penelitian bersama, kedua universitas menandatangani nota kesepahaman."', '{"tokens":["開始","両大学は","交わした。","に限らず、","共同研究の","にあたり、","覚書を","交わす"],"target_translation":"Menjelang dimulainya penelitian bersama, kedua universitas menandatangani nota kesepahaman.","romaji":"Kyoudou kenkyuu no kaishi ni atari, ryoudaigaku wa oboegaki o kawashita."}'::jsonb, '["共同研究の","開始","にあたり、","両大学は","覚書を","交わした。"]'::jsonb, '覚書を交わす (menandatangani/bertukar nota kesepahaman) adalah kolokasi formal N2.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pesan pembawa acara. Apa tujuan utama pertemuan hari ini?', '{"audio_text":"本日は新工場の建設にあたり、近隣住民の皆様へ工事計画をご説明いたします。","options":[{"id":"opt_1","text":"Merayakan selesainya pembangunan pabrik"},{"id":"opt_2","text":"Merekrut pekerja konstruksi dari luar kota"},{"id":"opt_3","text":"Menjelaskan rencana konstruksi pabrik baru kepada warga sekitar"},{"id":"opt_4","text":"Mengumumkan penutupan jalan tol nasional"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '近隣住民 (warga sekitar) dan 工事計画をご説明いたします menjelaskan rencana proyek konstruksi.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 大会に出場する___、毎日の練習メニューを強化した。', '{"options":["にあたって","ざるを得ず","かねなく","つつあり"],"translation":"Menjelang bertanding di turnamen, saya meningkatkan intensitas menu latihan harian.","sentence_template":"大会に出場する[blank]、毎日の練習メニューを強化した。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, '出場する (ikut bertanding) adalah peristiwa penting yang tepat memakai ～にあたって.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang presentasi akhir, kami memeriksa kembali seluruh data statistik."', '{"display_text":"最終発表にあたって、すべての統計データを再確認しました。","romaji":"Saishuu happyou ni atatte, subete no toukei deeta o saikakunin shimashita.","phonetic_breakdown":["さいしゅうはっぴょうに","あたって","すべての","とうけいでーたを","さいかくにんしました"]}'::jsonb, '{"expected_transcript":"最終発表にあたって、すべての統計データを再確認しました。"}'::jsonb, '統計データ (data statistik) dan 再確認 (verifikasi ulang) lazim di konteks akademik dan bisnis.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman resmi berikut. Tindakan apa yang dilakukan perusahaan?', '{"audio_text":"上場にあたり、監査体制の強化と情報開示の透明性向上を図ってまいります。","options":[{"id":"opt_1","text":"Menarik saham dari bursa efek"},{"id":"opt_2","text":"Mengurangi publikasi laporan keuangan tahunan"},{"id":"opt_3","text":"Menunda audit internal selama dua tahun"},{"id":"opt_4","text":"Memperkuat sistem audit dan meningkatkan transparansi keterbukaan informasi"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '上場にあたり berarti menjelang pencatatan saham di bursa (IPO).', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dalam rangka menerbitkan majalah baru, tim redaksi menyusun konsep awal."', '{"tokens":["創刊する","編集部は","練り上げた。","にもかかわらず、","新雑誌を","にあたり、","コンセプトを","創刊した"],"target_translation":"Dalam rangka menerbitkan majalah baru, tim redaksi menyusun konsep awal.","romaji":"Shin zasshi o soukan suru ni atari, henshuubu wa konseputo o neriageta."}'::jsonb, '["新雑誌を","創刊する","にあたり、","編集部は","コンセプトを","練り上げた。"]'::jsonb, '創刊する (menerbitkan edisi perdana) + にあたり memakai verba bentuk kamus.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi laporan ekonomi berikut: 少子高齢化の進行___、労働力不足が深刻な課題となっている。', '{"options":["に伴って","にあたって","に限らず","わけにはいかず"],"translation":"Seiring dengan berlanjutnya penurunan angka kelahiran dan penuaan penduduk, kekurangan tenaga kerja menjadi masalah serius.","sentence_template":"少子高齢化の進行[blank]、労働力不足が深刻な課題となっている。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, '進行に伴って menyatakan perubahan kedua (kekurangan tenaga kerja) yang muncul seiring perubahan pertama.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk penyambung kata benda yang tepat: 都市開発___環境破壊を防ぐため、新たな条例が制定された。', '{"options":["に伴う","に伴って","にあたり","に限る"],"translation":"Untuk mencegah kerusakan lingkungan yang menyertai pembangunan kota, peraturan daerah baru ditetapkan.","sentence_template":"都市開発[blank]環境破壊を防ぐため、新たな条例が制定された。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, 'Untuk menerangkan kata benda di belakangnya (環境破壊), digunakan bentuk ～に伴う.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan berita ekonomi berikut. Apa dampak dari melemahnya nilai tukar yen yang disebutkan?', '{"audio_text":"円安の進行に伴い、輸入原材料の価格が上昇し、食品メーカーの値上げが相次いでいる。","options":[{"id":"opt_1","text":"Harga bahan baku impor naik dan produsen makanan berturut-turut menaikkan harga"},{"id":"opt_2","text":"Harga seluruh produk makanan turun drastis di supermarket"},{"id":"opt_3","text":"Ekspor kendaraan bermotor dihentikan sementara"},{"id":"opt_4","text":"Jumlah wisatawan asing menurun tajam sepanjang tahun"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '輸入原材料の価格が上昇 (kenaikan harga bahan baku impor) memicu 値上げが相次いでいる (kenaikan harga berturut-turut).', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Seiring dengan berkembangnya AI, cara kerja di kantor berubah drastis."', '{"tokens":["発展","オフィスの","大きく変わった。","かねない。","AI技術の","に伴って、","働き方が","にあたって、"],"target_translation":"Seiring dengan berkembangnya AI, cara kerja di kantor berubah drastis.","romaji":"AI gijutsu no hatten ni tomonatte, ofisu no hatarakikata ga ookiku kawatta."}'::jsonb, '["AI技術の","発展","に伴って、","オフィスの","働き方が","大きく変わった。"]'::jsonb, '発展に伴って menghubungkan kemajuan teknologi dengan perubahan cara kerja.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring dengan meningkatnya wisatawan asing, panduan multibahasa makin diperluas."', '{"display_text":"外国人観光客の増加に伴い、多言語案内が充実してきています。","romaji":"Gaikokujin kankoukyaku no zouka ni tomonai, tagengo annai ga juujitsu shite kite imasu.","phonetic_breakdown":["がいこくじんかんこうきゃくの","ぞうかに","ともない","たげんごあんないが","じゅうじつしてきています"]}'::jsonb, '{"expected_transcript":"外国人観光客の増加に伴い、多言語案内が充実してきています。"}'::jsonb, '～に伴い adalah bentuk formal dari ～に伴って yang sering muncul di berita TV dan laporan.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat analisis tren: リモートワークが普及する___、郊外の住宅需要が高まっている。', '{"options":["に伴って","にもかかわらず","ざるを得ず","かねない"],"translation":"Seiring dengan meluasnya kerja jarak jauh, permintaan hunian di pinggiran kota semakin meningkat.","sentence_template":"リモートワークが普及する[blank]、郊外の住宅需要が高まっている。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, 'Verba bentuk kamus (普及する) + に伴って menyatakan korelasi perubahan yang paralel.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan penjelasan analis industri. Apa konsekuensi dari digitalisasi perbankan?', '{"audio_text":"キャッシュレス決済の拡大に伴って、実店舗の数を削減する金融機関が増えている。","options":[{"id":"opt_1","text":"Bank membuka lebih banyak cabang fisik di pedesaan"},{"id":"opt_2","text":"Penggunaan uang tunai meningkat dua kali lipat"},{"id":"opt_3","text":"Makin banyak lembaga keuangan mengurangi jumlah kantor cabang fisik"},{"id":"opt_4","text":"Transaksi daring dibatasi hanya pada hari kerja"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '実店舗の数を削減する berarti mengurangi jumlah cabang fisik seiring meluasnya pembayaran nontunai.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Risiko keamanan yang menyertai sistem baru harus segera ditangani."', '{"tokens":["に伴う","対処","ならない。","にあたり","新システム導入","リスクに","しなければ","に伴って"],"target_translation":"Risiko keamanan yang menyertai sistem baru harus segera ditangani.","romaji":"Shin shisutemu dounyuu ni tomonau risuku ni taisho shinakereba naranai."}'::jsonb, '["新システム導入","に伴う","リスクに","対処","しなければ","ならない。"]'::jsonb, 'に伴う + kata benda (リスク) menyatakan risiko yang menyertai suatu tindakan.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan cuaca dan transportasi. Mengapa jadwal kereta diubah?', '{"audio_text":"台風の接近に伴い、午後の新幹線は大幅な減便と運転見合わせが予定されています。","options":[{"id":"opt_1","text":"Karena adanya perbaikan rel rutin bulanan"},{"id":"opt_2","text":"Karena mendekatnya topan sehingga jadwal shinkansen dikurangi atau dihentikan sementara"},{"id":"opt_3","text":"Karena lonjakan penumpang pada hari libur nasional"},{"id":"opt_4","text":"Karena pemogokan masinis di stasiun pusat"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '台風の接近に伴い berarti seiring mendekatnya topan; 減便 berarti pengurangan frekuensi perjalanan.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Seiring dengan bertambahnya usia, perhatian terhadap kesehatan semakin meningkat."', '{"tokens":["重ねる","健康への","高まっている。","に限らず、","年齢を","に伴って、","関心が","重ねた"],"target_translation":"Seiring dengan bertambahnya usia, perhatian terhadap kesehatan semakin meningkat.","romaji":"Nenrei o kasaneru ni tomonatte, kenkou e no kanshin ga takamatte iru."}'::jsonb, '["年齢を","重ねる","に伴って、","健康への","関心が","高まっている。"]'::jsonb, '年齢を重ねる (bertambah usia) + に伴って menggunakan verba bentuk kamus.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 人口の減少___、地方の公共交通機関の維持が困難になりつつある。', '{"options":["に伴い","にあたり","の上で","かねず"],"translation":"Seiring dengan menurunnya populasi, pemeliharaan transportasi umum di daerah menjadi semakin sulit.","sentence_template":"人口の減少[blank]、地方の公共交通機関の維持が困難になりつつある。"}'::jsonb, '{"selected":"に伴い"}'::jsonb, '人口の減少に伴い menunjukkan perubahan struktural yang berjalan beriringan.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring dengan perluasan bisnis, jumlah karyawan baru juga bertambah."', '{"display_text":"事業の拡大に伴って、新入社員の数も増えています。","romaji":"Jigyou no kakudai ni tomonatte, shinnyuu shain no kazu mo fuete imasu.","phonetic_breakdown":["じぎょうの","かくだいに","ともなって","しんにゅうしゃいんの","かずも","ふえています"]}'::jsonb, '{"expected_transcript":"事業の拡大に伴って、新入社員の数も増えています。"}'::jsonb, '事業の拡大 (perluasan bisnis) berpasangan alami dengan ～に伴って.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat kebijakan berikut: 法律の改正___手続きの変更点について、資料にまとめました。', '{"options":["に伴う","に伴って","にあたって","つつある"],"translation":"Saya telah merangkum poin-poin perubahan prosedur yang menyertai revisi undang-undang ke dalam materi.","sentence_template":"法律の改正[blank]手続きの変更点について、資料にまとめました。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, 'Karena langsung memodifikasi frasa nominal 手続きの変更点, bentuk yang benar adalah に伴う.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar pakar energi. Perubahan apa yang sedang terjadi?', '{"audio_text":"電気自動車の普及に伴い、全国各地で急速充電器の設置が急ピッチで進んでいる。","options":[{"id":"opt_1","text":"Pembangunan stasiun pengisian cepat di seluruh negeri berlangsung pesat"},{"id":"opt_2","text":"Harga bahan bakar bensin turun ke titik terendah"},{"id":"opt_3","text":"Penjualan mobil listrik dilarang di wilayah pegunungan"},{"id":"opt_4","text":"Pemerintah menghentikan subsidi kendaraan ramah lingkungan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '急速充電器の設置が急ピッチで進んでいる berarti pemasangan pengisi daya cepat berlangsung dengan tempo tinggi.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Seiring dengan naiknya biaya hidup, banyak keluarga meninjau ulang pengeluaran."', '{"tokens":["上昇","多くの家庭が","見直している。","にもかかわらず、","物価の","に伴い、","支出を","見直す"],"target_translation":"Seiring dengan naiknya biaya hidup, banyak keluarga meninjau ulang pengeluaran.","romaji":"Bukka no joushou ni tomonai, ooku no katei ga shishutsu o minaoshite iru."}'::jsonb, '["物価の","上昇","に伴い、","多くの家庭が","支出を","見直している。"]'::jsonb, '物価の上昇に伴い menyatakan dampak langsung inflasi terhadap anggaran rumah tangga.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami menanggung biaya pengiriman yang menyertai pengembalian barang rusak."', '{"display_text":"不良品の返品に伴う送料は、弊社が負担いたします。","romaji":"Furyouhin no henpin ni tomonau souryou wa, heisha ga futan itashimasu.","phonetic_breakdown":["ふりょうひんの","へんぴんに","ともなう","そうりょうは","へいしゃが","ふたんいたします"]}'::jsonb, '{"expected_transcript":"不良品の返品に伴う送料は、弊社が負担いたします。"}'::jsonb, '返品に伴う送料 (ongkos kirim yang menyertai retur) adalah frasa standar layanan pelanggan Jepang.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 都市部への人口___に伴い、住宅価格の高騰が続いている。', '{"options":["集中","分散","解散","撤収"],"translation":"Seiring dengan terkonsentrasinya populasi ke wilayah perkotaan, lonjakan harga rumah terus berlanjut.","sentence_template":"都市部への人口[blank]に伴い、住宅価格の高騰が続いている。"}'::jsonb, '{"selected":"集中"}'::jsonb, '人口集中 (konsentrasi penduduk) adalah istilah demografi penting di JLPT N2.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring dengan kemajuan teknologi medis, angka harapan hidup rata-rata meningkat."', '{"display_text":"医療技術の進歩に伴って、平均寿命が延びています。","romaji":"Iryou gijutsu no shinpo ni tomonatte, heikin jumyou ga nobite imasu.","phonetic_breakdown":["いりょうぎじゅつの","しんぽに","ともなって","へいきんじゅみょうが","のびています"]}'::jsonb, '{"expected_transcript":"医療技術の進歩に伴って、平均寿命が延びています。"}'::jsonb, '平均寿命が延びる (angka harapan hidup meningkat) adalah kolokasi berita yang akurat.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa hubungan sebab-akibat yang disampaikan?', '{"audio_text":"スマートフォンの普及に伴って、新聞の購読者数は年々減少している。","options":[{"id":"opt_1","text":"Jumlah pembaca koran meningkat karena ponsel"},{"id":"opt_2","text":"Ponsel tidak berpengaruh pada penjualan koran"},{"id":"opt_3","text":"Jumlah pelanggan koran menurun tiap tahun seiring meluasnya ponsel pintar"},{"id":"opt_4","text":"Perusahaan koran berhenti beroperasi mulai bulan depan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '普及に伴って menghubungkan penyebaran smartphone dengan penurunan pelanggan koran (購読者数).', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi frasa nominal berikut: 移転___経費は、来期の予算に組み込む予定だ。', '{"options":["に伴う","に伴って","にあたり","に限らず"],"translation":"Biaya yang menyertai relokasi direncanakan akan dimasukkan ke dalam anggaran periode berikutnya.","sentence_template":"移転[blank]経費は、来期の予算に組み込む予定だ。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, 'に伴う memodifikasi kata benda 経費 (biaya/pengeluaran).', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Seiring dengan pertumbuhan ekonomi, konsumsi energi meningkat tajam."', '{"tokens":["成長","エネルギー消費が","した。","急増する","経済の","に伴って、","急増","にあたって、"],"target_translation":"Seiring dengan pertumbuhan ekonomi, konsumsi energi meningkat tajam.","romaji":"Keizai no seichou ni tomonatte, enerugii shouhi ga kyuuzou shita."}'::jsonb, '["経済の","成長","に伴って、","エネルギー消費が","急増","した。"]'::jsonb, '成長に伴って + 急増した menggambarkan lonjakan konsumsi energi.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan kereta. Apa yang terjadi saat jam sibuk?', '{"audio_text":"ダイヤ改正に伴い、平日の通勤時間帯に急行列車が三本増発されます。","options":[{"id":"opt_1","text":"Tiga kereta ekspres tambahan dioperasikan pada jam komuter hari kerja"},{"id":"opt_2","text":"Semua kereta ekspres dihapus pada hari kerja"},{"id":"opt_3","text":"Tarif tiket komuter dinaikkan tiga kali lipat"},{"id":"opt_4","text":"Stasiun ditutup lebih awal pada hari kerja"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '増発されます berarti jumlah keberangkatan kereta ditambah.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 気温が低下する___、暖房器具の売れ行きが伸びてきた。', '{"options":["に伴って","にもかかわらず","わけにはいかず","ざるを得ず"],"translation":"Seiring dengan turunnya suhu udara, penjualan alat pemanas mulai meningkat.","sentence_template":"気温が低下する[blank]、暖房器具の売れ行きが伸びてきた。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, '気温が低下する (suhu menurun) + に伴って menyatakan perubahan paralel pada penjualan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring dengan globalisasi, permintaan terhadap tenaga kerja multibahasa meningkat."', '{"display_text":"グローバル化に伴い、多言語人材の需要が高まっています。","romaji":"Guroobaruka ni tomonai, tagengo jinzai no juyou ga takamatte imasu.","phonetic_breakdown":["ぐろーばるかに","ともない","たげんごじんざいの","じゅようが","たかまっています"]}'::jsonb, '{"expected_transcript":"グローバル化に伴い、多言語人材の需要が高まっています。"}'::jsonb, '多言語人材 (SDM multibahasa) adalah istilah umum dalam rekrutmen perusahaan Jepang.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan singkat ini. Apa dampak dari perubahan iklim yang dibahas?', '{"audio_text":"気候変動の深刻化に伴い、農作物の収穫量が不安定になる地域が増えている。","options":[{"id":"opt_1","text":"Hasil panen di seluruh dunia meningkat stabil"},{"id":"opt_2","text":"Makin banyak wilayah mengalami ketidakstabilan hasil panen akibat perubahan iklim"},{"id":"opt_3","text":"Harga hasil pertanian menjadi gratis di daerah pedesaan"},{"id":"opt_4","text":"Petani beralih sepenuhnya ke sektor perikanan"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '収穫量が不安定になる berarti hasil panen menjadi tidak stabil.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Pekerjaan tambahan yang menyertai perubahan spesifikasi sedang kami hitung ulang."', '{"tokens":["に伴う","再計算","います。","にあたって","仕様変更","追加作業を","して","に伴って"],"target_translation":"Pekerjaan tambahan yang menyertai perubahan spesifikasi sedang kami hitung ulang.","romaji":"Shiyou henkou ni tomonau tsuika sagyou o saikeisan shite imasu."}'::jsonb, '["仕様変更","に伴う","追加作業を","再計算","して","います。"]'::jsonb, '仕様変更に伴う追加作業 (pekerjaan tambahan akibat perubahan spesifikasi) sangat khas dunia IT/proyek.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi artikel budaya berikut: 日本のアニメは若者___、幅広い世代から支持されている。', '{"options":["に限らず","にあたって","に伴って","かねない"],"translation":"Anime Jepang tidak terbatas pada kaum muda saja, melainkan didukung oleh berbagai generasi.","sentence_template":"日本のアニメは若者[blank]、幅広い世代から支持されている。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '～に限らず menyatakan cakupan yang luas (bukan hanya A, tetapi juga B).', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk laporan bisnis: このサービスは法人___、個人事業主にも広く利用されている。', '{"options":["に限らず","にもかかわらず","ざるを得ず","つつあり"],"translation":"Layanan ini tidak terbatas pada badan hukum, tetapi juga digunakan secara luas oleh pelaku usaha perorangan.","sentence_template":"このサービスは法人[blank]、個人事業主にも広く利用されている。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '法人 (badan usaha/perusahaan) dikontraskan perluasannya dengan 個人事業主 (pekerja mandiri/UMKM).', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan iklan aplikasi belajar berikut. Siapa target pengguna aplikasi tersebut?', '{"audio_text":"この語学アプリは初心者のみに限らず、ビジネスで実践的な会話力を磨きたい上級者にも対応しています。","options":[{"id":"opt_1","text":"Hanya khusus untuk siswa sekolah dasar"},{"id":"opt_2","text":"Hanya untuk penerjemah profesional bersertifikat"},{"id":"opt_3","text":"Tidak hanya pemula, tetapi juga pembelajar tingkat mahir untuk bisnis"},{"id":"opt_4","text":"Khusus untuk wisatawan yang berkunjung kurang dari seminggu"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '初心者のみに限らず berarti tidak hanya terbatas pada pemula saja.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Masalah lingkungan tidak terbatas pada satu negara, melainkan isu seluruh dunia."', '{"tokens":["一国","世界中の","だ。","にあたって、","環境問題は","に限らず、","課題","に伴って、"],"target_translation":"Masalah lingkungan tidak terbatas pada satu negara, melainkan isu seluruh dunia.","romaji":"Kankyou mondai wa ikkoku ni kagirazu, sekaijuu no kadai da."}'::jsonb, '["環境問題は","一国","に限らず、","世界中の","課題","だ。"]'::jsonb, '一国に限らず (tidak terbatas pada satu negara) sangat sering muncul di bacaan opini N2.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Produk ini tidak hanya populer di Jepang, tetapi juga di Asia Tenggara."', '{"display_text":"この商品は日本国内に限らず、東南アジアでも人気を集めています。","romaji":"Kono shouhin wa Nihon kokunai ni kagirazu, Tounan Ajia demo ninki o atsumete imasu.","phonetic_breakdown":["このしょうひんは","にほんこくないに","かぎらず","とうなんあじあでも","にんきを","あつめています"]}'::jsonb, '{"expected_transcript":"この商品は日本国内に限らず、東南アジアでも人気を集めています。"}'::jsonb, '人気を集める (menarik popularitas) + ～に限らず adalah struktur presentasi produk yang efektif.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 週末___、平日の夜もこの図書館は多くの利用者でにぎわっている。', '{"options":["に限らず","にあたり","の上で","わけにはいかず"],"translation":"Tidak hanya akhir pekan, pada malam hari kerja pun perpustakaan ini ramai oleh banyak pengunjung.","sentence_template":"週末[blank]、平日の夜もこの図書館は多くの利用者でにぎわっている。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '週末に限らず diikuti 平日の夜も (bahkan malam hari kerja pun) untuk memperluas jangkauan waktu.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan wawancara kepala HRD. Kriteria apa yang dicari perusahaan?', '{"audio_text":"弊社では学歴や国籍に限らず、主体的に課題解決へ取り組める人材を採用しています。","options":[{"id":"opt_1","text":"Hanya menerima lulusan universitas negeri di Tokyo"},{"id":"opt_2","text":"Merekrut talenta yang proaktif memecahkan masalah tanpa memandang latar pendidikan atau kewarganegaraan"},{"id":"opt_3","text":"Hanya merekrut pelamar dengan pengalaman kerja di atas sepuluh tahun"},{"id":"opt_4","text":"Membatasi rekrutmen hanya untuk bidang teknik mesin"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '学歴や国籍に限らず berarti tidak terbatas pada latar belakang pendidikan atau kewarganegaraan.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Keterampilan komunikasi penting tidak hanya dalam penjualan, tetapi juga di bidang teknik."', '{"tokens":["営業","技術職でも","だ。","にもかかわらず、","コミュニケーション能力は","に限らず、","重要","に伴う"],"target_translation":"Keterampilan komunikasi penting tidak hanya dalam penjualan, tetapi juga di bidang teknik.","romaji":"Komyunikeeshon nouryoku wa eigyou ni kagirazu, gijutsushoku demo juuyou da."}'::jsonb, '["コミュニケーション能力は","営業","に限らず、","技術職でも","重要","だ。"]'::jsonb, '営業に限らず、技術職でも memperluas lingkup pentingnya keterampilan komunikasi.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman festival kota. Siapa yang boleh berpartisipasi?', '{"audio_text":"地域の防災訓練は地元住民に限らず、市内に通勤・通学している方ならどなたでも参加できます。","options":[{"id":"opt_1","text":"Warga setempat maupun siapa saja yang bekerja atau bersekolah di kota tersebut"},{"id":"opt_2","text":"Hanya petugas pemadam kebakaran profesional"},{"id":"opt_3","text":"Hanya pemilik rumah yang tinggal lebih dari lima tahun"},{"id":"opt_4","text":"Hanya mahasiswa asing yang tinggal di asrama"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '地元住民に限らず memperluas peserta kepada pekerja dan pelajar komuter di kota tersebut.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Bukan hanya musim panas, tetapi sepanjang tahun kita perlu menjaga asupan cairan."', '{"tokens":["に限らず、","水分補給を","べきだ。","心がけた","夏","一年中","心がける","にあたって、"],"target_translation":"Bukan hanya musim panas, tetapi sepanjang tahun kita perlu menjaga asupan cairan.","romaji":"Natsu ni kagirazu, ichinenjuu suibun hokyuu o kokorogakeru beki da."}'::jsonb, '["夏","に限らず、","一年中","水分補給を","心がける","べきだ。"]'::jsonb, '夏に限らず (tidak hanya musim panas) + 一年中 (sepanjang tahun) menunjukkan perluasan waktu.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang sesuai: 近年は都市部___、地方でも空き家を活用したカフェが増えている。', '{"options":["に限らず","に伴い","かねず","つつあり"],"translation":"Belakangan ini, tidak terbatas pada wilayah perkotaan, di daerah pun kafe yang memanfaatkan rumah kosong makin bertambah.","sentence_template":"近年は都市部[blank]、地方でも空き家を活用したカフェが増えている。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '都市部に限らず、地方でも menyajikan perluasan geografis.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Olahraga ini dapat dinikmati oleh siapa saja, tanpa terbatas usia maupun gender."', '{"display_text":"このスポーツは年齢や性別に限らず、誰でも気軽に楽しめます。","romaji":"Kono supootsu wa nenrei ya seibetsu ni kagirazu, dare demo kigaru ni tanoshimemasu.","phonetic_breakdown":["このすぽーつは","ねんれいや","せいべつに","かぎらず","だれでも","きがるにたのしめます"]}'::jsonb, '{"expected_transcript":"このスポーツは年齢や性別に限らず、誰でも気軽に楽しめます。"}'::jsonb, '年齢や性別に限らず adalah ungkapan inklusif yang sangat lazim dalam brosur layanan.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat akademis: 歴史研究においては、文献資料___現地調査も欠かせない。', '{"options":["に限らず","にあたって","ざるを得ず","わけにはいかず"],"translation":"Dalam penelitian sejarah, tidak hanya dokumen tertulis, survei lapangan pun tidak boleh terlewatkan.","sentence_template":"歴史研究においては、文献資料[blank]現地調査も欠かせない。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '文献資料に限らず、現地調査も menegaskan keduanya sama-sama esensial.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan penjelasan pustakawan. Fasilitas apa yang tersedia di lantai dua?', '{"audio_text":"二階の学習スペースは紙の書籍に限らず、電子ジャーナルや映像資料も自由に閲覧できます。","options":[{"id":"opt_1","text":"Hanya menyediakan koran harian lokal"},{"id":"opt_2","text":"Ditutup sementara untuk renovasi"},{"id":"opt_3","text":"Khusus untuk ruang makan siang mahasiswa"},{"id":"opt_4","text":"Menyediakan akses buku cetak, jurnal elektronik, serta materi video"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '紙の書籍に限らず diikuti 電子ジャーナルや映像資料も (juga jurnal elektronik dan materi video).', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tidak hanya bahasa Inggris, kemampuan bahasa Jepang juga membuka peluang karier luas."', '{"tokens":["に限らず、","キャリアの","広げる。","広げた","英語","日本語の能力も","可能性を","に伴って、"],"target_translation":"Tidak hanya bahasa Inggris, kemampuan bahasa Jepang juga membuka peluang karier luas.","romaji":"Eigo ni kagirazu, Nihongo no nouryoku mo kyaria no kanousei o hirogeru."}'::jsonb, '["英語","に限らず、","日本語の能力も","キャリアの","可能性を","広げる。"]'::jsonb, '英語に限らず、日本語の能力も menghubungkan dua hal yang sama-sama memberi manfaat.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak hanya kualitas produk, layanan purnajual juga menentukan kepercayaan pelanggan."', '{"display_text":"製品の品質に限らず、アフターサービスも顧客の信頼を左右します。","romaji":"Seihin no hinshitsu ni kagirazu, afutaa saabisu mo kokyaku no shinrai o sayuu shimasu.","phonetic_breakdown":["せいひんの","ひんしつに","かぎらず","あふたーさーびすも","こきゃくのしんらいを","さゆうします"]}'::jsonb, '{"expected_transcript":"製品の品質に限らず、アフターサービスも顧客の信頼を左右します。"}'::jsonb, '信頼を左右する berarti sangat menentukan kepercayaan pelanggan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: この映画は国内に限らず、海外でも高い___を得ている。', '{"options":["評価","欠陥","延期","制限"],"translation":"Film ini tidak hanya di dalam negeri, tetapi di luar negeri pun mendapat penilaian tinggi.","sentence_template":"この映画は国内に限らず、海外でも高い[blank]を得ている。"}'::jsonb, '{"selected":"評価"}'::jsonb, '高い評価を得る (mendapatkan penilaian/apresiasi tinggi) adalah kolokasi umum N2.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Toko ini menyediakan bahan makanan organik dari berbagai wilayah di seluruh negeri."', '{"display_text":"当店では地元産に限らず、全国各地の有機食材を取り揃えております。","romaji":"Touten dewa jimotosan ni kagirazu, zenkoku kakuchi no yuuki shokuzai o torisoroete orimasu.","phonetic_breakdown":["とうてんでは","じもとさんに","かぎらず","ぜんこくかくちの","ゆうきしょくざいを","とりそろえております"]}'::jsonb, '{"expected_transcript":"当店では地元産に限らず、全国各地の有機食材を取り揃えております。"}'::jsonb, '取り揃えております adalah bentuk rendah hati/sopan yang umum di dunia ritel Jepang.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa makna utama yang ingin ditekankan pembicara?', '{"audio_text":"健康管理は高齢者に限らず、働き盛りの世代にとっても最優先課題だ。","options":[{"id":"opt_1","text":"Hanya lansia yang perlu menjaga kesehatan"},{"id":"opt_2","text":"Generasi usia produktif tidak perlu memikirkan kesehatan"},{"id":"opt_3","text":"Manajemen kesehatan adalah prioritas utama bagi lansia maupun generasi usia produktif"},{"id":"opt_4","text":"Pemerintah hanya menanggung biaya kesehatan lansia"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '高齢者に限らず memperluas subjek kepada 働き盛りの世代 (generasi usia produktif).', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 災害対策は地震___、水害や停電への備えも含めるべきだ。', '{"options":["に限らず","にあたり","に伴って","かねない"],"translation":"Penanggulangan bencana tidak terbatas pada gempa bumi, melainkan harus mencakup kesiapan menghadapi banjir dan pemadaman listrik.","sentence_template":"災害対策は地震[blank]、水害や停電への備えも含めるべきだ。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '地震に限らず + 水害や停電への備えも menunjukkan cakupan mitigasi yang komprehensif.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tidak hanya perusahaan besar, usaha kecil pun mulai menerapkan kerja fleksibel."', '{"tokens":["に限らず、","フレックス制度が","いる。","広がった","大企業","中小企業でも","広がって","にもかかわらず、"],"target_translation":"Tidak hanya perusahaan besar, usaha kecil pun mulai menerapkan kerja fleksibel.","romaji":"Daikigyou ni kagirazu, chuushou kigyou demo furekkusu seido ga hirogatte iru."}'::jsonb, '["大企業","に限らず、","中小企業でも","フレックス制度が","広がって","いる。"]'::jsonb, '大企業に限らず、中小企業でも adalah pasangan kontras-perluasan klasik di bacaan bisnis.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan informasi kursus memasak. Menu apa saja yang diajarkan?', '{"audio_text":"この料理教室では和食に限らず、イタリアンやエスニック料理の基本も学べます。","options":[{"id":"opt_1","text":"Hanya masakan tradisional Kyoto"},{"id":"opt_2","text":"Masakan Jepang, serta dasar-dasar masakan Italia dan etnik"},{"id":"opt_3","text":"Hanya pembuatan kue kering dan roti"},{"id":"opt_4","text":"Hanya teknik memotong ikan untuk koki profesional"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '和食に限らず diikuti イタリアンやエスニック料理の基本も.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 音楽は言葉の壁を越えて、国籍___人々の心を結びつける。', '{"options":["に限らず","にあたって","ざるを得ず","の上で"],"translation":"Musik melampaui batas bahasa dan menyatukan hati manusia tanpa terbatas kewarganegaraan.","sentence_template":"音楽は言葉の壁を越えて、国籍[blank]人々の心を結びつける。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '国籍に限らず menegaskan keberlakuan universal tanpa batas negara.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak hanya di musim semi, taman ini juga indah saat musim gugur."', '{"display_text":"この公園は春に限らず、紅葉の季節も見事な景色が楽しめます。","romaji":"Kono kouen wa haru ni kagirazu, kouyou no kisetsu mo migoto na keshiki ga tanoshimemasu.","phonetic_breakdown":["このこうえんは","はるに","かぎらず","こうようのきせつも","みごとなけしきが","たのしめます"]}'::jsonb, '{"expected_transcript":"この公園は春に限らず、紅葉の季節も見事な景色が楽しめます。"}'::jsonb, '紅葉 (kouyou) adalah dedaunan musim gugur; 見事な景色 berarti pemandangan menakjubkan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar pengamat teknologi. Apa kesimpulannya?', '{"audio_text":"サイバー攻撃の標的は大手IT企業に限らず、病院や自治体にも広がっている。","options":[{"id":"opt_1","text":"Serangan siber kini menyasar bukan hanya perusahaan IT besar, melainkan juga rumah sakit dan pemda"},{"id":"opt_2","text":"Hanya perusahaan IT besar yang pernah mengalami serangan siber"},{"id":"opt_3","text":"Rumah sakit sepenuhnya aman dari ancaman peretasan"},{"id":"opt_4","text":"Pemerintah daerah tidak menggunakan sistem digital"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '大手IT企業に限らず、病院や自治体にも広がっている menjelaskan perluasan target ancaman.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tidak hanya membaca buku, berdiskusi dengan orang lain juga memperdalam pemahaman."', '{"tokens":["に限らず、","理解を","ことができる。","深めた","読書","他人との議論も","深める","にあたり、"],"target_translation":"Tidak hanya membaca buku, berdiskusi dengan orang lain juga memperdalam pemahaman.","romaji":"Dokusho ni kagirazu, tanin to no giron mo rikai o fukameru koto ga dekiru."}'::jsonb, '["読書","に限らず、","他人との議論も","理解を","深める","ことができる。"]'::jsonb, '読書に限らず + 他人との議論も memperluas metode belajar.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat etika kerja berikut: 顧客から預かった機密情報を外部に漏らす___。', '{"options":["わけにはいかない","に伴っている","に限らない","つつある"],"translation":"Tidak mungkin boleh membocorkan informasi rahasia yang dipercayakan klien ke pihak luar.","sentence_template":"顧客から預かった機密情報を外部に漏らす[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, 'V-dict + わけにはいかない menyatakan larangan kuat berdasarkan etika atau tanggung jawab.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk kewajiban moral: 責任者として、この不具合を解決しない___。', '{"options":["わけにはいかない","にあたらない","かねない","に伴わない"],"translation":"Sebagai penanggung jawab, mau tidak mau saya harus menyelesaikan gangguan ini.","sentence_template":"責任者として、この不具合を解決しない[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, 'V-nai + わけにはいかない berarti ''tidak bisa tidak melakukan / mau tidak mau harus melakukan''.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan kerja. Mengapa pembicara tidak bisa pulang cepat hari ini?', '{"audio_text":"明日の朝一番で重要なプレゼンがあるので、資料が完成するまでは帰るわけにはいかないんだ。","options":[{"id":"opt_1","text":"Karena kereta terakhir sudah berangkat"},{"id":"opt_2","text":"Karena ada presentasi penting besok pagi sehingga harus menyelesaikan materi dulu"},{"id":"opt_3","text":"Karena sedang menunggu paket pribadi di kantor"},{"id":"opt_4","text":"Karena atasan melarang semua karyawan pulang sebelum tengah malam"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '帰るわけにはいかない menyatakan tidak bisa pulang karena tanggung jawab presentasi besok pagi.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah berjanji kepada klien, kami tidak mungkin menunda pengiriman."', '{"tokens":["約束した以上、","遅らせる","いかない。","かねない。","顧客と","納期を","わけには","遅らせた"],"target_translation":"Karena sudah berjanji kepada klien, kami tidak mungkin menunda pengiriman.","romaji":"Kokyaku to yakusoku shita ijou, nouki o okuraseru wake ni wa ikanai."}'::jsonb, '["顧客と","約束した以上、","納期を","遅らせる","わけには","いかない。"]'::jsonb, '納期を遅らせるわけにはいかない berarti tidak mungkin bisa menunda tenggat pengiriman.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun lelah, saya tidak bisa menyerah di tengah jalan."', '{"display_text":"どんなに疲れていても、途中で諦めるわけにはいきません。","romaji":"Donna ni tsukarete itemo, tochuu de akirameru wake ni wa ikimasen.","phonetic_breakdown":["どんなに","つかれていても","とちゅうで","あきらめる","わけにはいきません"]}'::jsonb, '{"expected_transcript":"どんなに疲れていても、途中で諦めるわけにはいきません。"}'::jsonb, '途中で諦めるわけにはいきません mencerminkan tekad dan tanggung jawab kuat.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: せっかく上司が誘ってくれたのだから、参加しない___。', '{"options":["わけにはいかない","つつある","にもかかわらず","にあたって"],"translation":"Karena atasan sudah susah payah mengajak, mau tidak mau saya harus ikut hadir.","sentence_template":"せっかく上司が誘ってくれたのだから、参加しない[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, '参加しないわけにはいかない (V-nai + わけにはいかない) menyatakan tidak enak jika tidak hadir, sehingga harus ikut.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pernyataan kepala tim. Mengapa mereka tetap melanjutkan proyek tersebut?', '{"audio_text":"ここまで多額の予算と時間を投じてきた以上、今さら計画を白紙に戻すわけにはいかない。","options":[{"id":"opt_1","text":"Karena belum ada biaya yang dikeluarkan sama sekali"},{"id":"opt_2","text":"Karena seluruh anggota tim ingin mengambil cuti panjang"},{"id":"opt_3","text":"Karena sudah menginvestasikan banyak dana dan waktu sehingga tidak mungkin membatalkan rencana"},{"id":"opt_4","text":"Karena pemerintah memerintahkan penutupan proyek"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '白紙に戻すわけにはいかない berarti tidak mungkin membatalkan rencana kembali dari nol.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena besok ada ujian penting, malam ini saya tidak boleh begadang."', '{"tokens":["試験があるので、","夜更かしする","いかない。","ざるを得ない。","明日重要な","今夜は","わけには","夜更かしした"],"target_translation":"Karena besok ada ujian penting, malam ini saya tidak boleh begadang.","romaji":"Ashita juuyou na shiken ga aru node, konya wa yofukashi suru wake ni wa ikanai."}'::jsonb, '["明日重要な","試験があるので、","今夜は","夜更かしする","わけには","いかない。"]'::jsonb, '夜更かしするわけにはいかない menyatakan tidak bisa begadang demi ujian besok.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan dialog di rumah sakit. Mengapa dokter tidak bisa meninggalkan ruangan sekarang?', '{"audio_text":"患者さんの容体が安定するまでは、担当医としてこの場を離れるわけにはまいりません。","options":[{"id":"opt_1","text":"Dokter sedang menunggu hasil pemeriksaan laboratorium pasien lain"},{"id":"opt_2","text":"Sebagai dokter penanggung jawab, beliau tidak bisa meninggalkan tempat sebelum kondisi pasien stabil"},{"id":"opt_3","text":"Dokter lupa membawa kunci kendaraan pribadi"},{"id":"opt_4","text":"Pintu ruang perawatan sedang rusak"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '～わけにはまいりません adalah bentuk sangat sopan (kenjougo) dari ～わけにはいきません.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Sebagai wakil perusahaan, saya tidak mungkin bersikap tidak sopan kepada tamu."', '{"tokens":["お客様に","取る","いかない。","に限らない。","会社の代表として、","失礼な態度を","わけには","取った"],"target_translation":"Sebagai wakil perusahaan, saya tidak mungkin bersikap tidak sopan kepada tamu.","romaji":"Kaisha no daihyou toshite, okyakusama ni shitsurei na taido o toru wake ni wa ikanai."}'::jsonb, '["会社の代表として、","お客様に","失礼な態度を","取る","わけには","いかない。"]'::jsonb, '取るわけにはいかない menyatakan larangan kuat karena peran sebagai wakil perusahaan.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: みんなが期待してくれているのに、簡単に引き下がる___。', '{"options":["わけにはいかない","に伴わない","にあたり","かねない"],"translation":"Padahal semua orang menaruh harapan, tidak mungkin saya mundur begitu saja.","sentence_template":"みんなが期待してくれているのに、簡単に引き下がる[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, '簡単に引き下がるわけにはいかない menunjukkan rasa tanggung jawab terhadap ekspektasi tim.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena ini adalah rahasia perusahaan, saya tidak bisa menceritakannya kepada siapa pun."', '{"display_text":"これは社外秘ですので、誰にも話すわけにはいきません。","romaji":"Kore wa shagaihi desu node, dare ni mo hanasu wake ni wa ikimasen.","phonetic_breakdown":["これは","しゃがいひですので","だれにも","はなす","わけにはいきません"]}'::jsonb, '{"expected_transcript":"これは社外秘ですので、誰にも話すわけにはいきません。"}'::jsonb, '社外秘 (rahasia internal perusahaan) berpasangan tepat dengan 話すわけにはいきません.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 親友の結婚式なのだから、どんなに忙しくても出席___。', '{"options":["しないわけにはいかない","するわけにはいかない","しかねない","しつつある"],"translation":"Karena ini pernikahan sahabat dekat, sesibuk apa pun mau tidak mau saya harus hadir.","sentence_template":"親友の結婚式なのだから、どんなに忙しくても出席[blank]。"}'::jsonb, '{"selected":"しないわけにはいかない"}'::jsonb, '出席しないわけにはいかない menggunakan bentuk negatif + わけにはいかない untuk makna ''harus hadir''.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan penjelasan manajer operasional. Apa sikap beliau terhadap keluhan pelanggan?', '{"audio_text":"いただいたご指摘はもっともなので、早急に改善策を講じないわけにはいきません。","options":[{"id":"opt_1","text":"Mengabaikan keluhan karena bukan kesalahan perusahaan"},{"id":"opt_2","text":"Menunda perbaikan hingga pergantian tahun"},{"id":"opt_3","text":"Menyerahkan seluruh keluhan kepada perusahaan lain"},{"id":"opt_4","text":"Merasa wajib segera mengambil langkah perbaikan karena masukan tersebut sangat masuk akal"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '改善策を講じないわけにはいきません berarti mau tidak mau harus segera mengambil langkah perbaikan.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun gaji kecil, saya tidak bisa mengabaikan keselamatan kerja."', '{"tokens":["限られていても、","おろそかにする","いかない。","に伴って、","予算が","安全管理を","わけには","おろそかにした"],"target_translation":"Meskipun gaji kecil, saya tidak bisa mengabaikan keselamatan kerja.","romaji":"Yosan ga kagira rete itemo, anzen kanri o orosoka ni suru wake ni wa ikanai."}'::jsonb, '["予算が","限られていても、","安全管理を","おろそかにする","わけには","いかない。"]'::jsonb, 'おろそかにするわけにはいかない berarti tidak boleh mengabaikan/melalaikan.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah menerima kepercayaan sebesar ini, saya tidak mungkin mengecewakan mereka."', '{"display_text":"これほど信頼を寄せていただいた以上、期待を裏切るわけにはいきません。","romaji":"Kore hodo shinrai o yosete itadaita ijou, kitai o uragiru wake ni wa ikimasen.","phonetic_breakdown":["これほど","しんらいをよせていただいた","いじょう","きたいをうらぎる","わけにはいきません"]}'::jsonb, '{"expected_transcript":"これほど信頼を寄せていただいた以上、期待を裏切るわけにはいきません。"}'::jsonb, '期待を裏切る (mengecewakan harapan) + わけにはいきません adalah ungkapan komitmen tinggi N2.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 会社の信用に関わる問題なので、曖昧なまま___するわけにはいかない。', '{"options":["放置","達成","歓迎","契約"],"translation":"Karena ini masalah yang menyangkut kredibilitas perusahaan, tidak mungkin membiarkannya begitu saja tanpa kejelasan.","sentence_template":"会社の信用に関わる問題なので、曖昧なまま[blank]するわけにはいかない。"}'::jsonb, '{"selected":"放置"}'::jsonb, '放置する (membiarkan/menelantarkan) sering dipakai bersama わけにはいかない dalam konteks tanggung jawab.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya tidak bisa menolak permintaan tolong dari senior yang selalu membimbing saya."', '{"display_text":"いつもお世話になっている先輩の頼みは、断るわけにはいきません。","romaji":"Itsumo osewa ni natte iru senpai no tanomi wa, kotowaru wake ni wa ikimasen.","phonetic_breakdown":["いつも","おせわになっている","せんぱいのたのみは","ことわる","わけにはいきません"]}'::jsonb, '{"expected_transcript":"いつもお世話になっている先輩の頼みは、断るわけにはいきません。"}'::jsonb, '断るわけにはいきません mengekspresikan rasa sungkan dan tanggung jawab sosial di budaya kerja Jepang.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Mengapa pembicara tetap pergi ke kantor?', '{"audio_text":"少し熱があるけれど、今日の会議の司会を任されているので休むわけにはいかない。","options":[{"id":"opt_1","text":"Karena pembicara ditugaskan menjadi moderator rapat hari ini sehingga tidak bisa absen"},{"id":"opt_2","text":"Karena pembicara sama sekali tidak merasa sakit"},{"id":"opt_3","text":"Karena tidak ada dokter yang buka hari ini"},{"id":"opt_4","text":"Karena rapat hari ini sudah dibatalkan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '休むわけにはいかない menunjukkan rasa tanggung jawab meski sedang kurang sehat.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan bentuk yang tepat: 約束の時間が迫っているから、もうこれ以上待つ___。', '{"options":["わけにはいかない","にあたらない","に伴わない","つつある"],"translation":"Karena waktu janji sudah semakin mepet, kita tidak bisa menunggu lebih lama lagi.","sentence_template":"約束の時間が迫っているから、もうこれ以上待つ[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, 'もうこれ以上待つわけにはいかない berarti kondisi tidak lagi memungkinkan untuk menunggu.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah menerima subsidi, kita harus melaporkan penggunaan dana dengan transparan."', '{"tokens":["受けたからには、","報告しない","いかない。","かねない。","補助金を","使途を","わけには","報告する"],"target_translation":"Karena sudah menerima subsidi, kita harus melaporkan penggunaan dana dengan transparan.","romaji":"Hojokin o uketa kara ni wa, shito o houkoku shinai wake ni wa ikanai."}'::jsonb, '["補助金を","受けたからには、","使途を","報告しない","わけには","いかない。"]'::jsonb, '報告しないわけにはいかない menegaskan kewajiban pelaporan akuntabel.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar pelatih tim nasional. Apa pesan utamanya?', '{"audio_text":"地元のファンの前で、情けない試合を見せるわけにはいかないんです。","options":[{"id":"opt_1","text":"Pelatih ingin membatalkan pertandingan kandang"},{"id":"opt_2","text":"Pelatih tidak peduli dengan hasil pertandingan"},{"id":"opt_3","text":"Pelatih merasa tidak boleh menampilkan permainan buruk di hadapan pendukung tuan rumah"},{"id":"opt_4","text":"Pelatih meminta penonton pulang lebih awal"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '情けない試合を見せるわけにはいかない berarti tidak boleh menunjukkan pertandingan yang memalukan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 借りた本に書き込みをする___。', '{"options":["わけにはいかない","ざるを得ない","に限らず","の上で"],"translation":"Tidak mungkin boleh menulis coretan di buku yang dipinjam.","sentence_template":"借りた本に書き込みをする[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, '書き込みをするわけにはいかない menyatakan larangan etis terhadap barang pinjaman.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebagai anggota tim, saya tidak bisa hanya berpangku tangan melihat rekan kesulitan."', '{"display_text":"チームの一員として、仲間の苦労を黙って見ているわけにはいきません。","romaji":"Chiimu no ichiin toshite, nakama no kurou o damatte mite iru wake ni wa ikimasen.","phonetic_breakdown":["ちーむの","いちいんとして","なかまのくろうを","だまってみている","わけにはいきません"]}'::jsonb, '{"expected_transcript":"チームの一員として、仲間の苦労を黙って見ているわけにはいきません。"}'::jsonb, '黙って見ているわけにはいきません berarti tidak bisa hanya diam menonton.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ucapan negosiator berikut. Mengapa mereka tidak menerima tawaran harga tersebut?', '{"audio_text":"原価を下回る価格では、いくらお得意様であってもお引き受けするわけにはまいりません。","options":[{"id":"opt_1","text":"Karena stok barang sudah habis terjual"},{"id":"opt_2","text":"Karena harga di bawah modal tidak mungkin diterima meski untuk pelanggan setia"},{"id":"opt_3","text":"Karena pengiriman ke luar kota sedang dihentikan"},{"id":"opt_4","text":"Karena pelanggan membatalkan pesanan secara sepihak"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '原価を下回る (di bawah biaya modal) menjadi alasan objektif untuk menolak secara sopan (お引き受けするわけにはまいりません).', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena besok harus menyetir jauh, malam ini saya tidak boleh minum alkohol."', '{"tokens":["運転するので、","お酒を飲む","いかない。","にもかかわらず、","明日長距離","今夜は","わけには","お酒を飲んだ"],"target_translation":"Karena besok harus menyetir jauh, malam ini saya tidak boleh minum alkohol.","romaji":"Ashita choukyori unten suru node, konya wa osake o nomu wake ni wa ikanai."}'::jsonb, '["明日長距離","運転するので、","今夜は","お酒を飲む","わけには","いかない。"]'::jsonb, 'お酒を飲むわけにはいかない menyatakan larangan jelas demi keselamatan berkendara.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi laporan bisnis berikut: 原材料費の高騰が続いており、来月から商品価格を改定___。', '{"options":["せざるを得ない","するにあたらない","するに限らず","しつつある"],"translation":"Karena lonjakan biaya bahan baku terus berlanjut, mau tidak mau kami terpaksa menyesuaikan harga produk mulai bulan depan.","sentence_template":"原材料費の高騰が続いており、来月から商品価格を改定[blank]。"}'::jsonb, '{"selected":"せざるを得ない"}'::jsonb, 'Untuk kata kerja golongan 3 (する), bentuk yang benar adalah せざるを得ない.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 悪天候のため、屋外での記念式典は中止___結果となった。', '{"options":["せざるを得ない","しざるを得ない","すざるを得ない","さざるを得ない"],"translation":"Akibat cuaca buruk, hasilnya upacara peringatan di luar ruangan terpaksa harus dibatalkan.","sentence_template":"悪天候のため、屋外での記念式典は中止[blank]結果となった。"}'::jsonb, '{"selected":"せざるを得ない"}'::jsonb, 'Ingat aturan penting JLPT N2: する berubah menjadi せざるを得ない (bukan しざる).', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan penerbangan. Keputusan apa yang terpaksa diambil?', '{"audio_text":"機材の整備に想定以上の時間を要するため、本日の最終便は欠航とせざるを得なくなりました。","options":[{"id":"opt_1","text":"Penerbangan terakhir hari ini terpaksa dibatalkan karena perawatan pesawat memakan waktu lebih lama dari perkiraan"},{"id":"opt_2","text":"Penerbangan terakhir dipercepat satu jam dari jadwal"},{"id":"opt_3","text":"Semua penumpang dipindahkan ke kelas bisnis secara gratis"},{"id":"opt_4","text":"Bandara ditutup selama satu bulan penuh"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '欠航とせざるを得なくなりました berarti terpaksa harus membatalkan penerbangan.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena kekurangan bukti, penyelidikan kasus tersebut terpaksa dihentikan."', '{"tokens":["その事件の","打ち切ら","得なかった。","かねなかった。","証拠不足のため、","捜査は","ざるを","打ち切る"],"target_translation":"Karena kekurangan bukti, penyelidikan kasus tersebut terpaksa dihentikan.","romaji":"Shouko fusoku no tame, sono jiken no sousa wa uchikirazaru o enakatta."}'::jsonb, '["証拠不足のため、","その事件の","捜査は","打ち切ら","ざるを","得なかった。"]'::jsonb, '打ち切る (menghentikan) -> bentuk nai tanpa い (打ち切ら) + ざるを得なかった.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mengingat kondisi anggaran saat ini, kami terpaksa menunda rencana ekspansi."', '{"display_text":"現在の予算状況を考えると、拡大計画は延期せざるを得ません。","romaji":"Genzai no yosan joukyou o kangaeru to, kakudai keikaku wa enki sezaru o emasen.","phonetic_breakdown":["げんざいの","よさんじょうきょうを","かんがえると","かくだいけいかくは","えんきせざるをえません"]}'::jsonb, '{"expected_transcript":"現在の予算状況を考えると、拡大計画は延期せざるを得ません。"}'::jsonb, '延期せざるを得ません menyampaikan keputusan berat secara profesional dan objektif.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: これだけ明確なデータを見せられては、自分の誤りを認め___。', '{"options":["ざるを得ない","かねない","に伴わない","にあたらない"],"translation":"Setelah diperlihatkan data sejelas ini, mau tidak mau saya terpaksa mengakui kesalahan saya sendiri.","sentence_template":"これだけ明確なデータを見せられては、自分の誤りを認め[blank]。"}'::jsonb, '{"selected":"ざるを得ない"}'::jsonb, '認める (golongan 2) -> 認め + ざるを得ない.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar manajer pabrik. Mengapa lini produksi dihentikan sementara?', '{"audio_text":"部品の供給が完全に止まってしまったため、工場の稼働を一時停止せざるを得ない状況です。","options":[{"id":"opt_1","text":"Karena semua pekerja sedang mengikuti pelatihan"},{"id":"opt_2","text":"Karena listrik di seluruh kota padam total"},{"id":"opt_3","text":"Karena pasokan suku cadang terhenti total sehingga operasional pabrik terpaksa dihentikan sementara"},{"id":"opt_4","text":"Karena permintaan produk menurun drastis"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '部品の供給が完全に止まってしまった (pasokan suku cadang terhenti total) memaksa penghentian operasional.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun enggan, demi keselamatan warga jalan tersebut terpaksa ditutup."', '{"tokens":["住民の安全のために","閉鎖","得なかった。","に限らず、","不本意ながら、","その道路は","せざるを","しざるを"],"target_translation":"Meskipun enggan, demi keselamatan warga jalan tersebut terpaksa ditutup.","romaji":"Fuhoni nagara, juumin no anzen no tame ni sono douro wa heisa sezaru o enakatta."}'::jsonb, '["不本意ながら、","住民の安全のために","その道路は","閉鎖","せざるを","得なかった。"]'::jsonb, '閉鎖する -> 閉鎖せざるを得なかった menyatakan tindakan terpaksa demi keselamatan.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pernyataan direktur keuangan. Langkah apa yang terpaksa dilakukan perusahaan?', '{"audio_text":"赤字が続いている不採算部門については、年内に撤退せざるを得ないと判断しました。","options":[{"id":"opt_1","text":"Menambah anggaran untuk divisi yang merugi"},{"id":"opt_2","text":"Memindahkan kantor pusat ke luar negeri"},{"id":"opt_3","text":"Merekrut seratus karyawan baru untuk divisi tersebut"},{"id":"opt_4","text":"Memutuskan terpaksa mundur dari divisi yang terus merugi sebelum akhir tahun"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '撤退せざるを得ない berarti terpaksa harus menarik diri/menutup lini bisnis.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena kereta berhenti akibat kecelakaan, saya terpaksa naik taksi ke kantor."', '{"tokens":["事故で止まったので、","出社","得なかった。","わけにはいかなかった。","電車が","タクシーで","せざるを","出社する"],"target_translation":"Karena kereta berhenti akibat kecelakaan, saya terpaksa naik taksi ke kantor.","romaji":"Densha ga jiko de tomatta node, takushii de shussha sezaru o enakatta."}'::jsonb, '["電車が","事故で止まったので、","タクシーで","出社","せざるを","得なかった。"]'::jsonb, '出社する -> 出社せざるを得なかった menunjukkan tidak adanya pilihan transportasi lain.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 期限までに修正が間に合わず、納期の延長をお願い___。', '{"options":["せざるを得なかった","しざるを得なかった","するざるを得なかった","されざるを得なかった"],"translation":"Karena perbaikan tidak sempat selesai sebelum tenggat, kami terpaksa memohon perpanjangan jadwal pengiriman.","sentence_template":"期限までに修正が間に合わず、納期の延長をお願い[blank]。"}'::jsonb, '{"selected":"せざるを得なかった"}'::jsonb, 'お願いする adalah kata kerja する, sehingga bentuknya お願いせざるを得なかった.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena kondisi kesehatan keluarga, saya terpaksa mengajukan cuti panjang."', '{"display_text":"家族の体調不良のため、長期休暇を取らざるを得なくなりました。","romaji":"Kazoku no taichou furyou no tame, chouki kyuuka o torazaru o enaku narimashita.","phonetic_breakdown":["かぞくの","たいちょうふりょうのため","ちょうききゅうかを","とらざるを","えなくなりました"]}'::jsonb, '{"expected_transcript":"家族の体調不良のため、長期休暇を取らざるを得なくなりました。"}'::jsonb, '取る -> 取らざるを得なくなりました menggambarkan perubahan keadaan yang memaksa mengambil cuti.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 相手側の条件があまりに厳しく、今回の契約は見送ら___。', '{"options":["ざるを得なかった","わけにはいかなかった","かねなかった","つつあった"],"translation":"Karena syarat pihak lawan terlalu ketat, kami terpaksa melewatkan kontrak kali ini.","sentence_template":"相手側の条件があまりに厳しく、今回の契約は見送ら[blank]。"}'::jsonb, '{"selected":"ざるを得なかった"}'::jsonb, '見送る (melewatkan/menunda) -> 見送ら + ざるを得なかった.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan berita lokal. Mengapa toko buku legendaris itu tutup?', '{"audio_text":"建物の老朽化と後継者不足により、創業八十年の老舗書店も閉店せざるを得なくなった。","options":[{"id":"opt_1","text":"Karena gedung sudah tua dan tidak ada penerus usaha"},{"id":"opt_2","text":"Karena pemiliknya memenangkan undian besar"},{"id":"opt_3","text":"Karena lokasi toko akan dijadikan stasiun baru"},{"id":"opt_4","text":"Karena penjualan buku cetak meningkat terlalu cepat"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '建物の老朽化 (penuaan bangunan) dan 後継者不足 (kurangnya penerus) memaksa penutupan toko.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena bukti baru ditemukan, laporan sebelumnya terpaksa direvisi seluruhnya."', '{"tokens":["見つかったため、","全面修正","得ない。","にあたって、","新たな証拠が","以前の報告書は","せざるを","全面修正し"],"target_translation":"Karena bukti baru ditemukan, laporan sebelumnya terpaksa direvisi seluruhnya.","romaji":"Arata na shouko ga mitsukatta tame, izen no houkokusho wa zenmen shuusei sezaru o enai."}'::jsonb, '["新たな証拠が","見つかったため、","以前の報告書は","全面修正","せざるを","得ない。"]'::jsonb, '全面修正せざるを得ない berarti terpaksa melakukan revisi menyeluruh.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meski berat hati, kami terpaksa mengurangi jumlah peserta karena kapasitas ruangan terbatas."', '{"display_text":"心苦しいのですが、会場の都合上、定員を削減せざるを得ません。","romaji":"Kokorogurushii no desu ga, kaijou no tsugoujou, teiin o sakugen sezaru o emasen.","phonetic_breakdown":["こころぐるしいのですが","かいじょうのつごうじょう","ていいんを","さくげんせざるをえません"]}'::jsonb, '{"expected_transcript":"心苦しいのですが、会場の都合上、定員を削減せざるを得ません。"}'::jsonb, '心苦しいのですが (dengan berat hati) memperhalus penyampaian keputusan terpaksa ～せざるを得ません.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 人手不足が深刻化し、営業時間の___をせざるを得なくなった。', '{"options":["短縮","拡張","開催","祝賀"],"translation":"Kekurangan tenaga kerja makin parah sehingga jam operasional terpaksa dipersingkat.","sentence_template":"人手不足が深刻化し、営業時間の[blank]をせざるを得なくなった。"}'::jsonb, '{"selected":"短縮"}'::jsonb, '営業時間の短縮 (pemendekan jam operasional) adalah respons bisnis yang lazim saat kekurangan staf.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena kendala teknis yang mendadak, kami terpaksa mengganti jadwal presentasi."', '{"display_text":"急な技術トラブルにより、発表日程を変更せざるを得なくなりました。","romaji":"Kyuu na gijutsu toraburu ni yori, happyou nittei o henkou sezaru o enaku narimashita.","phonetic_breakdown":["きゅうな","ぎじゅつとらぶるにより","はっぴょうにっていを","へんこうせざるを","えなくなりました"]}'::jsonb, '{"expected_transcript":"急な技術トラブルにより、発表日程を変更せざるを得なくなりました。"}'::jsonb, '変更せざるを得なくなりました menyampaikan perubahan jadwal yang tidak terhindarkan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa nuansa perasaan pembicara?', '{"audio_text":"本当は続けたかったが、資金が尽きたため事業を畳まざるを得なかった。","options":[{"id":"opt_1","text":"Pembicara sangat senang menutup usahanya"},{"id":"opt_2","text":"Pembicara sebenarnya ingin melanjutkan, tetapi terpaksa menutup usaha karena dana habis"},{"id":"opt_3","text":"Pembicara menutup usaha karena ingin pindah profesi ke bidang seni"},{"id":"opt_4","text":"Pembicara masih memiliki banyak dana cadangan"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '畳まざるを得なかった (terpaksa menutup usaha) mengandung nuansa berat hati karena tidak ada pilihan lain.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan konjugasi yang benar: 法律で定められている以上、この規則に従わ___。', '{"options":["ざるを得ない","かねない","にあたらない","つつある"],"translation":"Selama sudah ditetapkan oleh undang-undang, mau tidak mau kita harus mematuhi aturan ini.","sentence_template":"法律で定められている以上、この規則に従わ[blank]。"}'::jsonb, '{"selected":"ざるを得ない"}'::jsonb, '従う (mematuhi) -> 従わ + ざるを得ない.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Karena kesalahan sistem, transaksi daring terpaksa dihentikan sementara."', '{"tokens":["オンライン取引を","せざるを","のです。","に限らず、","システム障害により、","一時中断","得なかった","しざるを"],"target_translation":"Karena kesalahan sistem, transaksi daring terpaksa dihentikan sementara.","romaji":"Shisutemu shoukai ni yori, onrain torihiki o ichiji chuudan sezaru o enakatta."}'::jsonb, '["システム障害により、","オンライン取引を","一時中断","せざるを","得なかった","のです。"]'::jsonb, '一時中断せざるを得なかった berarti terpaksa menghentikan sementara akibat gangguan sistem.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan cuaca. Keputusan apa yang diambil panitia maraton?', '{"audio_text":"激しい雷雨が予想されるため、選手の安全を最優先し、大会は中止せざるを得ないとの結論に達しました。","options":[{"id":"opt_1","text":"Lomba tetap dijalankan sesuai jadwal semula"},{"id":"opt_2","text":"Rute lomba diperpanjang dua kali lipat"},{"id":"opt_3","text":"Lomba terpaksa dibatalkan demi mengutamakan keselamatan pelari akibat badai petir"},{"id":"opt_4","text":"Lomba dipindahkan ke dalam gedung olahraga"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '中止せざるを得ないとの結論に達しました berarti mencapai kesimpulan terpaksa membatalkan acara.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: ほかに頼める人がいないので、自分で対応___。', '{"options":["せざるを得ない","しざるを得ない","するわけがない","しかねない"],"translation":"Karena tidak ada orang lain yang bisa dimintai tolong, terpaksa saya tangani sendiri.","sentence_template":"ほかに頼める人がいないので、自分で対応[blank]。"}'::jsonb, '{"selected":"せざるを得ない"}'::jsonb, '対応する -> 対応せざるを得ない.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena tidak ada alternatif lain, kami terpaksa menerima syarat tersebut."', '{"display_text":"他に選択肢がないため、その条件を受け入れざるを得ませんでした。","romaji":"Hoka ni sentakushi ga nai tame, sono jouken o ukeirezaru o emasen deshita.","phonetic_breakdown":["ほかに","せんたくしがないため","そのじょうけんを","うけいれざるを","えませんでした"]}'::jsonb, '{"expected_transcript":"他に選択肢がないため、その条件を受け入れざるを得ませんでした。"}'::jsonb, '受け入れる (menerima) -> 受け入れざるを得ませんでした.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan pengamat ekonomi. Apa penilaian beliau terhadap kebijakan tersebut?', '{"audio_text":"インフレを抑え込むためには、中央銀行も金利を引き上げざるを得ないだろう。","options":[{"id":"opt_1","text":"Bank sentral tidak perlu melakukan apa pun"},{"id":"opt_2","text":"Bank sentral akan menurunkan suku bunga hingga nol"},{"id":"opt_3","text":"Inflasi akan hilang sendiri tanpa kebijakan moneter"},{"id":"opt_4","text":"Bank sentral kemungkinan besar terpaksa menaikkan suku bunga untuk menekan inflasi"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '金利を引き上げざるを得ないだろう berarti mau tidak mau akan terpaksa menaikkan suku bunga.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Akibat gempa besar, ribuan warga terpaksa mengungsi ke tempat penampungan."', '{"tokens":["多くの住民が","避難","得なかった。","にもかかわらず、","大地震の影響で、","避難所へ","せざるを","避難する"],"target_translation":"Akibat gempa besar, ribuan warga terpaksa mengungsi ke tempat penampungan.","romaji":"Oojishin no eikyou de, ooku no juumin ga hinanjo e hinan sezaru o enakatta."}'::jsonb, '["大地震の影響で、","多くの住民が","避難所へ","避難","せざるを","得なかった。"]'::jsonb, '避難せざるを得なかった menggambarkan tindakan pengungsian yang terpaksa akibat bencana.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi berita berikut: 大雨警報が出ていた___、会場には予定通り多くの参加者が集まった。', '{"options":["にもかかわらず","にあたって","に伴って","の上で"],"translation":"Meskipun peringatan hujan deras telah dikeluarkan, banyak peserta tetap berkumpul di lokasi sesuai jadwal.","sentence_template":"大雨警報が出ていた[blank]、会場には予定通り多くの参加者が集まった。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, '～にもかかわらず menyatakan kontras tajam antara kondisi yang ada dan hasil yang terjadi di luar dugaan.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah kata sifat-na: 彼はまだ入社二年目___にもかかわらず、大型案件を見事にまとめ上げた。', '{"options":["である","な","に","を"],"translation":"Meskipun ia baru tahun kedua masuk perusahaan, ia berhasil merampungkan proyek berskala besar dengan gemilang.","sentence_template":"彼はまだ入社二年目[blank]にもかかわらず、大型案件を見事にまとめ上げた。"}'::jsonb, '{"selected":"である"}'::jsonb, 'Kata benda (入社二年目) dapat langsung diikuti にもかかわらず, atau dengan である + にもかかわらず dalam gaya formal.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan survei berikut. Fakta kontras apa yang ditemukan?', '{"audio_text":"何度も注意喚起を行ったにもかかわらず、不審メールの添付ファイルを開いてしまう事例が後を絶たない。","options":[{"id":"opt_1","text":"Tidak ada lagi karyawan yang membuka email mencurigakan"},{"id":"opt_2","text":"Meskipun sudah berkali-kali diperingatkan, kasus membuka lampiran email mencurigakan masih terus terjadi"},{"id":"opt_3","text":"Sistem email kantor dihapus sepenuhnya karena serangan siber"},{"id":"opt_4","text":"Karyawan tidak pernah menerima peringatan tentang keamanan data"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '注意喚起を行ったにもかかわらず (meski sudah diperingatkan) dikontraskan dengan 事例が後を絶たない (kasus tak kunjung berhenti).', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun usianya sudah lanjut, beliau masih aktif meneliti setiap hari."', '{"tokens":["にも","先生は毎日","続けている。","続けた。","高齢","かかわらず、","現役で研究を","に伴って、"],"target_translation":"Meskipun usianya sudah lanjut, beliau masih aktif meneliti setiap hari.","romaji":"Kourei ni mo kakawarazu, sensei wa mainichi geneki de kenkyuu o tsuzukete iru."}'::jsonb, '["高齢","にも","かかわらず、","先生は毎日","現役で研究を","続けている。"]'::jsonb, 'Kata benda 高齢 + にもかかわらず menyatakan kontras yang penuh rasa kagum.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun jadwal Anda sangat padat, terima kasih telah meluangkan waktu untuk hadir."', '{"display_text":"ご多忙にもかかわらず、ご出席いただき誠にありがとうございます。","romaji":"Gotabou ni mo kakawarazu, goshusseki itadaki makoto ni arigatou gozaimasu.","phonetic_breakdown":["ごたぼうに","もかかわらず","ごしゅっせきいただき","まことに","ありがとうございます"]}'::jsonb, '{"expected_transcript":"ご多忙にもかかわらず、ご出席いただき誠にありがとうございます。"}'::jsonb, 'ご多忙にもかかわらず adalah frasa pembuka sangat sopan yang wajib dikuasai di dunia kerja Jepang.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat analisis: 厳しい不況___、同社のクラウド事業は過去最高の売上を記録した。', '{"options":["にもかかわらず","に限らず","ざるを得ず","つつあり"],"translation":"Terlepas dari resesi ekonomi yang berat, bisnis cloud perusahaan tersebut mencatat penjualan tertinggi sepanjang masa.","sentence_template":"厳しい不況[blank]、同社のクラウド事業は過去最高の売上を記録した。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, 'Kata benda 不況 + にもかかわらず menyoroti kinerja luar biasa di tengah kondisi sulit.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan tanggapan pembaca berita. Apa yang mengherankan dari hasil pemilu daerah?', '{"audio_text":"事前の世論調査では苦戦が予想されていたにもかかわらず、新人候補が圧倒的な票差で当選した。","options":[{"id":"opt_1","text":"Kandidat baru itu mengundurkan diri sebelum pemungutan suara"},{"id":"opt_2","text":"Hasil pemilu sama persis dengan prediksi survei"},{"id":"opt_3","text":"Meski diprediksi kesulitan dalam survei sebelumnya, kandidat baru menang dengan selisih suara telak"},{"id":"opt_4","text":"Tingkat partisipasi pemilih hanya mencapai sepuluh persen"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '苦戦が予想されていたにもかかわらず dikontraskan dengan 圧倒的な票差で当選した.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun biayanya mahal, kualitas layanan hotel itu jauh di bawah harapan."', '{"tokens":["である","ホテルのサービスは","だった。","期待外れだ。","料金が高額","にもかかわらず、","期待外れ","にあたって、"],"target_translation":"Meskipun biayanya mahal, kualitas layanan hotel itu jauh di bawah harapan.","romaji":"Ryoukin ga kougaku de aru ni mo kakawarazu, hoteru no saabisu wa kitai hazure datta."}'::jsonb, '["料金が高額","である","にもかかわらず、","ホテルのサービスは","期待外れ","だった。"]'::jsonb, '高額であるにもかかわらず menonjolkan kekecewaan yang kontras dengan harga tinggi.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan diskusi dua analis. Apa masalah utama dari kebijakan subsidi tersebut?', '{"audio_text":"莫大な予算を投入したにもかかわらず、目標としていた出生率の回復には結びついていない。","options":[{"id":"opt_1","text":"Anggaran besar yang digelontorkan belum membuahkan pemulihan angka kelahiran sesuai target"},{"id":"opt_2","text":"Anggaran yang dialokasikan jauh lebih kecil dari tahun lalu"},{"id":"opt_3","text":"Angka kelahiran melonjak tajam melampaui target pemerintah"},{"id":"opt_4","text":"Kebijakan subsidi belum pernah dilaksanakan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '莫大な予算を投入したにもかかわらず (meski mengucurkan anggaran besar) kontras dengan 結びついていない.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun dilarang keras, masih saja ada pengunjung yang memotret di dalam galeri."', '{"tokens":["されている","写真を撮る","いる。","禁止した","厳しく禁止","にもかかわらず、","入場者が","に伴って、"],"target_translation":"Meskipun dilarang keras, masih saja ada pengunjung yang memotret di dalam galeri.","romaji":"Kibishiku kinshi sarete iru ni mo kakawarazu, shashin o toru nyuujousha ga iru."}'::jsonb, '["厳しく禁止","されている","にもかかわらず、","写真を撮る","入場者が","いる。"]'::jsonb, 'V-te iru + にもかかわらず menyatakan tindakan yang tetap terjadi meski dilarang.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 足元が悪い___、本日は遠方よりお越しいただき感謝申し上げます。', '{"options":["にもかかわらず","にあたり","に伴い","かねない"],"translation":"Meskipun kondisi jalan sedang kurang baik (hujan/licin), kami ucapkan terima kasih atas kehadiran Anda dari jauh hari ini.","sentence_template":"足元が悪い[blank]、本日は遠方よりお越しいただき感謝申し上げます。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, '足元が悪いにもかかわらず adalah ungkapan sambutan standar saat cuaca hujan di Jepang.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun baru pertama kali berkunjung ke Jepang, ia berbicara sangat fasih."', '{"display_text":"初めての来日にもかかわらず、とても流暢な日本語を話しますね。","romaji":"Hajimete no rainichi ni mo kakawarazu, totemo ryuuchou na Nihongo o hanashimasu ne.","phonetic_breakdown":["はじめての","らいにちに","もかかわらず","とてもりゅうちょうな","にほんごを","はなしますね"]}'::jsonb, '{"expected_transcript":"初めての来日にもかかわらず、とても流暢な日本語を話しますね。"}'::jsonb, '初めての来日 (kunjungan pertama ke Jepang) + にもかかわらず mengekspresikan kekaguman.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 十分な説明を受けた___、まだ納得していない社員が多いようだ。', '{"options":["にもかかわらず","の上で","に限らず","ざるを得ない"],"translation":"Meskipun telah menerima penjelasan yang memadai, tampaknya masih banyak karyawan yang belum merasa yakin.","sentence_template":"十分な説明を受けた[blank]、まだ納得していない社員が多いようだ。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, 'V-ta + にもかかわらず menunjukkan hasil yang berlawanan dari yang diharapkan setelah penjelasan.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan film. Mengapa kritikus terkesan dengan film independen itu?', '{"audio_text":"極めて限られた制作費で作られたにもかかわらず、映像美と脚本の完成度は大作に引けを取らない。","options":[{"id":"opt_1","text":"Karena film itu dibuat dengan anggaran terbesar tahun ini"},{"id":"opt_2","text":"Karena film itu hanya berdurasi lima menit"},{"id":"opt_3","text":"Karena seluruh pemerannya adalah aktor Hollywood terkenal"},{"id":"opt_4","text":"Karena meski dibuat dengan biaya sangat terbatas, keindahan visual dan naskahnya setara film besar"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '大作に引けを取らない berarti tidak kalah mutunya dibanding film beranggaran besar.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun sudah larut malam, lampu di ruang rapat masih menyala terang."', '{"tokens":["にも","会議室の明かりは","いる。","点いた。","深夜","かかわらず、","まだ点いて","にあたって、"],"target_translation":"Meskipun sudah larut malam, lampu di ruang rapat masih menyala terang.","romaji":"Shinya ni mo kakawarazu, kaigishitsu no akari wa mada tsuite iru."}'::jsonb, '["深夜","にも","かかわらず、","会議室の明かりは","まだ点いて","いる。"]'::jsonb, '深夜にもかかわらず menekankan suasana kerja lembur di luar jam wajar.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun sudah diperiksa berkali-kali, ternyata masih ada satu kesalahan ketik."', '{"display_text":"何度も確認したにもかかわらず、誤字が一箇所残っていました。","romaji":"Nando mo kakunin shita ni mo kakawarazu, goji ga ikkasho nokotte imashita.","phonetic_breakdown":["なんども","かくにんしたに","もかかわらず","ごじが","いっかしょ","のこっていました"]}'::jsonb, '{"expected_transcript":"何度も確認したにもかかわらず、誤字が一箇所残っていました。"}'::jsonb, '誤字 (salah ketik/aksara) sering dibahas dalam konteks penyuntingan dokumen kantor.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 懸命な___にもかかわらず、交渉は合意に至らなかった。', '{"options":["努力","休暇","風景","趣味"],"translation":"Meskipun telah dilakukan upaya sekuat tenaga, negosiasi tetap tidak mencapai kesepakatan.","sentence_template":"懸命な[blank]にもかかわらず、交渉は合意に至らなかった。"}'::jsonb, '{"selected":"努力"}'::jsonb, '懸命な努力 (upaya sekuat tenaga) adalah kolokasi alami dengan にもかかわらず.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun cuacanya dingin menusuk, antrean di depan toko sudah panjang sejak pagi."', '{"display_text":"厳しい寒さにもかかわらず、朝から店の前には長い列ができています。","romaji":"Kibishii samusa ni mo kakawarazu, asa kara mise no mae ni wa nagai retsu ga dekite imasu.","phonetic_breakdown":["きびしい","さむさに","もかかわらず","あさからみせのまえには","ながいれつが","できています"]}'::jsonb, '{"expected_transcript":"厳しい寒さにもかかわらず、朝から店の前には長い列ができています。"}'::jsonb, '厳しい寒さ (dingin yang menusuk) + にもかかわらず sangat alami untuk laporan berita.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Pernyataan mana yang benar?', '{"audio_text":"体調が優れないにもかかわらず、彼は責任感から会議に最後まで出席した。","options":[{"id":"opt_1","text":"Ia pulang lebih awal karena tidak enak badan"},{"id":"opt_2","text":"Ia tetap mengikuti rapat sampai selesai demi rasa tanggung jawab meski kondisinya kurang sehat"},{"id":"opt_3","text":"Ia sama sekali tidak hadir dalam rapat hari ini"},{"id":"opt_4","text":"Rapat dibatalkan karena kondisinya memburuk"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '体調が優れないにもかかわらず berarti meskipun kondisi badan sedang tidak prima.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 立地が不便___にもかかわらず、そのレストランは連日満席だ。', '{"options":["である","な","に","の"],"translation":"Meskipun lokasinya kurang strategis, restoran itu penuh pengunjung setiap hari.","sentence_template":"立地が不便[blank]にもかかわらず、そのレストランは連日満席だ。"}'::jsonb, '{"selected":"である"}'::jsonb, 'Kata sifat-na (不便) tidak memakai な sebelum にもかかわらず; gunakan 不便にもかかわらず atau 不便であるにもかかわらず.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun mendapat kritik keras, ia tidak mengubah pendiriannya."', '{"tokens":["浴びた","彼は主張を","なかった。","かねなかった。","厳しい批判を","にもかかわらず、","変え","浴びる"],"target_translation":"Meskipun mendapat kritik keras, ia tidak mengubah pendiriannya.","romaji":"Kibishii hihan o abita ni mo kakawarazu, kare wa shuchou o kaenakatta."}'::jsonb, '["厳しい批判を","浴びた","にもかかわらず、","彼は主張を","変え","なかった。"]'::jsonb, '批判を浴びる (dihujani kritik) + にもかかわらず menggambarkan keteguhan sikap.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan lalu lintas. Kondisi apa yang terjadi di jalan tol?', '{"audio_text":"三連休の初日にもかかわらず、現在のところ高速道路に大きな渋滞は発生していません。","options":[{"id":"opt_1","text":"Terjadi kemacetan parah sepanjang lima puluh kilometer"},{"id":"opt_2","text":"Jalan tol ditutup karena perbaikan jembatan"},{"id":"opt_3","text":"Meskipun hari pertama libur tiga hari berturut-turut, sejauh ini belum ada kemacetan besar"},{"id":"opt_4","text":"Semua gerbang tol digratiskan hari ini"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '三連休の初日にもかかわらず kontras dengan 大きな渋滞は発生していません.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 経験が浅い___、彼女は冷静にトラブルを処理した。', '{"options":["にもかかわらず","に伴って","にあたって","ざるを得ず"],"translation":"Meskipun pengalamannya masih minim, ia menangani masalah tersebut dengan tenang.","sentence_template":"経験が浅い[blank]、彼女は冷静にトラブルを処理した。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, 'Kata sifat-i (浅い) langsung tersambung ke にもかかわらず.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun waktunya singkat, kami berhasil menyelesaikan persiapan dengan rapi."', '{"display_text":"短い準備期間にもかかわらず、滞りなく開催することができました。","romaji":"Mijikai junbi kikan ni mo kakawarazu, todokoorinaku kaisai suru koto ga dekimashita.","phonetic_breakdown":["みじかい","じゅんびきかんに","もかかわらず","とどこおりなく","かいさいすることが","できました"]}'::jsonb, '{"expected_transcript":"短い準備期間にもかかわらず、滞りなく開催することができました。"}'::jsonb, '滞りなく (dengan lancar tanpa hambatan) adalah kosakata formal N2.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kutipan editorial berikut. Apa poin kritik penulis?', '{"audio_text":"安全性への懸念が解消されていないにもかかわらず、計画を強行する姿勢には疑問が残る。","options":[{"id":"opt_1","text":"Penulis mendukung penuh pelaksanaan rencana secepatnya"},{"id":"opt_2","text":"Semua kekhawatiran soal keamanan telah terjawab tuntas"},{"id":"opt_3","text":"Rencana tersebut sudah dibatalkan oleh pihak berwenang"},{"id":"opt_4","text":"Penulis mempertanyakan sikap memaksakan rencana meski kekhawatiran keamanan belum teratasi"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '懸念が解消されていないにもかかわらず (meski kekhawatiran belum terselesaikan) + 疑問が残る (menyisakan tanda tanya).', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun jaraknya jauh, banyak pelanggan tetap datang berkunjung dari luar prefektur."', '{"tokens":["にも","県外からも","訪れる。","訪れた。","遠方","かかわらず、","多くの客が","に限らず、"],"target_translation":"Meskipun jaraknya jauh, banyak pelanggan tetap datang berkunjung dari luar prefektur.","romaji":"Enpou ni mo kakawarazu, kengai kara mo ooku no kyaku ga otozureru."}'::jsonb, '["遠方","にも","かかわらず、","県外からも","多くの客が","訪れる。"]'::jsonb, '遠方にもかかわらず adalah ungkapan formal untuk menghargai kedatangan dari jauh.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 関係者全員と十分に協議した___、最終的な方針を決定したい。', '{"options":["上で","に伴って","に限らず","かねない"],"translation":"Setelah berdiskusi secara matang dengan semua pihak terkait, saya ingin menetapkan kebijakan final.","sentence_template":"関係者全員と十分に協議した[blank]、最終的な方針を決定したい。"}'::jsonb, '{"selected":"上で"}'::jsonb, 'V-ta + 上で menyatakan langkah A diselesaikan terlebih dahulu sebagai dasar sebelum melakukan B.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk penyambung yang tepat untuk konteks ''dalam hal'': 異文化を理解する___、相手の価値観を尊重する姿勢が大切だ。', '{"options":["上で","にあたらない","にもかかわらず","ざるを得ず"],"translation":"Dalam hal memahami lintas budaya, sikap menghormati nilai-nilai pihak lain sangatlah penting.","sentence_template":"異文化を理解する[blank]、相手の価値観を尊重する姿勢が大切だ。"}'::jsonb, '{"selected":"上で"}'::jsonb, 'V-dict + 上で berarti ''dalam hal / saat melakukan (tujuan tersebut)''.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan arahan staf administrasi. Apa yang harus dilakukan pelamar sebelum mengirim formulir?', '{"audio_text":"募集要項をよくお読みいただいた上で、必要書類を期限までにご提出ください。","options":[{"id":"opt_1","text":"Membaca panduan rekrutmen dengan saksama terlebih dahulu baru menyerahkan dokumen yang diperlukan"},{"id":"opt_2","text":"Mengirim dokumen kosong tanpa membaca panduan"},{"id":"opt_3","text":"Datang langsung ke kantor pusat tanpa membuat janji"},{"id":"opt_4","text":"Menunggu pengumuman hasil seleksi sebelum mendaftar"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'よくお読みいただいた上で menegaskan tindakan membaca panduan harus mendahului penyerahan dokumen.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setelah memeriksa isi kontrak secara teliti, saya menandatanganinya."', '{"tokens":["内容をよく","上で、","した。","に伴って、","契約書の","確認した","署名","確認する"],"target_translation":"Setelah memeriksa isi kontrak secara teliti, saya menandatanganinya.","romaji":"Keiyakusho no naiyou o yoku kakunin shita ue de, shomei shita."}'::jsonb, '["契約書の","内容をよく","確認した","上で、","署名","した。"]'::jsonb, '確認した上で (setelah memastikan) memakai bentuk lampau V-ta sebelum tindakan berikutnya.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam hal menjalankan proyek bersama, komunikasi yang terbuka sangat penting."', '{"display_text":"共同プロジェクトを進める上で、率直な意見交換が不可欠です。","romaji":"Kyoudou purojekuto o susumeru ue de, sotchoku na iken koukan ga fukaketsu desu.","phonetic_breakdown":["きょうどうぷろじぇくとを","すすめるうえで","そっちょくな","いけんこうかんが","ふかけつです"]}'::jsonb, '{"expected_transcript":"共同プロジェクトを進める上で、率直な意見交換が不可欠です。"}'::jsonb, '進める上で (dalam menjalankan) + 不可欠です (mutlak diperlukan) adalah struktur rapat formal N2.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 現地を実際に視察した___なければ、正確な判断は下せない。', '{"options":["上で","にあたり","に伴い","つつ"],"translation":"Jika tidak setelah meninjau lokasi secara langsung terlebih dahulu, penilaian yang akurat tidak dapat dibuat.","sentence_template":"現地を実際に視察した[blank]なければ、正確な判断は下せない。"}'::jsonb, '{"selected":"上で"}'::jsonb, '～た上でなければ berarti ''kecuali setelah melakukan A terlebih dahulu, B tidak mungkin terwujud''.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan saran dosen pembimbing. Apa yang perlu diperhatikan dalam menulis tesis?', '{"audio_text":"先行研究を徹底的に整理した上で、独自の視点を提示することが論文の質を高めます。","options":[{"id":"opt_1","text":"Mengabaikan seluruh penelitian terdahulu"},{"id":"opt_2","text":"Menulis kesimpulan sebelum mengumpulkan data"},{"id":"opt_3","text":"Merangkum penelitian terdahulu secara menyeluruh terlebih dahulu, baru menyajikan sudut pandang orisinal"},{"id":"opt_4","text":"Memperpendek jumlah halaman tesis hingga separuhnya"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '整理した上で (setelah menata/merangkum) menjadi landasan bagi 独自の視点を提示する.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dalam hal belajar bahasa asing, membiasakan diri mendengar setiap hari sangat efektif."', '{"tokens":["学ぶ","毎日聞く習慣が","だ。","にもかかわらず、","外国語を","上で、","効果的","学んだ"],"target_translation":"Dalam hal belajar bahasa asing, membiasakan diri mendengar setiap hari sangat efektif.","romaji":"Gaikokugo o manabu ue de, mainichi kiku shuukan ga kouka-teki da."}'::jsonb, '["外国語を","学ぶ","上で、","毎日聞く習慣が","効果的","だ。"]'::jsonb, '学ぶ上で (dalam hal mempelajari) menggunakan verba bentuk kamus.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan penjelasan bagian HRD. Bagaimana proses penentuan penempatan karyawan baru?', '{"audio_text":"本人の希望と適性を総合的に考慮した上で、配属先を決定いたします。","options":[{"id":"opt_1","text":"Penempatan ditentukan sepenuhnya secara acak lewat undian"},{"id":"opt_2","text":"Penempatan ditetapkan setelah mempertimbangkan minat dan kecocokan masing-masing secara menyeluruh"},{"id":"opt_3","text":"Karyawan baru memilih sendiri gaji sebelum wawancara"},{"id":"opt_4","text":"Semua karyawan baru ditempatkan di cabang luar negeri"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '総合的に考慮した上で berarti setelah mempertimbangkan secara komprehensif.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setelah berkonsultasi dengan keluarga, saya memutuskan menerima tawaran mutasi kerja."', '{"tokens":["相談した","転勤の辞令を","した。","に限らず、","家族と","上で、","受けることに","相談する"],"target_translation":"Setelah berkonsultasi dengan keluarga, saya memutuskan menerima tawaran mutasi kerja.","romaji":"Kazoku to soudan shita ue de, tenkin no jirei o ukeru koto ni shita."}'::jsonb, '["家族と","相談した","上で、","転勤の辞令を","受けることに","した。"]'::jsonb, '相談した上で (setelah berkonsultasi) diikuti keputusan akhir 受けることにした.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: リスクを十分に理解した___、投資を判断してください。', '{"options":["上で","にあたって","つつある","かねない"],"translation":"Setelah memahami risikonya dengan cukup baik, silakan putuskan investasi Anda.","sentence_template":"リスクを十分に理解した[blank]、投資を判断してください。"}'::jsonb, '{"selected":"上で"}'::jsonb, '理解した上で lazim muncul dalam ketentuan layanan keuangan dan kontrak.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam hal membangun kepercayaan, menepati janji kecil sekalipun sangatlah penting."', '{"display_text":"信頼関係を築く上で、小さな約束を守ることが何より大切です。","romaji":"Shinrai kankei o kizuku ue de, chiisana yakusoku o mamoru koto ga nani yori taisetsu desu.","phonetic_breakdown":["しんらいかんけいを","きずくうえで","ちいさなやくそくを","まもることが","なによりたいせつです"]}'::jsonb, '{"expected_transcript":"信頼関係を築く上で、小さな約束を守ることが何より大切です。"}'::jsonb, '信頼関係を築く上で berarti ''dalam hal membangun hubungan saling percaya''.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 複数の見積もりを比較検討した___、発注先を選定した。', '{"options":["上で","に伴い","に限らず","わけにはいかず"],"translation":"Setelah membandingkan dan menelaah beberapa penawaran harga, kami memilih vendor pemesanan.","sentence_template":"複数の見積もりを比較検討した[blank]、発注先を選定した。"}'::jsonb, '{"selected":"上で"}'::jsonb, '比較検討した上で (setelah membandingkan dan menelaah) adalah ungkapan pengadaan barang/bisnis.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan wawancara kepala koki. Apa kunci penting dalam mengelola restoran?', '{"audio_text":"飲食店を経営する上では、料理の味はもちろんですが、衛生管理の徹底が最も重要です。","options":[{"id":"opt_1","text":"Hanya desain interior yang menentukan kesuksesan restoran"},{"id":"opt_2","text":"Harga makanan harus selalu lebih murah dari pesaing"},{"id":"opt_3","text":"Lokasi restoran tidak memengaruhi jumlah pelanggan"},{"id":"opt_4","text":"Dalam mengelola restoran, selain rasa masakan, ketegasan manajemen kebersihan adalah yang terpenting"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '経営する上では (dalam hal mengelola usaha) menyoroti poin terpenting 衛生管理の徹底.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setelah menguji prototipe berkali-kali, kami memulai produksi massal."', '{"tokens":["何度も","上で、","開始した。","にもかかわらず、","試作品を","検証した","量産を","検証する"],"target_translation":"Setelah menguji prototipe berkali-kali, kami memulai produksi massal.","romaji":"Shisakuhin o nando mo kenshou shita ue de, ryousan o kaishi shita."}'::jsonb, '["試作品を","何度も","検証した","上で、","量産を","開始した。"]'::jsonb, '検証した上で (setelah memverifikasi/menguji) diikuti tahap produksi massal 量産を開始した.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah berdiskusi di internal perusahaan, kami akan menghubungi Anda kembali besok."', '{"display_text":"社内で検討いたしました上で、明日改めてご連絡いたします。","romaji":"Shanai de kentou itashimashita ue de, asu aratamete gorenraku itashimasu.","phonetic_breakdown":["しゃないで","けんとういたしました","うえで","あしたあらためて","ごれんらくいたします"]}'::jsonb, '{"expected_transcript":"社内で検討いたしました上で、明日改めてご連絡いたします。"}'::jsonb, '検討いたしました上で adalah balasan bisnis sangat sopan sebelum memberi jawaban resmi.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 現状の課題を正確に___した上で、改善計画を立てよう。', '{"options":["把握","廃止","撤退","欠席"],"translation":"Setelah memahami permasalahan saat ini secara akurat, mari kita susun rencana perbaikan.","sentence_template":"現状の課題を正確に[blank]した上で、改善計画を立てよう。"}'::jsonb, '{"selected":"把握"}'::jsonb, '把握する (haaku suru = memahami/menguasai situasi secara akurat) sangat sering dipasangkan dengan ～した上で.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam hal bekerja sama secara internasional, pemahaman budaya sangat membantu."', '{"display_text":"国際的に協働する上で、異文化への理解が大きな助けになります。","romaji":"Kokusaiteki ni kyoudou suru ue de, ibunka e no rikai ga ookina tasuke ni narimasu.","phonetic_breakdown":["こくさいてきに","きょうどうするうえで","いぶんかえのりかいが","おおきなたすけに","なります"]}'::jsonb, '{"expected_transcript":"国際的に協働する上で、異文化への理解が大きな助けになります。"}'::jsonb, '協働する (bekerja sama secara setara) + 上で cocok untuk konteks profesional global.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa urutan tindakan yang benar?', '{"audio_text":"医師の診断を受けた上で、適切な運動メニューを決めることにした。","options":[{"id":"opt_1","text":"Memeriksakan diri ke dokter dulu, baru menentukan menu olahraga yang sesuai"},{"id":"opt_2","text":"Langsung berolahraga berat tanpa berkonsultasi ke dokter"},{"id":"opt_3","text":"Berhenti berolahraga selamanya setelah bertemu dokter"},{"id":"opt_4","text":"Membuat menu olahraga dulu baru mencari dokter"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '診断を受けた上で menyatakan pemeriksaan dokter dilakukan terlebih dahulu.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan kata benda + の上で: 業務遂行___、何か問題があればすぐに報告してください。', '{"options":["の上で","にあたって","に伴って","に限らず"],"translation":"Dalam hal pelaksanaan tugas kerja, jika ada masalah apa pun mohon segera laporkan.","sentence_template":"業務遂行[blank]、何か問題があればすぐに報告してください。"}'::jsonb, '{"selected":"の上で"}'::jsonb, 'Kata benda (業務遂行) tersambung dengan の上で untuk makna ''dalam pelaksanaan...''.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dalam hal memelihara kesehatan, keseimbangan makan dan tidur sangat menentukan."', '{"tokens":["維持する","食事と睡眠の","重要だ。","かねない。","健康を","上で、","バランスが","維持した"],"target_translation":"Dalam hal memelihara kesehatan, keseimbangan makan dan tidur sangat menentukan.","romaji":"Kenkou o iji suru ue de, shokuji to suimin no baransu ga juuyou da."}'::jsonb, '["健康を","維持する","上で、","食事と睡眠の","バランスが","重要だ。"]'::jsonb, '維持する上で (dalam hal menjaga/memelihara) memakai verba bentuk kamus.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman bank. Apa syarat sebelum mengajukan pinjaman?', '{"audio_text":"将来の返済計画を無理なく立てた上で、お申し込みいただくようお願いしております。","options":[{"id":"opt_1","text":"Mengajukan pinjaman tanpa rencana pengembalian"},{"id":"opt_2","text":"Menyusun rencana pelunasan masa depan yang realistis terlebih dahulu sebelum mendaftar"},{"id":"opt_3","text":"Melunasi pinjaman dalam waktu satu hari"},{"id":"opt_4","text":"Menutup seluruh rekening tabungan sebelum mendaftar"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '無理なく立てた上で berarti setelah menyusun rencana secara realistis tanpa memaksakan diri.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 現場の意見を聞いた___、最終案を修正しました。', '{"options":["上で","つつ","かねず","ざるを得ず"],"translation":"Setelah mendengarkan pendapat dari lapangan, kami merevisi draf akhirnya.","sentence_template":"現場の意見を聞いた[blank]、最終案を修正しました。"}'::jsonb, '{"selected":"上で"}'::jsonb, '聞いた上で menunjukkan urutan mendengarkan masukan terlebih dahulu sebelum revisi.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah menimbang pro dan kontranya, kami memilih opsi yang paling aman."', '{"display_text":"利点と欠点を比較した上で、最も安全な方法を選びました。","romaji":"Riten to ketten o hikaku shita ue de, mottomo anzen na houhou o erabimashita.","phonetic_breakdown":["りてんとけってんを","ひかくしたうえで","もっともあんぜんな","ほうほうを","えらびました"]}'::jsonb, '{"expected_transcript":"利点と欠点を比較した上で、最も安全な方法を選びました。"}'::jsonb, '利点と欠点 (kelebihan dan kekurangan) + 比較した上で lazim dalam pengambilan keputusan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan arahan manajer IT. Apa langkah yang harus didahulukan?', '{"audio_text":"データのバックアップを完全に取った上で、システムのアップデートを実行してください。","options":[{"id":"opt_1","text":"Langsung memperbarui sistem tanpa cadangan data"},{"id":"opt_2","text":"Menghapus seluruh data lama sebelum pembaruan"},{"id":"opt_3","text":"Membuat cadangan data secara penuh terlebih dahulu, baru menjalankan pembaruan sistem"},{"id":"opt_4","text":"Mematikan server selama satu minggu"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'バックアップを完全に取った上で memastikan langkah pengamanan dilakukan sebelum pembaruan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dalam hal mengembangkan karier, terus memperbarui keterampilan adalah hal esensial."', '{"tokens":["伸ばす","スキルを磨き続ける","欠かせない。","にもかかわらず、","キャリアを","上で、","ことが","伸ばした"],"target_translation":"Dalam hal mengembangkan karier, terus memperbarui keterampilan adalah hal esensial.","romaji":"Kyaria o nobasu ue de, sukiru o migaki tsuzukeru koto ga kakasenai."}'::jsonb, '["キャリアを","伸ばす","上で、","スキルを磨き続ける","ことが","欠かせない。"]'::jsonb, '伸ばす上で (dalam hal mengembangkan karier) memakai bentuk kamus + 上で.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi artikel berita berikut: 再生可能エネルギーの導入が、世界規模で急速に広がり___。', '{"options":["つつある","かねない","わけにはいかない","ざるを得ない"],"translation":"Penerapan energi terbarukan sedang terus meluas dengan cepat dalam skala global.","sentence_template":"再生可能エネルギーの導入が、世界規模で急速に広がり[blank]。"}'::jsonb, '{"selected":"つつある"}'::jsonb, 'V-masu stem (広がり) + つつある menggambarkan proses perubahan yang sedang berlangsung secara bertahap.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk laporan pemulihan: 長引いていた景気低迷から、ようやく回復の兆しが見え___。', '{"options":["つつある","にあたっている","に限っている","の上である"],"translation":"Dari kelesuan ekonomi yang berkepanjangan, tanda-tanda pemulihan akhirnya mulai terus terlihat.","sentence_template":"長引いていた景気低迷から、ようやく回復の兆しが見え[blank]。"}'::jsonb, '{"selected":"つつある"}'::jsonb, '見えつつある menggambarkan perubahan positif yang mulai tampak secara progresif.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan berita ekonomi berikut. Perubahan apa yang sedang berlangsung di pasar kerja?', '{"audio_text":"従来の終身雇用制度が見直され、実力本位の評価システムへと移行しつつある。","options":[{"id":"opt_1","text":"Sistem kerja seumur hidup sedang ditinjau ulang dan beralih menuju sistem evaluasi berbasis kompetensi"},{"id":"opt_2","text":"Semua perusahaan mewajibkan karyawan bekerja di satu perusahaan seumur hidup"},{"id":"opt_3","text":"Sistem evaluasi kinerja dihapuskan di seluruh perusahaan"},{"id":"opt_4","text":"Gaji karyawan hanya ditentukan oleh lama masa kerja"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '移行しつつある berarti sedang bertransisi secara bertahap menuju sistem baru.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kesadaran masyarakat terhadap pengurangan sampah plastik sedang meningkat."', '{"tokens":["削減への","高まり","ある。","かねない。","プラスチックごみ","意識が","つつ","高まった"],"target_translation":"Kesadaran masyarakat terhadap pengurangan sampah plastik sedang meningkat.","romaji":"Purasuchikku gomi sakugen e no ishiki ga takamaritsutsu aru."}'::jsonb, '["プラスチックごみ","削減への","意識が","高まり","つつ","ある。"]'::jsonb, '高まる -> 高まりつつある menyatakan peningkatan kesadaran yang terus berlangsung.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kondisi pasien sedang berangsur-angsur membaik menuju pemulihan."', '{"display_text":"患者さんの容体は、順調に回復に向かいつつあります。","romaji":"Kanjasan no youdai wa, junchou ni kaifuku ni mukaitsutsu arimasu.","phonetic_breakdown":["かんじゃさんの","ようだいは","じゅんちょうに","かいふくに","むかいつつあります"]}'::jsonb, '{"expected_transcript":"患者さんの容体は、順調に回復に向かいつつあります。"}'::jsonb, '回復に向かいつつあります adalah ungkapan sopan dan akurat untuk progres pemulihan.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 地域の伝統工芸を受け継ぐ職人の数が、年々減り___のが現状だ。', '{"options":["つつある","かねない","にあたって","の上で"],"translation":"Kenyataannya saat ini jumlah pengrajin yang mewarisi kerajinan tradisional daerah terus berkurang dari tahun ke tahun.","sentence_template":"地域の伝統工芸を受け継ぐ職人の数が、年々減り[blank]のが現状だ。"}'::jsonb, '{"selected":"つつある"}'::jsonb, '減りつつある menggambarkan tren penurunan yang sedang berlangsung.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan pengamat teknologi. Apa yang terjadi pada layanan transportasi kota?', '{"audio_text":"自動運転バスの実証実験が進み、地方の移動手段のあり方が大きく変わりつつある。","options":[{"id":"opt_1","text":"Seluruh layanan bus daerah dihentikan permanen"},{"id":"opt_2","text":"Uji coba bus otonom ditolak oleh pemerintah"},{"id":"opt_3","text":"Bentuk transportasi di daerah sedang berubah besar seiring majunya uji coba bus otonom"},{"id":"opt_4","text":"Penumpang bus hanya boleh membayar dengan koin"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '大きく変わりつつある berarti sedang mengalami perubahan besar secara berkelanjutan.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Masalah kekurangan air di wilayah tersebut sedang menjadi semakin serius."', '{"tokens":["水不足は","深刻化","ある。","ざるを得ない。","その地域の","さらに","しつつ","深刻化した"],"target_translation":"Masalah kekurangan air di wilayah tersebut sedang menjadi semakin serius.","romaji":"Sono chiiki no mizubusoku wa sara ni shinkokuka shitsutsu aru."}'::jsonb, '["その地域の","水不足は","さらに","深刻化","しつつ","ある。"]'::jsonb, '深刻化する -> 深刻化しつつある menyatakan proses yang makin memburuk dari waktu ke waktu.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan lingkungan. Kondisi apa yang dilaporkan tentang gletser di kutub?', '{"audio_text":"地球温暖化の影響で、北極圏の氷がかつてない速さで溶けつつあると報告された。","options":[{"id":"opt_1","text":"Es di wilayah Arktik bertambah tebal setiap tahun"},{"id":"opt_2","text":"Dilaporkan bahwa es di wilayah Arktik sedang mencair dengan kecepatan yang belum pernah terjadi sebelumnya"},{"id":"opt_3","text":"Suhu di wilayah Arktik turun drastis tahun ini"},{"id":"opt_4","text":"Penelitian di wilayah Arktik dihentikan selama lima tahun"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '溶けつつある berarti sedang dalam proses mencair secara terus-menerus.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Pola konsumsi generasi muda sedang bergeser dari kepemilikan ke layanan berlangganan."', '{"tokens":["所有から","変化","ある。","わけにはいかない。","若者の消費は","利用へと","しつつ","変化する"],"target_translation":"Pola konsumsi generasi muda sedang bergeser dari kepemilikan ke layanan berlangganan.","romaji":"Wakamono no shouhi wa shoyuu kara riyou e to henka shitsutsu aru."}'::jsonb, '["若者の消費は","所有から","利用へと","変化","しつつ","ある。"]'::jsonb, '変化しつつある menggambarkan pergeseran tren konsumen yang sedang berjalan.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 長年の対立を経て、両国の関係はようやく改善に向かい___。', '{"options":["つつある","ざるを得ない","に限らず","にもかかわらず"],"translation":"Setelah perselisihan bertahun-tahun, hubungan kedua negara akhirnya sedang bergerak menuju perbaikan.","sentence_template":"長年の対立を経て、両国の関係はようやく改善に向かい[blank]。"}'::jsonb, '{"selected":"つつある"}'::jsonb, '向かう -> 向かいつつある menyatakan arah perubahan yang sedang terjadi.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Teknologi penerjemahan otomatis sedang berkembang pesat hingga mendekati tingkat alami."', '{"display_text":"自動翻訳の精度は、急速に向上しつつあります。","romaji":"Jidou honyaku no seido wa, kyuusoku ni koujou shitsutsu arimasu.","phonetic_breakdown":["じどうほんやくの","せいどは","きゅうそくに","こうじょうしつつ","あります"]}'::jsonb, '{"expected_transcript":"自動翻訳の精度は、急速に向上しつつあります。"}'::jsonb, '向上しつつあります (sedang terus meningkat) sering dipakai untuk perkembangan teknologi.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 紙の書類を廃止し、業務の完全デジタル化が定着___。', '{"options":["しつつある","するつつある","したつつある","せつつある"],"translation":"Dokumen kertas dihapus dan digitalisasi penuh operasional kerja sedang mulai mengakar.","sentence_template":"紙の書類を廃止し、業務の完全デジタル化が定着[blank]。"}'::jsonb, '{"selected":"しつつある"}'::jsonb, '定着する -> bentuk masu stem 定着し + つつある.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan berita sosial berikut. Tren apa yang sedang terjadi pada gaya hidup perkotaan?', '{"audio_text":"都会の喧騒を離れ、自然豊かな地方へ移住する若い世帯が増えつつある。","options":[{"id":"opt_1","text":"Semakin sedikit orang yang tertarik tinggal di daerah"},{"id":"opt_2","text":"Harga rumah di desa menjadi lebih mahal dari pusat kota"},{"id":"opt_3","text":"Pemerintah melarang warga pindah ke luar kota besar"},{"id":"opt_4","text":"Makin banyak keluarga muda yang sedang beralih pindah ke daerah yang kaya alam meninggalkan hiruk-pikuk kota"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '増えつつある menyatakan tren peningkatan yang sedang berlangsung saat ini.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kepercayaan konsumen terhadap merek tersebut perlahan sedang pulih kembali."', '{"tokens":["消費者の信頼は","戻り","ある。","かねない。","そのブランドへの","徐々に","つつ","戻った"],"target_translation":"Kepercayaan konsumen terhadap merek tersebut perlahan sedang pulih kembali.","romaji":"Sono burando e no shouhisha no shinrai wa joujou ni modoritsutsu aru."}'::jsonb, '["そのブランドへの","消費者の信頼は","徐々に","戻り","つつ","ある。"]'::jsonb, '徐々に戻りつつある berarti sedang berangsur-angsur kembali pulih.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kesalahpahaman di antara kedua tim akhirnya sedang mulai terurai."', '{"display_text":"両チームの間の誤解は、ようやく解消されつつあります。","romaji":"Ryou chiimu no aida no gokai wa, youyaku kaishou saretsutsu arimasu.","phonetic_breakdown":["りょうちーむの","あいだのごかいは","ようやく","かいしょうされつつ","あります"]}'::jsonb, '{"expected_transcript":"両チームの間の誤解は、ようやく解消されつつあります。"}'::jsonb, '解消されつつあります (bentuk pasif + つつある) berarti sedang berangsur-angsur terselesaikan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: オンライン診療の仕組みが全国で___しつつある。', '{"options":["定着","撤回","欠陥","延期"],"translation":"Sistem konsultasi medis daring sedang mulai mengakar/mapan di seluruh negeri.","sentence_template":"オンライン診療の仕組みが全国で[blank]しつつある。"}'::jsonb, '{"selected":"定着"}'::jsonb, '定着する (teichaku suru = mengakar/menjadi kebiasaan mapan) sangat cocok dengan ～つつある.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jumlah pengguna kendaraan ramah lingkungan sedang terus bertambah setiap tahun."', '{"display_text":"環境配慮型自動車の利用者が年々増加しつつあります。","romaji":"Kankyou hairyogata jidousha no riyousha ga nennen zouka shitsutsu arimasu.","phonetic_breakdown":["かんきょうはいりょがた","じどうしゃのりようしゃが","ねんねん","ぞうかしつつあります"]}'::jsonb, '{"expected_transcript":"環境配慮型自動車の利用者が年々増加しつつあります。"}'::jsonb, '増加しつつあります adalah padanan formal dari 増えてきている.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa yang sedang terjadi pada proyek tersebut?', '{"audio_text":"当初の遅れを取り戻し、開発プロジェクトは予定通りの完成に近づきつつある。","options":[{"id":"opt_1","text":"Proyek pengembangan sedang makin mendekati penyelesaian sesuai jadwal setelah mengejar ketertinggalan awal"},{"id":"opt_2","text":"Proyek pengembangan dibatalkan karena terlalu terlambat"},{"id":"opt_3","text":"Proyek belum dimulai sama sekali"},{"id":"opt_4","text":"Tim pengembang mengundurkan diri di tengah jalan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '完成に近づきつつある berarti sedang semakin mendekati tahap penyelesaian.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan konjugasi yang benar: 長年続いた習慣も、時代の変化とともに忘れられ___。', '{"options":["つつある","かねない","ざるを得ない","わけにはいかない"],"translation":"Kebiasaan yang berlangsung bertahun-tahun pun sedang perlahan terlupakan seiring perubahan zaman.","sentence_template":"長年続いた習慣も、時代の変化とともに忘れられ[blank]。"}'::jsonb, '{"selected":"つつある"}'::jsonb, '忘れられる (pasif) -> 忘れられつつある menyatakan proses pelupaan yang sedang terjadi.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Standar keselamatan pangan sedang diperketat di berbagai negara."', '{"tokens":["各国で","され","ある。","に限らず、","食品の安全基準は","厳格化","つつ","された"],"target_translation":"Standar keselamatan pangan sedang diperketat di berbagai negara.","romaji":"Shokuhin no anzen kijun wa kakkoku de genkakuka saretsutsu aru."}'::jsonb, '["食品の安全基準は","各国で","厳格化","され","つつ","ある。"]'::jsonb, '厳格化されつつある berarti sedang terus diperketat.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar ekonom. Bagaimana situasi ekspor kuartal ini?', '{"audio_text":"海外市場の需要回復を受け、製造業の輸出額は緩やかに持ち直しつつある。","options":[{"id":"opt_1","text":"Nilai ekspor manufaktur anjlok ke titik terendah"},{"id":"opt_2","text":"Nilai ekspor sektor manufaktur sedang pulih secara perlahan seiring membaiknya permintaan pasar luar negeri"},{"id":"opt_3","text":"Ekspor manufaktur dihentikan sementara"},{"id":"opt_4","text":"Pasar luar negeri tidak lagi membeli produk manufaktur"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '緩やかに持ち直しつつある berarti sedang membaik/pulih secara bertahap.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 都市部の空き家対策として、新しい活用法が広がり___。', '{"options":["つつある","にあたって","にもかかわらず","の上で"],"translation":"Sebagai langkah mengatasi rumah kosong di perkotaan, cara pemanfaatan baru sedang terus meluas.","sentence_template":"都市部の空き家対策として、新しい活用法が広がり[blank]。"}'::jsonb, '{"selected":"つつある"}'::jsonb, '広がりつつある menyatakan penyebaran yang progresif.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kesenjangan informasi antara kota besar dan daerah perlahan sedang mengecil."', '{"display_text":"都市と地方の情報格差は、少しずつ縮小しつつあります。","romaji":"Toshi to chihou no jouhou kakusa wa, sukoshizutsu shukushou shitsutsu arimasu.","phonetic_breakdown":["としとちほうの","じょうほうかくさは","すこしずつ","しゅくしょうしつつあります"]}'::jsonb, '{"expected_transcript":"都市と地方の情報格差は、少しずつ縮小しつつあります。"}'::jsonb, '縮小しつつあります berarti sedang berangsur-angsur menyusut/mengecil.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan penelitian berikut. Apa temuan utamanya?', '{"audio_text":"森林伐採の影響で、希少な野生動物の生息地が急速に失われつつある。","options":[{"id":"opt_1","text":"Populasi satwa liar langka meningkat drastis"},{"id":"opt_2","text":"Penebangan hutan telah berhenti sepenuhnya di seluruh dunia"},{"id":"opt_3","text":"Habitat satwa liar langka sedang hilang dengan cepat akibat penebangan hutan"},{"id":"opt_4","text":"Satwa liar langka dipindahkan semuanya ke kebun binatang"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '失われつつある menyatakan proses hilangnya habitat yang sedang berlangsung cepat.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Budaya kerja fleksibel sedang menyebar luas di kalangan perusahaan rintisan."', '{"tokens":["スタートアップ企業に","しつつ","ようだ。","かねない","柔軟な働き方が","浸透","ある","浸透した"],"target_translation":"Budaya kerja fleksibel sedang menyebar luas di kalangan perusahaan rintisan.","romaji":"Jyuunan na hatarakikata ga sutaatoappu kigyou ni shintou shitsutsu aru."}'::jsonb, '["柔軟な働き方が","スタートアップ企業に","浸透","しつつ","ある","ようだ。"]'::jsonb, '浸透しつつある (sedang meresap/menyebar luas) sering dipakai untuk budaya kerja baru.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat peringatan keselamatan berikut: わずかな確認ミスが、重大な事故を引き起こし___。', '{"options":["かねない","つつある","にあたらない","に限らない"],"translation":"Kesalahan pengecekan sekecil apa pun bisa saja memicu kecelakaan fatal.","sentence_template":"わずかな確認ミスが、重大な事故を引き起こし[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, 'V-masu stem (引き起こし) + かねない menyatakan kekhawatiran akan dampak negatif yang mungkin terjadi.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk peringatan bisnis: 対応を先延ばしにすれば、長年の顧客の信頼を失い___。', '{"options":["かねない","ざるを得ない","わけにはいかない","に伴う"],"translation":"Jika kita menunda-nunda penanganan, kita bisa saja kehilangan kepercayaan pelanggan bertahun-tahun.","sentence_template":"対応を先延ばしにすれば、長年の顧客の信頼を失い[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, '失う -> 失いかねない mengekspresikan risiko serius bila tidak segera bertindak.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan arahan manajer keamanan IT. Risiko apa yang ia peringatkan?', '{"audio_text":"パスワードを複数のサービスで使い回していると、不正アクセスの被害に遭いかねませんよ。","options":[{"id":"opt_1","text":"Akun akan otomatis mendapatkan penyimpanan gratis tambahan"},{"id":"opt_2","text":"Menggunakan kata sandi yang sama di beberapa layanan bisa berisiko terkena akses tidak sah"},{"id":"opt_3","text":"Kecepatan internet di kantor akan meningkat dua kali lipat"},{"id":"opt_4","text":"Kata sandi akan otomatis diperbarui setiap hari"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '被害に遭いかねません berarti bisa saja mengalami kerugian/menjadi korban peretasan.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika terus bekerja tanpa istirahat, Anda bisa saja jatuh sakit."', '{"tokens":["働き続けると、","壊し","ない。","つつある。","休まずに","体を","かね","壊した"],"target_translation":"Jika terus bekerja tanpa istirahat, Anda bisa saja jatuh sakit.","romaji":"Yasumazu ni hataraki tsuzukeru to, karada o kowashikanenai."}'::jsonb, '["休まずに","働き続けると、","体を","壊し","かね","ない。"]'::jsonb, '体を壊す -> 体を壊しかねない adalah peringatan kesehatan yang sangat alami.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pernyataan yang kurang hati-hati itu bisa saja menimbulkan kesalahpahaman besar."', '{"display_text":"その軽率な発言は、大きな誤解を招きかねません。","romaji":"Sono keisotsu na hatsugen wa, ookina gokai o manekikanemasen.","phonetic_breakdown":["そのけいそつな","はつげんは","おおきなごかいを","まねきかねません"]}'::jsonb, '{"expected_transcript":"その軽率な発言は、大きな誤解を招きかねません。"}'::jsonb, '誤解を招きかねません (bisa saja mengundang kesalahpahaman) adalah kolokasi klasik JLPT N2.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予算管理を甘く見ていると、年度末に深刻な資金不足に陥り___。', '{"options":["かねない","にあたって","の上で","にもかかわらず"],"translation":"Jika meremehkan pengelolaan anggaran, pada akhir tahun fiskal bisa saja terjerumus ke kekurangan dana serius.","sentence_template":"予算管理を甘く見ていると、年度末に深刻な資金不足に陥り[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, '陥る (terjerumus) -> 陥りかねない menggambarkan risiko finansial.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan peringatan dokter berikut. Apa bahaya jika gejala dibiarkan?', '{"audio_text":"軽い症状だからといって放置しておくと、慢性化して治療が長引きかねないのです。","options":[{"id":"opt_1","text":"Gejala ringan pasti sembuh sendiri dalam satu jam"},{"id":"opt_2","text":"Obat tidak diperlukan untuk penyakit kronis"},{"id":"opt_3","text":"Jika dibiarkan karena dianggap ringan, kondisi bisa menjadi kronis dan pengobatan berlarut-larut"},{"id":"opt_4","text":"Pasien tidak perlu memeriksakan diri lagi"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '治療が長引きかねない berarti pengobatan bisa saja menjadi berkepanjangan.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika jadwal terlalu dipaksakan, kualitas produk bisa saja menurun drastis."', '{"tokens":["スケジュールを組むと、","低下","ない。","わけにはいかない。","無理な","製品の品質が","しかね","低下した"],"target_translation":"Jika jadwal terlalu dipaksakan, kualitas produk bisa saja menurun drastis.","romaji":"Muri na sukejuuru o kumu to, seihin no hinshitsu ga teika shikanenai."}'::jsonb, '["無理な","スケジュールを組むと、","製品の品質が","低下","しかね","ない。"]'::jsonb, '低下する -> 低下しかねない memperingatkan penurunan kualitas.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar analis hukum. Risiko apa yang muncul dari klausul kontrak yang ambigu?', '{"audio_text":"契約書の表現が曖昧なままだと、将来的に深刻な法的トラブルに発展しかねない。","options":[{"id":"opt_1","text":"Rumusan kontrak yang ambigu bisa saja berkembang menjadi sengketa hukum serius di masa depan"},{"id":"opt_2","text":"Kontrak yang ambigu mempermudah pembatalan tanpa biaya"},{"id":"opt_3","text":"Pihak hukum tidak memerlukan kontrak tertulis"},{"id":"opt_4","text":"Klausul tersebut akan otomatis diperbaiki oleh pengadilan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'トラブルに発展しかねない berarti bisa saja berkembang menjadi perselisihan serius.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika pengawasan lalu lintas dilonggarkan, angka kecelakaan bisa saja meningkat."', '{"tokens":["緩めると、","増加","ない。","つつある。","交通取り締まりを","事故件数が","しかね","増加する"],"target_translation":"Jika pengawasan lalu lintas dilonggarkan, angka kecelakaan bisa saja meningkat.","romaji":"Koutsuu torishimari o yurumeru to, jiko kensuu ga zouka shikanenai."}'::jsonb, '["交通取り締まりを","緩めると、","事故件数が","増加","しかね","ない。"]'::jsonb, '増加しかねない menyatakan kemungkinan buruk meningkatnya kecelakaan.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 個人情報の管理体制が不十分だと、企業の存続にも関わる問題になり___。', '{"options":["かねない","ざるを得ない","に限らず","に伴って"],"translation":"Jika sistem pengelolaan data pribadi tidak memadai, bisa saja menjadi masalah yang mengancam kelangsungan perusahaan.","sentence_template":"個人情報の管理体制が不十分だと、企業の存続にも関わる問題になり[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, 'なる -> なりかねない menekankan potensi eskalasi dampak negatif.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mengemudi dalam keadaan mengantuk sangat berbahaya karena bisa menyebabkan kecelakaan fatal."', '{"display_text":"居眠り運転は、命に関わる大事故を起こしかねず大変危険です。","romaji":"Inemuri unten wa, inochi ni kakawaru daijiko o okoshikanezu taihen kiken desu.","phonetic_breakdown":["いねむりうんてんは","いのちにかかわる","だいじこを","おこしかねず","たいへんきけんです"]}'::jsonb, '{"expected_transcript":"居眠り運転は、命に関わる大事故を起こしかねず大変危険です。"}'::jsonb, '～かねず adalah bentuk sambung formal dari ～かねない dalam tulisan/peringatan resmi.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 証拠を確認せずに情報を拡散すると、名誉毀損で訴えられ___。', '{"options":["かねない","つつある","にあたって","の上で"],"translation":"Jika menyebarkan informasi tanpa memverifikasi bukti, bisa saja dituntut atas pencemaran nama baik.","sentence_template":"証拠を確認せずに情報を拡散すると、名誉毀損で訴えられ[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, '訴えられる (pasif) -> 訴えられかねない berarti berisiko dituntut secara hukum.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan diskusi rapat krisis. Apa kekhawatiran direktur pemasaran?', '{"audio_text":"ここで誠実な謝罪と説明を怠れば、不買運動にまで広がりかねないと危惧しています。","options":[{"id":"opt_1","text":"Penjualan produk akan melonjak naik besok pagi"},{"id":"opt_2","text":"Pelanggan tidak akan menyadari adanya masalah"},{"id":"opt_3","text":"Media akan memuji perusahaan karena diam saja"},{"id":"opt_4","text":"Jika lalai meminta maaf dan menjelaskan dengan tulus, bisa saja meluas hingga aksi boikot produk"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '不買運動にまで広がりかねない berarti bisa saja meluas sampai aksi boikot.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika pemeliharaan jembatan diabaikan, keselamatan warga bisa saja terancam."', '{"tokens":["怠ると、","脅かされ","ない。","に限らず、","橋の点検を","市民の安全が","かね","脅かした"],"target_translation":"Jika pemeliharaan jembatan diabaikan, keselamatan warga bisa saja terancam.","romaji":"Hashi no tenken o okotaru to, shimin no anzen ga obiyakasarekanenai."}'::jsonb, '["橋の点検を","怠ると、","市民の安全が","脅かされ","かね","ない。"]'::jsonb, '脅かされる (terancam) -> 脅かされかねない.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika kita tidak segera memperbaiki bug ini, layanan bisa saja berhenti total."', '{"display_text":"この不具合を早急に修正しないと、サービス全体が停止しかねません。","romaji":"Kono fuguai o soukyuu ni shuusei shinai to, saabisu zentai ga teishi shikanemasen.","phonetic_breakdown":["このふぐあいを","そうきゅうに","しゅうせいしないと","さーびすぜんたいが","ていししかねません"]}'::jsonb, '{"expected_transcript":"この不具合を早急に修正しないと、サービス全体が停止しかねません。"}'::jsonb, '停止しかねません memperingatkan risiko downtime total dalam operasional IT.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 軽率な行動は、チームの士気を___しかねない。', '{"options":["低下","達成","歓迎","祝賀"],"translation":"Tindakan yang gegabah bisa saja menurunkan semangat juang tim.","sentence_template":"軽率な行動は、チームの士気を[blank]しかねない。"}'::jsonb, '{"selected":"低下"}'::jsonb, '士気が低下する (semangat/moral tim menurun) adalah kolokasi penting dunia kerja.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kelelahan yang menumpuk bisa saja menyebabkan kesalahan kerja yang tidak terduga."', '{"display_text":"疲労が蓄積すると、思わぬ作業ミスにつながりかねません。","romaji":"Hirou ga chikuseki suru to, omowanu sagyou misu ni tsunagarikanemasen.","phonetic_breakdown":["ひろうが","ちくせきすると","おもわぬさぎょうみすに","つながりかねません"]}'::jsonb, '{"expected_transcript":"疲労が蓄積すると、思わぬ作業ミスにつながりかねません。"}'::jsonb, 'つながりかねません berarti bisa saja berujung pada akibat buruk.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa nuansa utama dari ～かねない dalam konteks ini?', '{"audio_text":"このまま赤字が続けば、来期は経営破綻に陥りかねない状況だ。","options":[{"id":"opt_1","text":"Kekhawatiran realistis bahwa perusahaan bisa saja jatuh bangkrut jika defisit berlanjut"},{"id":"opt_2","text":"Harapan gembira bahwa keuntungan akan meningkat"},{"id":"opt_3","text":"Kepastian bahwa perusahaan pasti sukses besar"},{"id":"opt_4","text":"Kewajiban etis untuk mengambil cuti bersama"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '～かねない selalu digunakan untuk memperingatkan kemungkinan hasil negatif yang dikhawatirkan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 電源コードが傷んだまま使い続けると、火災の原因になり___。', '{"options":["かねない","つつある","ざるを得ない","わけにはいかない"],"translation":"Jika terus digunakan saat kabel daya rusak, hal itu bisa saja menjadi penyebab kebakaran.","sentence_template":"電源コードが傷んだまま使い続けると、火災の原因になり[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, '原因になりかねない adalah frasa standar dalam buku panduan keselamatan produk.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika rumor palsu dibiarkan, reputasi perusahaan bisa saja rusak parah."', '{"tokens":["放置すると、","傷つき","ない。","にもかかわらず、","根拠のない噂を","企業の評判が","かね","傷ついた"],"target_translation":"Jika rumor palsu dibiarkan, reputasi perusahaan bisa saja rusak parah.","romaji":"Ne mo ha mo nai uwasa o houchi suru to, kigyou no hyouban ga kizutsukikanenai."}'::jsonb, '["根拠のない噂を","放置すると、","企業の評判が","傷つき","かね","ない。"]'::jsonb, '傷つきかねない mengingatkan potensi rusaknya reputasi.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan peringatan pemandu gunung. Mengapa pendaki diminta turun lebih awal?', '{"audio_text":"天候が急変し始めていますので、このまま登り続けると遭難しかねません。","options":[{"id":"opt_1","text":"Karena jalur pendakian akan segera dipenuhi bunga sakura"},{"id":"opt_2","text":"Karena cuaca mulai berubah mendadak sehingga jika terus mendaki bisa berisiko tersesat/celaka"},{"id":"opt_3","text":"Karena penginapan di puncak gunung sedang diskon besar"},{"id":"opt_4","text":"Karena semua pendaki sudah mencapai puncak"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '遭難しかねません berarti bisa saja mengalami kecelakaan atau tersesat di gunung.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 説明不足のまま新ルールを強制すると、現場の反発を招き___。', '{"options":["かねない","に伴って","にあたって","の上で"],"translation":"Jika memaksakan aturan baru tanpa penjelasan cukup, bisa saja memicu penolakan dari lapangan.","sentence_template":"説明不足のまま新ルールを強制すると、現場の反発を招き[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, '反発を招きかねない berarti bisa saja mengundang reaksi penolakan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika suhu penyimpanan tidak tepat, bahan makanan bisa saja cepat membusuk."', '{"display_text":"保存温度が適切でないと、食材が傷みかねません。","romaji":"Hozon ondo ga tekisetsu de nai to, shokuzai ga itamikanemasen.","phonetic_breakdown":["ほぞんおんどが","てきせつでないと","しょくざいが","いたみかねません"]}'::jsonb, '{"expected_transcript":"保存温度が適切でないと、食材が傷みかねません。"}'::jsonb, '食材が傷む (bahan makanan rusak/busuk) + かねません cocok untuk konteks manajemen kualitas pangan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar pakar lingkungan. Apa dampak jangka panjang yang dikhawatirkan?', '{"audio_text":"排水基準を守らない工場が増えれば、地域の生態系が取り返しのつかないほど破壊されかねない。","options":[{"id":"opt_1","text":"Kualitas air sungai akan menjadi lebih jernih"},{"id":"opt_2","text":"Industri perikanan lokal akan berkembang pesat"},{"id":"opt_3","text":"Ekosistem setempat bisa saja rusak tak terpulihkan jika makin banyak pabrik melanggar standar limbah"},{"id":"opt_4","text":"Pemerintah akan menutup seluruh sungai di kota"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '破壊されかねない memperingatkan ancaman kerusakan permanen ekosistem.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika terlalu percaya diri, kita bisa saja melewatkan celah kesalahan kecil."', '{"tokens":["しすぎると、","見逃し","ない。","に限らず、","過信","小さなミスを","かね","見逃した"],"target_translation":"Jika terlalu percaya diri, kita bisa saja melewatkan celah kesalahan kecil.","romaji":"Kajin shi sugiru to, chiisana misu o minogashikanenai."}'::jsonb, '["過信","しすぎると、","小さなミスを","見逃し","かね","ない。"]'::jsonb, '見逃しかねない (bisa saja terlewat/tidak terlihat) adalah peringatan sikap kerja teliti.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat resepsionis kantor dengan sonkeigo yang tepat: 社長はただいま会議室に___。', '{"options":["いらっしゃいます","おります","まいります","いたします"],"translation":"Direktur utama saat ini sedang berada di ruang rapat.","sentence_template":"社長はただいま会議室に[blank]。"}'::jsonb, '{"selected":"いらっしゃいます"}'::jsonb, 'いらっしゃいます adalah sonkeigo (peninggi) dari いる; おります adalah kenjougo (merendahkan diri).', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk sonkeigo yang tepat untuk menanyakan apakah klien sudah membaca materi: 先ほどお送りした資料は、すでにご覧___でしょうか。', '{"options":["になりました","いたしました","申しました","伺いました"],"translation":"Apakah Anda sudah sempat melihat materi yang baru saja kami kirimkan?","sentence_template":"先ほどお送りした資料は、すでにご覧[blank]でしょうか。"}'::jsonb, '{"selected":"になりました"}'::jsonb, 'ご覧になる adalah bentuk sonkeigo baku untuk 見る (melihat/membaca).', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ucapan sekretaris di telepon. Apa yang ia sampaikan mengenai direktur?', '{"audio_text":"あいにく部長はただいま外出しておりまして、三時頃にお戻りになる予定です。","options":[{"id":"opt_1","text":"Kepala divisi sudah pensiun minggu lalu"},{"id":"opt_2","text":"Kepala divisi sedang keluar kantor saat ini dan dijadwalkan kembali sekitar pukul tiga"},{"id":"opt_3","text":"Kepala divisi menolak menerima panggilan dari siapa pun"},{"id":"opt_4","text":"Kepala divisi sedang makan siang di kantin lantai satu"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, 'お戻りになる adalah sonkeigo untuk 戻る; digunakan saat berbicara tentang jadwal kembalinya atasan kepada rekan internal atau sesama staf, atau perhatikan konteks sopan.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Bapak Direktur bersedia menyantap hidangan ini?"', '{"tokens":["こちらの","召し上がり","か。","まいります","社長は","お料理を","ます","いただきます"],"target_translation":"Apakah Bapak Direktur bersedia menyantap hidangan ini?","romaji":"Shachou wa kochira no oryouri o meshiagarimasu ka."}'::jsonb, '["社長は","こちらの","お料理を","召し上がり","ます","か。"]'::jsonb, '召し上がる adalah sonkeigo baku untuk 食べる dan 飲む.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Silakan Anda beristirahat sejenak di ruang tunggu sambil menunggu."', '{"display_text":"恐れ入りますが、少々こちらでお待ちになっていただけますか。","romaji":"Osoreirimasu ga, shoushou kochira de omachi ni natte itadakemasu ka.","phonetic_breakdown":["おそれいりますが","しょうしょうこちらで","おまちになって","いただけますか"]}'::jsonb, '{"expected_transcript":"恐れ入りますが、少々こちらでお待ちになっていただけますか。"}'::jsonb, 'お待ちになる (お + V-masu stem + になる) adalah pola sonkeigo standar yang sangat sopan.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat penyambutan tamu: 田中様、本日は遠方よりお越し___、誠にありがとうございます。', '{"options":["くださり","いたし","申し上げ","伺い"],"translation":"Bapak/Ibu Tanaka, terima kasih banyak telah berkenan hadir dari jauh pada hari ini.","sentence_template":"田中様、本日は遠方よりお越し[blank]、誠にありがとうございます。"}'::jsonb, '{"selected":"くださり"}'::jsonb, 'お越しくださる adalah bentuk sonkeigo sangat sopan untuk 来てくれる (berkenan datang).', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan di ruang rapat. Apa yang diminta oleh pembicara kepada tamu?', '{"audio_text":"ご不明な点がございましたら、どうぞ遠慮なくおっしゃってくださいませ。","options":[{"id":"opt_1","text":"Meminta tamu segera meninggalkan ruangan"},{"id":"opt_2","text":"Meminta tamu menulis laporan sepuluh halaman"},{"id":"opt_3","text":"Mempersilakan tamu menyampaikan tanpa sungkan jika ada hal yang kurang jelas"},{"id":"opt_4","text":"Meminta tamu mematikan layar presentasi"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'おっしゃる adalah sonkeigo baku untuk 言う (mengatakan/menyampaikan).', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Anda mengetahui jadwal perubahan seminar minggu depan?"', '{"tokens":["セミナーの","ご存じ","か。","申して","来週の","日程変更を","でしょう","存じて"],"target_translation":"Apakah Anda mengetahui jadwal perubahan seminar minggu depan?","romaji":"Raishuu no seminaa no nittei henkou o gozonji deshou ka."}'::jsonb, '["来週の","セミナーの","日程変更を","ご存じ","でしょう","か。"]'::jsonb, 'ご存じです adalah sonkeigo dari 知っている, sedangkan 存じております adalah kenjougo.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan sambutan pembawa acara. Siapa yang akan memberikan pidato pembukaan?', '{"audio_text":"続きまして、来賓を代表いたしまして、佐藤理事長よりご挨拶を頂戴いたします。","options":[{"id":"opt_1","text":"Ketua Dewan Sato akan menyampaikan sambutan mewakili para tamu kehormatan"},{"id":"opt_2","text":"Acara resmi ditutup sekarang juga"},{"id":"opt_3","text":"Pembawa acara akan menyanyikan lagu perpisahan"},{"id":"opt_4","text":"Para tamu diminta segera menuju ruang makan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '来賓を代表いたしまして dan ご挨拶を頂戴いたします adalah protokol formal upacara Jepang.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kapan Bapak Profesor berangkat menuju konferensi internasional di Osaka?"', '{"tokens":["大阪の","お出かけ","ますか。","まいり","先生はいつ","国際会議へ","になり","出かけいたし"],"target_translation":"Kapan Bapak Profesor berangkat menuju konferensi internasional di Osaka?","romaji":"Sensei wa itsu Oosaka no kokusai kaigi e odekake ni narimasu ka."}'::jsonb, '["先生はいつ","大阪の","国際会議へ","お出かけ","になり","ますか。"]'::jsonb, 'お出かけになる adalah sonkeigo baku untuk 出かける (bepergian/berangkat).', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk sonkeigo yang tepat (hindari keigo ganda!): 課長は昨日、新しい企画書を___。', '{"options":["ご覧になりました","ご覧になられました","拝見しました","お読みいたしました"],"translation":"Kemarin kepala seksi telah membaca/melihat proposal baru tersebut.","sentence_template":"課長は昨日、新しい企画書を[blank]。"}'::jsonb, '{"selected":"ご覧になりました"}'::jsonb, 'ご覧になりました sudah merupakan sonkeigo penuh; ご覧になられました adalah kesalahan keigo ganda (二重敬語).', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Bapak/Ibu berkenan memilih kopi atau teh hijau?"', '{"display_text":"お飲み物はコーヒーと緑茶のどちらになさいますか。","romaji":"Onomimono wa koohii to ryokucha no dochira ni nasaimasu ka.","phonetic_breakdown":["おのみものは","こーひーと","りょくちゃの","どちらに","なさいますか"]}'::jsonb, '{"expected_transcript":"お飲み物はコーヒーと緑茶のどちらになさいますか。"}'::jsonb, 'なさる adalah sonkeigo baku untuk する; どちらになさいますか berarti ''hendak memilih yang mana?''.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat email bisnis: 添付ファイルをご確認の___、ご返信いただけますと幸いです。', '{"options":["上","下","前","内"],"translation":"Kami akan sangat berterima kasih apabila Anda berkenan membalas setelah memeriksa file lampiran.","sentence_template":"添付ファイルをご確認の[blank]、ご返信いただけますと幸いです。"}'::jsonb, '{"selected":"上"}'::jsonb, 'ご確認の上 (setelah Anda memeriksa) menggabungkan sopan-santun ご確認 dengan pola 上.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ucapan staf hotel kepada tamu VIP. Apa yang diinformasikan staf?', '{"audio_text":"お荷物はすでにお部屋へお運びしてございますので、どうぞごゆっくりお寛ぎくださいませ。","options":[{"id":"opt_1","text":"Bagasi tamu hilang di bandara"},{"id":"opt_2","text":"Tamu harus mengangkat sendiri koper ke lantai sepuluh"},{"id":"opt_3","text":"Kamar tamu belum selesai dibersihkan"},{"id":"opt_4","text":"Bagasi tamu sudah diantarkan ke kamar sehingga tamu dipersilakan beristirahat dengan tenang"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, 'お寛ぎくださいませ (silakan beristirahat santai) adalah ungkapan sonkeigo ramah khas layanan Jepang.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Silakan Anda menuliskan nama dan alamat pada formulir ini."', '{"tokens":["用紙に","ご住所を","ください。","お書き申し","こちらの","お名前と","お書き","書いていたし"],"target_translation":"Silakan Anda menuliskan nama dan alamat pada formulir ini.","romaji":"Kochira no youshi ni onamae to gojuusho o okaki kudasai."}'::jsonb, '["こちらの","用紙に","お名前と","ご住所を","お書き","ください。"]'::jsonb, 'お + V-masu stem + ください (お書きください) adalah permintaan sopan bergaya sonkeigo.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bapak Direktur berkata bahwa beliau akan menghadiri pertemuan besok pagi."', '{"display_text":"社長は明日の朝の打ち合わせにご出席になるとおっしゃいました。","romaji":"Shachou wa asu no asa no uchiawase ni goshusseki ni naru to osshaimashita.","phonetic_breakdown":["しゃちょうは","あしたのあさの","うちあわせに","ごしゅっせきになると","おっしゃいました"]}'::jsonb, '{"expected_transcript":"社長は明日の朝の打ち合わせにご出席になるとおっしゃいました。"}'::jsonb, 'ご出席になる (hadir) dan おっしゃいました (berkata) adalah kombinasi sonkeigo yang tepat tanpa tumpang tindih.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih padanan sonkeigo yang tepat untuk 寝る / 休む: 長旅でお疲れでしょうから、今夜はゆっくり___ください。', '{"options":["お休み","ご拝見","お伺い","ご参上"],"translation":"Karena pasti lelah dari perjalanan jauh, malam ini silakan beristirahat dengan tenang.","sentence_template":"長旅でお疲れでしょうから、今夜はゆっくり[blank]ください。"}'::jsonb, '{"selected":"お休み"}'::jsonb, 'お休みください adalah sonkeigo baku untuk mempersilakan tamu/atasan beristirahat.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih banyak karena Anda selalu memberikan bimbingan yang hangat kepada kami."', '{"display_text":"日頃より温かいご指導を賜り、心より感謝申し上げます。","romaji":"Higoro yori atatakai goshidou o tamawari, kokoro yori kansha moushiagemasu.","phonetic_breakdown":["ひごろより","あたたかい","ごしどうをたまわり","こころより","かんしゃもうしあげます"]}'::jsonb, '{"expected_transcript":"日頃より温かいご指導を賜り、心より感謝申し上げます。"}'::jsonb, 'ご指導を賜る (menerima bimbingan dari pihak yang dihormati) adalah ungkapan puncak sopan santun bisnis N2.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Manakah pilihan yang menjelaskan penggunaan sonkeigo di dalamnya?', '{"audio_text":"先生が推薦してくださった専門書を、さっそく図書館で借りてきました。","options":[{"id":"opt_1","text":"Pembicara menghormati dosen dengan memakai ～てくださった karena dosen berkenan merekomendasikan buku"},{"id":"opt_2","text":"Pembicara meminta dosen meminjamkan kartu perpustakaan"},{"id":"opt_3","text":"Dosen meminjam buku dari mahasiswa"},{"id":"opt_4","text":"Pembicara lupa judul buku yang direkomendasikan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '～てくださる adalah bentuk sonkeigo dari ～てくれる yang meninggikan tindakan baik dari atasan/dosen.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan sonkeigo untuk する: 本日のイベントには、多くの来賓の方々にご参加___。', '{"options":["いただきました","いたしました","申しました","おりました"],"translation":"Pada acara hari ini, banyak tamu kehormatan berkenan turut berpartisipasi.","sentence_template":"本日のイベントには、多くの来賓の方々にご参加[blank]。"}'::jsonb, '{"selected":"いただきました"}'::jsonb, 'ご参加いただきました (menerima kehormatan partisipasi Anda) adalah ungkapan baku dalam laporan acara.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Ibu Manajer sudah memeriksa laporan bulanan tersebut?"', '{"tokens":["もうその月報を","になり","か。","いたし","部長は","ご覧","ました","拝見し"],"target_translation":"Apakah Ibu Manajer sudah memeriksa laporan bulanan tersebut?","romaji":"Buchou wa mou sono geppou o goran ni narimashita ka."}'::jsonb, '["部長は","もうその月報を","ご覧","になり","ました","か。"]'::jsonb, 'ご覧になりましたか menggunakan sonkeigo baku untuk menanyakan apakah atasan sudah melihat laporan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pesan suara klien. Apa yang disampaikan Bapak Yamada?', '{"audio_text":"恐れ入りますが、先ほどお話しになった新製品の資料をメールでお送りいただけますか。","options":[{"id":"opt_1","text":"Bapak Yamada ingin membatalkan seluruh pesanan"},{"id":"opt_2","text":"Bapak Yamada meminta materi produk baru yang baru saja dibicarakan dikirimkan melalui email"},{"id":"opt_3","text":"Bapak Yamada mengundang rapat tatap muka hari Minggu"},{"id":"opt_4","text":"Bapak Yamada salah sambung nomor telepon"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, 'お話しになった (sonkeigo dari 話した) merujuk pada hal yang baru saja disampaikan lawan bicara.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang paling tepat: お客様がもうすぐ受付に___ので、会議室へご案内してください。', '{"options":["いらっしゃいます","まいります","おります","いたします"],"translation":"Karena tamu akan segera tiba di resepsionis, tolong antarkan ke ruang rapat.","sentence_template":"お客様がもうすぐ受付に[blank]ので、会議室へご案内してください。"}'::jsonb, '{"selected":"いらっしゃいます"}'::jsonb, 'いらっしゃいます adalah sonkeigo baku untuk 来る (datang/tiba) bagi tamu.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apabila ada pertanyaan lebih lanjut, silakan hubungi bagian layanan kami kapan saja."', '{"display_text":"ご不明な点がございましたら、いつでもお気軽にお問い合わせください。","romaji":"Gofumei na ten ga gozaimashitara, itsudemo okigaru ni otoiawase kudasai.","phonetic_breakdown":["ごふめいなてんが","ございましたら","いつでもおきがるに","おといあわせください"]}'::jsonb, '{"expected_transcript":"ご不明な点がございましたら、いつでもお気軽にお問い合わせください。"}'::jsonb, 'お問い合わせください (silakan menghubungi) adalah penutup standar email dan layanan pelanggan Jepang.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman di ruang seminar. Apa yang diminta panitia kepada hadirin?', '{"audio_text":"まもなく講演が始まりますので、まだお席に着いていらっしゃらない方は前方へお進みください。","options":[{"id":"opt_1","text":"Hadirin diminta meninggalkan gedung seminar"},{"id":"opt_2","text":"Acara seminar diundur dua jam"},{"id":"opt_3","text":"Hadirin yang belum duduk dipersilakan maju ke bagian depan karena kuliah segera dimulai"},{"id":"opt_4","text":"Hadirin dilarang membawa catatan ke dalam ruangan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '着いていらっしゃらない方 menggunakan sonkeigo ～ていらっしゃる secara tepat dan sopan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Bapak Presiden Direktur berkenan menyampaikan pesan penyemangat kepada seluruh staf."', '{"tokens":["全社員に","お言葉を","ました。","いたし","社長は","励ましの","ください","さしあげ"],"target_translation":"Bapak Presiden Direktur berkenan menyampaikan pesan penyemangat kepada seluruh staf.","romaji":"Shachou wa zenshain ni hagemashi no okotoba o kudasaimashita."}'::jsonb, '["社長は","全社員に","励ましの","お言葉を","ください","ました。"]'::jsonb, 'お言葉をくださいました menggunakan sonkeigo くださる untuk tindakan memberi pesan dari atasan tertinggi.', 8);
        INSERT INTO units (id, level_id, title, description, unit_type, order_index)
        INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
        INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
        VALUES
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N2-001' LIMIT 1), 'reading', 'fill_blank', 'Simulasi N2 (1/10): Lengkapi kalimat formal berikut: 新規海外拠点の開設___、現地法規の専門チームを編成した。', '{"options":["にあたり","に伴って","に限らず","かねず"],"translation":"Menjelang pembukaan basis luar negeri baru, kami membentuk tim khusus hukum setempat.","sentence_template":"新規海外拠点の開設[blank]、現地法規の専門チームを編成した。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, '～にあたり digunakan pada pengumuman atau persiapan resmi menjelang peristiwa penting.', 1),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N2-002' LIMIT 1), 'listening', 'listening_choice', 'Simulasi N2 (2/10): Dengarkan laporan ekonomi berikut. Perubahan apa yang menyertai tren belanja daring?', '{"audio_text":"ネット通販の急拡大に伴い、物流業界では配達員不足と再配達コストの増加が深刻化している。","options":[{"id":"opt_1","text":"Jumlah kurir melimpah dan biaya pengiriman turun drastis"},{"id":"opt_2","text":"Seiring meluasnya belanja daring, kekurangan kurir dan biaya kirim ulang makin parah di industri logistik"},{"id":"opt_3","text":"Belanja daring dilarang di wilayah perkotaan"},{"id":"opt_4","text":"Perusahaan logistik menghentikan layanan pengiriman rumah"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '急拡大に伴い menghubungkan pertumbuhan e-commerce dengan meningkatnya beban logistik.', 2),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N2-003' LIMIT 1), 'reading', 'fill_blank', 'Simulasi N2 (3/10): Pilih pola yang tepat: この奨学金制度は理系学生___、文系分野の研究者も対象としている。', '{"options":["に限らず","にあたって","にもかかわらず","の上で"],"translation":"Program beasiswa ini tidak terbatas pada mahasiswa sains, tetapi juga mencakup peneliti bidang humaniora.","sentence_template":"この奨学金制度は理系学生[blank]、文系分野の研究者も対象としている。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, '～に限らず memperluas cakupan subjek dari A ke B secara inklusif.', 3),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N2-004' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah diberi kepercayaan sebagai pemimpin proyek, saya tidak mungkin mundur di tengah jalan."', '{"tokens":["任された以上、","投げ出す","いかない。","かねない。","リーダーを","途中で","わけには","投げ出した"],"target_translation":"Karena sudah diberi kepercayaan sebagai pemimpin proyek, saya tidak mungkin mundur di tengah jalan.","romaji":"Riidaa o makasareta ijou, tochuu de nagedasu wake ni wa ikanai."}'::jsonb, '["リーダーを","任された以上、","途中で","投げ出す","わけには","いかない。"]'::jsonb, 'V-dict + わけにはいかない menyatakan tidak mungkin melakukan sesuatu karena tanggung jawab.', 4),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N2-005' LIMIT 1), 'reading', 'fill_blank', 'Simulasi N2 (5/10): Pilih bentuk konjugasi yang benar: 設備の重大な故障が見つかり、工場の稼働を一時停止___。', '{"options":["せざるを得なかった","しざるを得なかった","すざるを得なかった","するざるを得なかった"],"translation":"Ditemukan kerusakan peralatan serius sehingga kami terpaksa menghentikan operasional pabrik sementara.","sentence_template":"設備の重大な故障が見つかり、工場の稼働を一時停止[blank]。"}'::jsonb, '{"selected":"せざるを得なかった"}'::jsonb, 'Kata kerja する selalu berubah menjadi せざるを得ない / せざるを得なかった.', 5),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N2-006' LIMIT 1), 'listening', 'listening_choice', 'Simulasi N2 (6/10): Dengarkan berita berikut. Apa hal kontras yang dilaporkan?', '{"audio_text":"厳しい価格競争が続いているにもかかわらず、高品質を貫く同社の製品シェアは拡大し続けている。","options":[{"id":"opt_1","text":"Pangsa pasar perusahaan terus menyusut akibat perang harga"},{"id":"opt_2","text":"Perusahaan menurunkan kualitas demi memangkas biaya"},{"id":"opt_3","text":"Meskipun persaingan harga ketat berlanjut, pangsa pasar produk berkualitas tinggi perusahaan itu terus meluas"},{"id":"opt_4","text":"Perusahaan menghentikan penjualan di pasar domestik"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '～にもかかわらず menyoroti kontras kuat antara persaingan ketat dan pertumbuhan pangsa pasar.', 6),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N2-007' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah mempertimbangkan masukan seluruh departemen, kami akan menetapkan rencana final."', '{"display_text":"各部署の意見を踏まえた上で、最終計画を決定いたします。","romaji":"Kaku busho no iken o fumaeta ue de, saishuu keikaku o kettei itashimasu.","phonetic_breakdown":["かくぶしょの","いけんをふまえたうえで","さいしゅうけいかくを","けっていいたします"]}'::jsonb, '{"expected_transcript":"各部署の意見を踏まえた上で、最終計画を決定いたします。"}'::jsonb, 'V-ta + 上で menyatakan langkah A diselesaikan lebih dulu sebelum keputusan B.', 7),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N2-008' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Kesadaran perusahaan terhadap keberlanjutan lingkungan sedang terus meningkat."', '{"tokens":["企業の意識が","高まり","ある。","ざるを得ない。","環境配慮に対する","年々","つつ","高まった"],"target_translation":"Kesadaran perusahaan terhadap keberlanjutan lingkungan sedang terus meningkat.","romaji":"Kankyou e no hairyo ni taisuru kigyou no ishiki ga takamaritsutsu aru."}'::jsonb, '["環境配慮に対する","企業の意識が","年々","高まり","つつ","ある。"]'::jsonb, 'V-masu stem + つつある menggambarkan tren perubahan yang sedang berlangsung.', 8),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N2-009' LIMIT 1), 'listening', 'listening_choice', 'Simulasi N2 (9/10): Dengarkan peringatan manajer kualitas. Apa risiko yang ia khawatirkan?', '{"audio_text":"出荷前の検査工程を省略すれば、不良品が市場に流出して大規模なリコールに発展しかねません。","options":[{"id":"opt_1","text":"Biaya produksi akan menjadi nol tanpa pemeriksaan"},{"id":"opt_2","text":"Pelanggan akan lebih cepat menerima produk sempurna"},{"id":"opt_3","text":"Pabrik akan menerima penghargaan kualitas internasional"},{"id":"opt_4","text":"Jika tahap inspeksi sebelum kirim dilewati, produk cacat bisa beredar dan memicu penarikan massal"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '発展しかねません memperingatkan eskalasi risiko serius (recall massal).', 9),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N2-010' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Bapak Direktur sudah berkenan memeriksa draf kontrak yang kami kirimkan kemarin?"', '{"display_text":"昨日お送りした契約書案は、すでにご覧になりましたでしょうか。","romaji":"Sakujitsu ookuri shita keiyakushoan wa, sude ni goran ni narimashita deshou ka.","phonetic_breakdown":["さくじつ","おおくりしたけいやくしょあんは","すでに","ごらんになりましたでしょうか"]}'::jsonb, '{"expected_transcript":"昨日お送りした契約書案は、すでにご覧になりましたでしょうか。"}'::jsonb, 'ご覧になりましたでしょうか menggunakan sonkeigo baku tanpa kesalahan keigo ganda.', 10);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi laporan krisis berikut: 深刻なシステム障害が発生する___、ようやく抜本的な改修予算が承認された。', '{"options":["に至って","をもって","なりに","ともなると"],"translation":"Baru setelah terjadi gangguan sistem yang parah, anggaran perombakan mendasar akhirnya disetujui.","sentence_template":"深刻なシステム障害が発生する[blank]、ようやく抜本的な改修予算が承認された。"}'::jsonb, '{"selected":"に至って"}'::jsonb, '～に至って menandai titik kritis ekstrem yang baru memicu kesadaran atau tindakan.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk eskalasi puncak: 事態がここまで悪化する___、もはや従来の対策では不十分だ。', '{"options":["に至っては","を余儀なくされ","とはいえ","に足る"],"translation":"Setelah situasi memburuk sampai sejauh ini, langkah penanggulangan konvensional tidak lagi memadai.","sentence_template":"事態がここまで悪化する[blank]、もはや従来の対策では不十分だ。"}'::jsonb, '{"selected":"に至っては"}'::jsonb, '～に至っては memberi penekanan kuat pada situasi yang sudah mencapai tahap ekstrem.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan berita politik berikut. Kapan pemerintah akhirnya mengambil tindakan tegas?', '{"audio_text":"複数の自治体から住民の健康被害が報告されるに至って、国はようやく工場の操業停止を命じた。","options":[{"id":"opt_1","text":"Sebelum pabrik mulai beroperasi sama sekali"},{"id":"opt_2","text":"Baru setelah laporan gangguan kesehatan warga datang dari berbagai pemda, pemerintah memerintahkan penghentian operasi pabrik"},{"id":"opt_3","text":"Pemerintah tidak pernah mengeluarkan perintah apa pun"},{"id":"opt_4","text":"Pabrik memutuskan berhenti sendiri tanpa laporan warga"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '報告されるに至って menegaskan keterlambatan respons hingga situasi mencapai titik kritis.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Baru setelah kehilangan kesehatannya, ia menyadari betapa berharganya istirahat."', '{"tokens":["失う","彼は休息の","気づいた。","とはいえ、","健康を","に至って、","尊さに","失った"],"target_translation":"Baru setelah kehilangan kesehatannya, ia menyadari betapa berharganya istirahat.","romaji":"Kenkou o ushinau ni itatte, kare wa kyuusoku no toutosa ni kizuita."}'::jsonb, '["健康を","失う","に至って、","彼は休息の","尊さに","気づいた。"]'::jsonb, '失うに至って (baru ketika sampai kehilangan) memakai verba bentuk kamus.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah mencapai tahap ini, kita harus meninjau ulang seluruh strategi dari awal."', '{"display_text":"この段階に至っては、戦略全体を根本から見直すほかありません。","romaji":"Kono dankai ni itatte wa, senryaku zentai o konpon kara minaosu hoka arimasen.","phonetic_breakdown":["このだんかいに","いたっては","せんりゃくぜんたいを","こんぽんから","みなおすほかありません"]}'::jsonb, '{"expected_transcript":"この段階に至っては、戦略全体を根本から見直すほかありません。"}'::jsonb, 'この段階に至っては adalah ungkapan rapat eksekutif tingkat N1 saat menghadapi titik balik.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat sejarah bisnis: 明治時代___、日本の産業構造は急速な近代化を遂げた。', '{"options":["に至って","極まりなく","ずにはおかず","いかんによらず"],"translation":"Memasuki era Meiji, struktur industri Jepang mencapai modernisasi yang pesat.","sentence_template":"明治時代[blank]、日本の産業構造は急速な近代化を遂げた。"}'::jsonb, '{"selected":"に至って"}'::jsonb, 'Kata benda waktu/era (明治時代) + に至って menandai titik sejarah baru.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar analis keuangan. Apa pemicu mundurnya dewan direksi?', '{"audio_text":"不正会計の事実が第三者委員会によって公表されるに至り、経営陣は総辞職を決断した。","options":[{"id":"opt_1","text":"Kenaikan laba perusahaan yang melampaui target"},{"id":"opt_2","text":"Keinginan direksi untuk membuka cabang di Eropa"},{"id":"opt_3","text":"Terungkapnya fakta manipulasi akuntansi oleh komite independen hingga direksi memutuskan mundur massal"},{"id":"opt_4","text":"Berakhirnya masa jabatan rutin lima tahunan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '公表されるに至り (bentuk formal tertulis dari に至って) menandai titik balik yang memicu pengunduran diri.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Hingga saat terakhir pun, ia tetap mempertahankan pendiriannya."', '{"tokens":["瞬間に","彼は自分の","貫いた。","貫く","最後の","至るまで、","信念を","至って、"],"target_translation":"Hingga saat terakhir pun, ia tetap mempertahankan pendiriannya.","romaji":"Saigo no shunkan ni itaru made, kare wa jibun no shinnen o tsuranuita."}'::jsonb, '["最後の","瞬間に","至るまで、","彼は自分の","信念を","貫いた。"]'::jsonb, '～に至るまで berarti ''hingga mencapai titik (paling akhir)''.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan investigasi berikut. Bagaimana respons masyarakat terhadap skandal tersebut?', '{"audio_text":"当事者が責任を認めない姿勢を貫くに至っては、世論の批判が収まるはずもない。","options":[{"id":"opt_1","text":"Masyarakat memuji sikap pihak yang terlibat"},{"id":"opt_2","text":"Kritik publik mereda dengan sendirinya"},{"id":"opt_3","text":"Media massa berhenti memberitakan kasus tersebut"},{"id":"opt_4","text":"Karena pihak terkait sampai bersikeras tidak mengakui kesalahan, kritik publik tidak mungkin mereda"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '貫くに至っては menyoroti sikap ekstrem yang membuat kritik publik kian tak terbendung.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Baru pada abad ke-21 teknologi ini mulai diterapkan dalam kehidupan sehari-hari."', '{"tokens":["に至って、","ようやく","された。","実用化する","二十一世紀","この技術は","実用化","をもって、"],"target_translation":"Baru pada abad ke-21 teknologi ini mulai diterapkan dalam kehidupan sehari-hari.","romaji":"Nijuu-isseiki ni itatte, kono gijutsu wa youyaku jitsuyouka sareta."}'::jsonb, '["二十一世紀","に至って、","この技術は","ようやく","実用化","された。"]'::jsonb, '二十一世紀に至って menandai era ketika teknologi akhirnya masuk tahap penerapan praktis.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 交渉が完全に決裂する___、両社は法廷で争うこととなった。', '{"options":["に至り","なりに","とはいえ","に足らず"],"translation":"Hingga negosiasi benar-benar buntu/putus, kedua perusahaan akhirnya bersengketa di pengadilan.","sentence_template":"交渉が完全に決裂する[blank]、両社は法廷で争うこととなった。"}'::jsonb, '{"selected":"に至り"}'::jsonb, '決裂するに至り adalah bentuk tertulis formal N1 untuk hasil eskalasi negosiasi.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bahkan sampai hari ini, penyebab utama kecelakaan tersebut masih belum terungkap sepenuhnya."', '{"display_text":"現在に至るまで、その事故の根本原因は完全には解明されていません。","romaji":"Genzai ni itaru made, sono jiko no konpon genin wa kanzen ni wa kaimei sarete imasen.","phonetic_breakdown":["げんざいに","いたるまで","そのじこの","こんぽんげんいんは","かんぜんには","かいめいされていません"]}'::jsonb, '{"expected_transcript":"現在に至るまで、その事故の根本原因は完全には解明されていません。"}'::jsonb, '現在に至るまで (hingga sampai saat ini) adalah kolokasi berita dan laporan investigasi N1.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 主力商品の販売が急落する___、同社は事業転換を迫られた。', '{"options":["に至って","極まりない","ともなると","いかんによらず"],"translation":"Ketika penjualan produk andalan sampai anjlok drastis, perusahaan tersebut didesak melakukan transformasi bisnis.","sentence_template":"主力商品の販売が急落する[blank]、同社は事業転換を迫られた。"}'::jsonb, '{"selected":"に至って"}'::jsonb, '急落するに至って menandai titik kritis finansial yang memaksa perubahan model bisnis.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kutipan kuliah sosiologi. Apa yang dijelaskan dosen tentang proses urbanisasi?', '{"audio_text":"高度経済成長期に至って、農村から大都市への大規模な人口移動が加速した。","options":[{"id":"opt_1","text":"Pada masa pertumbuhan ekonomi tinggi, migrasi penduduk besar-besaran dari desa ke kota besar melaju pesat"},{"id":"opt_2","text":"Penduduk kota besar berbondong-bondong kembali ke desa pada masa itu"},{"id":"opt_3","text":"Pertumbuhan ekonomi Jepang terhenti selama era tersebut"},{"id":"opt_4","text":"Tidak ada perubahan demografi selama era pertumbuhan tinggi"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '高度経済成長期に至って menandai periode sejarah tertentu ketika fenomena mulai berakselerasi.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Masalah kecil yang dibiarkan akhirnya berkembang hingga memicu krisis kepercayaan."', '{"tokens":["放置され、","招く","至った。","を余儀なくされた。","小さな問題が","信頼危機を","に","招いた"],"target_translation":"Masalah kecil yang dibiarkan akhirnya berkembang hingga memicu krisis kepercayaan.","romaji":"Chiisana mondai ga houchi sare, shinrai kiki o maneku ni itatta."}'::jsonb, '["小さな問題が","放置され、","信頼危機を","招く","に","至った。"]'::jsonb, 'V-dict + に至った menyatakan hasil akhir ekstrem dari rangkaian proses sebelumnya.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah keadaan berkembang sampai sejauh ini, penjelasan terbuka kepada publik mutlak diperlukan."', '{"display_text":"ここに至っては、社会に対する誠実な説明責任を果たすほかありません。","romaji":"Koko ni itatte wa, shakai ni taisuru seijitsu na setsumei sekinin o hatasu hoka arimasen.","phonetic_breakdown":["ここに","いたっては","しゃかいにたいする","せいじつなせつめいせきにんを","はたすほかありません"]}'::jsonb, '{"expected_transcript":"ここに至っては、社会に対する誠実な説明責任を果たすほかありません。"}'::jsonb, 'ここに至っては (setelah sampai pada titik ini) adalah frasa idiomatik N1 tingkat tinggi.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: 長年の交渉の末、ようやく平和条約の___に至った。', '{"options":["締結","撤回","破棄","決裂"],"translation":"Setelah negosiasi bertahun-tahun, akhirnya tercapai penandatanganan perjanjian damai.","sentence_template":"長年の交渉の末、ようやく平和条約の[blank]に至った。"}'::jsonb, '{"selected":"締結"}'::jsonb, '締結に至る (mencapai tahap pengesahan/penandatanganan) adalah kolokasi resmi diplomasi dan hukum.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah melalui diskusi panjang, dewan akhirnya mencapai kesimpulan bersama."', '{"display_text":"度重なる議論の末、委員会はようやく合意形成に至りました。","romaji":"Tabikasanaru giron no sue, iinkai wa youyaku goui keisei ni itarimashita.","phonetic_breakdown":["たびかさなる","ぎろんのすえ","いいんかいはようやく","ごういけいせいに","いたりました"]}'::jsonb, '{"expected_transcript":"度重なる議論の末、委員会はようやく合意形成に至りました。"}'::jsonb, '合意形成に至る berarti berhasil mencapai konsensus.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa makna ～に至って dalam konteks ini?', '{"audio_text":"実際に被害が出てからに至って、ようやく自治体も避難計画の不備を認めた。","options":[{"id":"opt_1","text":"Pemerintah daerah mengakui kelemahan rencana evakuasi sebelum ada korban"},{"id":"opt_2","text":"Baru setelah korban benar-benar jatuh, pemerintah daerah akhirnya mengakui kekurangan rencana evakuasi"},{"id":"opt_3","text":"Rencana evakuasi pemerintah daerah sudah sempurna sejak awal"},{"id":"opt_4","text":"Warga menolak mengikuti rencana evakuasi"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '～に至って sering membawa nuansa kritik bahwa tindakan baru diambil setelah terlambat/mencapai titik kritis.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan bentuk yang tepat: 調査の結果、複数の部署で規則違反が常態化していた事実が明らかになる___。', '{"options":["に至った","を余儀なくされた","とはいえ","極まりない"],"translation":"Hasil investigasi sampai mengungkap fakta bahwa pelanggaran aturan sudah menjadi kebiasaan di beberapa divisi.","sentence_template":"調査の結果、複数の部署で規則違反が常態化していた事実が明らかになる[blank]。"}'::jsonb, '{"selected":"に至った"}'::jsonb, '明らかになるに至った menyatakan hasil akhir investigasi yang serius.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dari persiapan hingga pelaksanaan acara, semua proses berjalan tanpa hambatan."', '{"tokens":["実施","すべての工程が","進んだ。","進む","準備から","に至るまで、","順調に","に至って、"],"target_translation":"Dari persiapan hingga pelaksanaan acara, semua proses berjalan tanpa hambatan.","romaji":"Junbi kara jisshi ni itaru made, subete no koutei ga juncho ni susunda."}'::jsonb, '["準備から","実施","に至るまで、","すべての工程が","順調に","進んだ。"]'::jsonb, 'AからBに至るまで mencakup seluruh rentang proses dari awal hingga akhir.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan wawancara penulis buku. Kapan beliau memutuskan menulis memoar tersebut?', '{"audio_text":"定年退職を迎えて自身の歩みを振り返るに至り、次世代に伝えたい経験を一冊にまとめることにした。","options":[{"id":"opt_1","text":"Saat baru mulai bekerja di usia dua puluh tahun"},{"id":"opt_2","text":"Saat masih duduk di bangku kuliah"},{"id":"opt_3","text":"Saat memasuki masa pensiun dan menengok kembali perjalanan hidupnya"},{"id":"opt_4","text":"Setelah buku tersebut diterjemahkan ke bahasa asing"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '振り返るに至り menandai titik balik refleksi kehidupan saat pensiun.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 資金繰りが完全に行き詰まる___、銀行団への支援要請が決まった。', '{"options":["に至って","なりに","に足る","ずにはおかず"],"translation":"Ketika arus kas benar-benar buntu, diputuskan untuk meminta dukungan konsorsium bank.","sentence_template":"資金繰りが完全に行き詰まる[blank]、銀行団への支援要請が決まった。"}'::jsonb, '{"selected":"に至って"}'::jsonb, '行き詰まるに至って menandai kondisi finansial yang mencapai batas akhir.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mulai dari detail terkecil hingga kebijakan besar, semuanya ditinjau secara cermat."', '{"display_text":"細部に至るまで徹底的に検証した上で、最終報告書をまとめました。","romaji":"Saibu ni itaru made tetteiteki ni kenshou shita ue de, saishuu houkokusho o matomemashita.","phonetic_breakdown":["さいぶに","いたるまで","てっていてきに","けんしょうしたうえで","さいしゅうほうこくしょを","まとめました"]}'::jsonb, '{"expected_transcript":"細部に至るまで徹底的に検証した上で、最終報告書をまとめました。"}'::jsonb, '細部に至るまで (hingga ke detail terkecil) adalah frasa standar N1.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan berita ekonomi. Mengapa perusahaan teknologi itu menjual anak usahanya?', '{"audio_text":"業績の低迷が三年連続で続くに至り、経営再建のため子会社の売却に踏み切った。","options":[{"id":"opt_1","text":"Karena anak usaha tersebut mencatat rekor keuntungan tertinggi"},{"id":"opt_2","text":"Karena perusahaan ingin memperluas jaringan ritel"},{"id":"opt_3","text":"Karena kelesuan kinerja berlanjut tiga tahun berturut-turut sehingga terpaksa menjual anak usaha demi restrukturisasi"},{"id":"opt_4","text":"Karena aturan pajak baru melarang kepemilikan anak usaha"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '三年連続で続くに至り menandai eskalasi kerugian yang memicu keputusan restrukturisasi besar.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kini setelah mencapai tahap akhir proyek, jangan sampai lengah sedikit pun."', '{"tokens":["至って、","気を緩めては","ない。","緩めた","ここに","少しも","なら","をもって、"],"target_translation":"Kini setelah mencapai tahap akhir proyek, jangan sampai lengah sedikit pun.","romaji":"Koko ni itatte, sukoshi mo ki o yurumete wa naranai."}'::jsonb, '["ここに","至って、","少しも","気を緩めては","なら","ない。"]'::jsonb, 'ここに至って menegaskan momen krusial di garis akhir.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi berita berikut: 大規模な土砂崩れにより、周辺地域の住民は長期の避難生活___。', '{"options":["を余儀なくされた","に至った","とはいえ","に足る"],"translation":"Akibat tanah longsor berskala besar, warga di wilayah sekitar terpaksa menjalani kehidupan pengungsian jangka panjang.","sentence_template":"大規模な土砂崩れにより、周辺地域の住民は長期の避難生活[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, 'Kata benda + を余儀なくされる menyatakan keterpaksaan akibat faktor eksternal di luar kendali.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk kausatif yang tepat (memaksa pihak lain): 突然の輸入規制は、現地の輸出業者に事業計画の全面見直し___。', '{"options":["を余儀なくさせた","を余儀なくされた","に至らせた","をもってした"],"translation":"Regulasi impor yang mendadak memaksa para eksportir lokal meninjau ulang rencana bisnis secara menyeluruh.","sentence_template":"突然の輸入規制は、現地の輸出業者に事業計画の全面見直し[blank]。"}'::jsonb, '{"selected":"を余儀なくさせた"}'::jsonb, '～を余儀なくさせる adalah bentuk kausatif (aktor/faktor X memaksa pihak Y melakukan sesuatu).', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan ekonomi berikut. Dampak apa yang dialami maskapai penerbangan?', '{"audio_text":"燃料費の急激な高騰と国際情勢の悪化を受け、複数の航空会社が路線縮小を余儀なくされている。","options":[{"id":"opt_1","text":"Beberapa maskapai terpaksa menyusutkan rute penerbangan akibat lonjakan biaya bahan bakar dan memburuknya situasi internasional"},{"id":"opt_2","text":"Semua maskapai membuka puluhan rute baru bulan ini"},{"id":"opt_3","text":"Harga tiket pesawat internasional turun separuh"},{"id":"opt_4","text":"Biaya bahan bakar pesawat disubsidi penuh oleh bandara"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '路線縮小を余儀なくされている berarti terpaksa memangkas rute penerbangan.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Akibat pandemi global, banyak acara internasional terpaksa ditunda."', '{"tokens":["流行により、","延期","された。","とはいえ、","世界的な","多くの国際行事が","を余儀なく","を余儀なくさせた。"],"target_translation":"Akibat pandemi global, banyak acara internasional terpaksa ditunda.","romaji":"Sekai-teki na ryuukou ni yori, ooku no kokusai gyouji ga enki o yoginaku sareta."}'::jsonb, '["世界的な","流行により、","多くの国際行事が","延期","を余儀なく","された。"]'::jsonb, '延期を余儀なくされた adalah kolokasi berita N1 yang sangat sering muncul.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Akibat perubahan regulasi lingkungan, pabrik kami terpaksa mengganti seluruh peralatan produksi."', '{"display_text":"環境規制の強化に伴い、工場設備の全面刷新を余儀なくされました。","romaji":"Kankyou kisei no kyouka ni tomonai, koujou setsubi no zenmen sasshin o yoginaku saremashita.","phonetic_breakdown":["かんきょうきせいの","きょうかにともない","こうじょうせつびの","ぜんめんさっしんを","よぎなくされました"]}'::jsonb, '{"expected_transcript":"環境規制の強化に伴い、工場設備の全面刷新を余儀なくされました。"}'::jsonb, '全面刷新 (pembaruan menyeluruh) + を余儀なくされました sangat khas laporan korporasi N1.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予期せぬ為替変動により、同社は業績予想の下方修正___状況にある。', '{"options":["を余儀なくされる","極まりない","なりに","ずにはおかない"],"translation":"Akibat fluktuasi nilai tukar yang tak terduga, perusahaan tersebut berada dalam situasi terpaksa merevisi turun proyeksi kinerjanya.","sentence_template":"予期せぬ為替変動により、同社は業績予想の下方修正[blank]状況にある。"}'::jsonb, '{"selected":"を余儀なくされる"}'::jsonb, '下方修正を余儀なくされる状況 menyatakan posisi terpaksa menurunkan target keuangan.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan berita olahraga. Mengapa atlet unggulan itu batal tampil di final?', '{"audio_text":"準決勝で負った右膝の負傷が想定以上に重く、決勝戦の棄権を余儀なくされたとのことだ。","options":[{"id":"opt_1","text":"Ia memilih beristirahat untuk persiapan tahun depan"},{"id":"opt_2","text":"Ia terkena sanksi karena terlambat hadir"},{"id":"opt_3","text":"Cedera lutut kanan di semifinal lebih parah dari dugaan sehingga ia terpaksa mundur dari final"},{"id":"opt_4","text":"Pertandingan final dibatalkan karena hujan salju"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '棄権を余儀なくされた berarti terpaksa mengundurkan diri (walkover/withdraw).', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kekurangan semikonduktor memaksa produsen mobil mengurangi volume produksi."', '{"tokens":["自動車メーカーに","を","させた。","をもって、","半導体不足は","減産","余儀なく","された。"],"target_translation":"Kekurangan semikonduktor memaksa produsen mobil mengurangi volume produksi.","romaji":"Handoutai busoku wa jidousha meekaa ni gensan o yoginaku saseta."}'::jsonb, '["半導体不足は","自動車メーカーに","減産","を","余儀なく","させた。"]'::jsonb, '減産を余儀なくさせた memakai bentuk kausatif karena subjeknya adalah faktor penyebab (半導体不足).', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan wawancara pemilik penginapan tradisional. Mengapa mereka merenovasi bangunan secara besar-besaran?', '{"audio_text":"新たな耐震基準を満たすため、歴史ある木造建築であっても大規模な改修を余儀なくされたのです。","options":[{"id":"opt_1","text":"Untuk menarik wisatawan dengan desain futuristik"},{"id":"opt_2","text":"Karena mereka terpaksa melakukan renovasi besar demi memenuhi standar tahan gempa yang baru"},{"id":"opt_3","text":"Karena bangunan lama terbakar habis tahun lalu"},{"id":"opt_4","text":"Karena pemerintah kota membeli bangunan tersebut"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '大規模な改修を余儀なくされた menjelaskan keterpaksaan mematuhi standar tahan gempa baru.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Akibat pemadaman listrik luas, rumah sakit terpaksa menggunakan generator darurat."', '{"tokens":["病院は","稼働","された。","ともなると、","広域停電により、","非常用発電機の","を余儀なく","稼働する"],"target_translation":"Akibat pemadaman listrik luas, rumah sakit terpaksa menggunakan generator darurat.","romaji":"Kouiki teiden ni yori, byouin wa hijouyou hatsudenki no kadou o yoginaku sareta."}'::jsonb, '["広域停電により、","病院は","非常用発電機の","稼働","を余儀なく","された。"]'::jsonb, '稼働を余儀なくされた menggunakan kata benda 稼働 langsung sebelum を余儀なくされた.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 深刻な干ばつが続き、農家は作付け品目の変更___。', '{"options":["を余儀なくされている","に至っている","に足る","いかんによらず"],"translation":"Kekeringan parah terus berlanjut sehingga para petani terpaksa mengubah jenis tanaman yang ditanam.","sentence_template":"深刻な干ばつが続き、農家は作付け品目の変更[blank]。"}'::jsonb, '{"selected":"を余儀なくされている"}'::jsonb, '変更を余儀なくされている menyatakan kondisi keterpaksaan yang sedang berlangsung.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Akibat penghentian pasokan bahan baku, kami terpaksa menangguhkan penerimaan pesanan baru."', '{"display_text":"原材料の供給停止を受け、新規受注の一時停止を余儀なくされております。","romaji":"Genzairyou no kyoukyuu teishi o uke, shinki juchuu no ichiji teishi o yoginaku sarete orimasu.","phonetic_breakdown":["げんざいりょうの","きょうきゅうていしをうけ","しんきじゅちゅうの","いちじていしを","よぎなくされております"]}'::jsonb, '{"expected_transcript":"原材料の供給停止を受け、新規受注の一時停止を余儀なくされております。"}'::jsonb, '一時停止を余儀なくされております adalah ungkapan surat pemberitahuan resmi bisnis N1.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 競合他社の急速な台頭が、老舗企業にビジネスモデルの再構築___。', '{"options":["を余儀なくさせた","を余儀なくされた","とはいえ","極まりない"],"translation":"Kebangkitan pesat perusahaan pesaing memaksa perusahaan mapan membangun ulang model bisnisnya.","sentence_template":"競合他社の急速な台頭が、老舗企業にビジネスモデルの再構築[blank]。"}'::jsonb, '{"selected":"を余儀なくさせた"}'::jsonb, 'Subjek penyebab (台頭が) + pihak terdampak (老舗企業に) + 再構築を余儀なくさせた.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan bencana laut. Apa dampak tumpahan minyak bagi nelayan setempat?', '{"audio_text":"沿岸部の油流出事故により、地元の漁業協同組合は数ヶ月間にわたる禁漁を余儀なくされた。","options":[{"id":"opt_1","text":"Hasil tangkapan ikan meningkat dua kali lipat"},{"id":"opt_2","text":"Nelayan menerima kapal baru dari pemerintah"},{"id":"opt_3","text":"Harga ikan di pasar lokal turun drastis"},{"id":"opt_4","text":"Koperasi nelayan setempat terpaksa menghentikan penangkapan ikan selama beberapa bulan"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '禁漁を余儀なくされた berarti terpaksa menjalani larangan melaut/menangkap ikan.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Akibat konflik berkepanjangan, ribuan penduduk terpaksa meninggalkan kampung halaman mereka."', '{"tokens":["紛争により、","故郷からの脱出","された。","なりに、","長期化する","多くの住民が","を余儀なく","を余儀なくさせた。"],"target_translation":"Akibat konflik berkepanjangan, ribuan penduduk terpaksa meninggalkan kampung halaman mereka.","romaji":"Choukika suru funsou ni yori, ooku no juumin ga kokyou kara no dasshutsu o yoginaku sareta."}'::jsonb, '["長期化する","紛争により、","多くの住民が","故郷からの脱出","を余儀なく","された。"]'::jsonb, '脱出を余儀なくされた menyoroti penderitaan akibat faktor luar yang tak terelakkan.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena cuaca ekstrem yang belum pernah terjadi, jadwal konstruksi terpaksa diperpanjang."', '{"display_text":"記録的な悪天候のため、工期の大幅な延長を余儀なくされました。","romaji":"Kirokuteki na akutenkou no tame, kouki no oohaba na enchou o yoginaku saremashita.","phonetic_breakdown":["きろくてきな","あくてんこうのため","こうきのおおはばな","えんちょうを","よぎなくされました"]}'::jsonb, '{"expected_transcript":"記録的な悪天候のため、工期の大幅な延長を余儀なくされました。"}'::jsonb, '工期の延長 (perpanjangan jadwal proyek konstruksi) + を余儀なくされました.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata formal N1 yang tepat: 業績悪化のため、同社は人員の___を余儀なくされた。', '{"options":["削減","増強","表彰","歓迎"],"translation":"Akibat memburuknya kinerja, perusahaan tersebut terpaksa melakukan pengurangan pegawai.","sentence_template":"業績悪化のため、同社は人員の[blank]を余儀なくされた。"}'::jsonb, '{"selected":"削減"}'::jsonb, '人員削減 (pengurangan tenaga kerja) adalah kolokasi ekonomi/berita yang lazim dengan を余儀なくされる.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Akibat kebangkrutan mitra utama, perusahaan terpaksa meninjau ulang arus kasnya."', '{"display_text":"主要取引先の倒産により、資金計画の見直しを余儀なくされました。","romaji":"Shuyou torihikisaki no tousan ni yori, shikin keikaku no minaoshi o yoginaku saremashita.","phonetic_breakdown":["しゅようとりひきさきの","とうさんにより","しきんけいかくの","みなおしを","よぎなくされました"]}'::jsonb, '{"expected_transcript":"主要取引先の倒産により、資金計画の見直しを余儀なくされました。"}'::jsonb, '倒産 (kebangkrutan) dan 資金計画の見直し (peninjauan ulang rencana keuangan) adalah kosakata inti N1.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Siapa yang mengalami keterpaksaan dan apa penyebabnya?', '{"audio_text":"予算の大幅削減により、研究チームは実験規模の縮小を余儀なくされた。","options":[{"id":"opt_1","text":"Tim peneliti terpaksa mengecilkan skala eksperimen akibat pemangkasan anggaran besar-besaran"},{"id":"opt_2","text":"Tim peneliti meminta tambahan anggaran untuk memperbesar eksperimen"},{"id":"opt_3","text":"Pemangkasan anggaran membuat eksperimen selesai lebih cepat"},{"id":"opt_4","text":"Tim peneliti membubarkan diri sebelum anggaran dipotong"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '実験規模の縮小を余儀なくされた menunjukkan keterpaksaan akibat pemangkasan anggaran.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan kata benda yang tepat: 道路の陥没事故により、周辺は全面通行止め___。', '{"options":["を余儀なくされた","を余儀なくさせた","に至った","極まりない"],"translation":"Akibat insiden jalan amblas, area sekitar terpaksa ditutup total bagi lalu lintas.","sentence_template":"道路の陥没事故により、周辺は全面通行止め[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, '全面通行止めを余儀なくされた berarti terpaksa mengalami penutupan jalan total.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kenaikan suku bunga memaksa banyak pengembang properti menunda proyek baru."', '{"tokens":["多くの不動産会社に","を","させた。","とはいえ、","金利上昇は","新規計画の延期","余儀なく","された。"],"target_translation":"Kenaikan suku bunga memaksa banyak pengembang properti menunda proyek baru.","romaji":"Kinri joushou wa ooku no fudousan gaisha ni shinki keikaku no enki o yoginaku saseta."}'::jsonb, '["金利上昇は","多くの不動産会社に","新規計画の延期","を","余儀なく","させた。"]'::jsonb, 'Kausatif を余儀なくさせた menghubungkan penyebab ekonomi dengan dampaknya pada pelaku industri.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan laporan cuaca. Mengapa festival kembang api harus dipindahkan tanggalnya?', '{"audio_text":"強風と高波の恐れがあるため、主催者は開催日の順延を余儀なくされたと発表した。","options":[{"id":"opt_1","text":"Karena tidak ada penonton yang membeli tiket"},{"id":"opt_2","text":"Karena panitia terpaksa menunda tanggal pelaksanaan akibat potensi angin kencang dan ombak tinggi"},{"id":"opt_3","text":"Karena kembang api belum dikirim dari pabrik"},{"id":"opt_4","text":"Karena lokasi pantai sedang direnovasi"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '開催日の順延 (penundaan tanggal pelaksanaan ke hari cadangan) + を余儀なくされた.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 急激な人口流出により、その村の小学校は統廃合___。', '{"options":["を余儀なくされた","ずにはおかない","に足る","ともなると"],"translation":"Akibat keluarnya penduduk secara drastis, sekolah dasar di desa itu terpaksa digabungkan/ditutup.","sentence_template":"急激な人口流出により、その村の小学校は統廃合[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, '統廃合 (penggabungan dan penutupan fasilitas) + を余儀なくされた adalah isu sosial klasik Jepang.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Akibat kelangkaan bahan baku impor, kami terpaksa beralih ke pemasok domestik."', '{"display_text":"輸入資材の不足により、国内調達への切り替えを余儀なくされました。","romaji":"Yunyuu shizai no fusoku ni yori, kokunai choutatsu e no kirikae o yoginaku saremashita.","phonetic_breakdown":["ゆにゅうしざいの","ふそくにより","こくないちょうたつへの","きりかえを","よぎなくされました"]}'::jsonb, '{"expected_transcript":"輸入資材の不足により、国内調達への切り替えを余儀なくされました。"}'::jsonb, '切り替えを余儀なくされました berarti terpaksa melakukan peralihan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kutipan berita internasional. Apa konsekuensi sanksi dagang tersebut?', '{"audio_text":"関税の大幅引き上げを受け、輸出依存度の高い中小企業は苦境に立たされ、生産拠点の移転を余儀なくされている。","options":[{"id":"opt_1","text":"UKM eksportir mendapatkan keuntungan berlipat ganda"},{"id":"opt_2","text":"Tarif bea masuk dihapuskan sepenuhnya"},{"id":"opt_3","text":"UKM yang bergantung pada ekspor terpaksa memindahkan basis produksinya akibat kenaikan tarif besar"},{"id":"opt_4","text":"Semua pabrik di dalam negeri menambah jam kerja"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '生産拠点の移転を余儀なくされている berarti terpaksa merelokasi basis produksi.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Cedera serius di tengah musim memaksa sang kapten absen jangka panjang."', '{"tokens":["キャプテンは","を","された。","をもって、","深刻な怪我により、","長期離脱","余儀なく","させた。"],"target_translation":"Cedera serius di tengah musim memaksa sang kapten absen jangka panjang.","romaji":"Shinkoku na kega ni yori, kyaputen wa chouki ridatsu o yoginaku sareta."}'::jsonb, '["深刻な怪我により、","キャプテンは","長期離脱","を","余儀なく","された。"]'::jsonb, '長期離脱を余儀なくされた (terpaksa absen jangka panjang) lazim dalam liputan olahraga N1.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi tajuk rencana berikut: 景気回復の兆しが見え始めた___、中小企業の経営環境は依然として厳しい。', '{"options":["とはいえ","をもって","を余儀なくされ","極まりない"],"translation":"Meskipun memang tanda-tanda pemulihan ekonomi mulai terlihat, iklim usaha UKM tetap saja masih berat.","sentence_template":"景気回復の兆しが見え始めた[blank]、中小企業の経営環境は依然として厳しい。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '～とはいえ mengakui kebenaran klausa pertama terlebih dahulu, lalu menyampaikan realitas atau catatan kontras.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah kata benda: 経験豊富なベテラン___、初めての市場では慎重な調査が欠かせない。', '{"options":["とはいえ","に至って","ともなると","ずにはおかず"],"translation":"Meskipun ia seorang veteran berpengalaman, riset yang cermat tetap mutlak diperlukan di pasar yang baru pertama kali dimasuki.","sentence_template":"経験豊富なベテラン[blank]、初めての市場では慎重な調査が欠かせない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, 'Kata benda (ベテラン) dapat langsung diikuti とはいえ (atau であるとはいえ).', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar editor surat kabar. Apa penilaian berimbang beliau terhadap AI generatif?', '{"audio_text":"生成AIが業務効率を飛躍的に高めたとはいえ、情報の正確性を人間が検証する工程は省けない。","options":[{"id":"opt_1","text":"AI generatif sama sekali tidak meningkatkan efisiensi kerja"},{"id":"opt_2","text":"Meskipun AI generatif meningkatkan efisiensi kerja secara drastis, proses verifikasi akurasi oleh manusia tetap tidak boleh dihilangkan"},{"id":"opt_3","text":"Manusia tidak perlu lagi memeriksa data yang dihasilkan AI"},{"id":"opt_4","text":"Perusahaan harus melarang penggunaan semua perangkat lunak komputer"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '高めたとはいえ mengakui manfaat AI, lalu menegaskan syarat penting 検証する工程は省けない.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun sudah memasuki bulan April, udara pagi masih terasa cukup dingin."', '{"tokens":["入った","朝の空気は","肌寒い。","肌寒かった。","四月に","とはいえ、","まだ","をもって、"],"target_translation":"Meskipun sudah memasuki bulan April, udara pagi masih terasa cukup dingin.","romaji":"Shigatsu ni haitta to wa ie, asa no kuuki wa mada hadazamui."}'::jsonb, '["四月に","入った","とはいえ、","朝の空気は","まだ","肌寒い。"]'::jsonb, '四月に入ったとはいえ mengakui fakta kalender sebelum kontras cuaca まだ肌寒い.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun dikatakan bebas biaya, tetap ada syarat dan ketentuan yang harus diperhatikan."', '{"display_text":"無料とはいえ、利用にあたってはいくつかの注意点があります。","romaji":"Muryou to wa ie, riyou ni atatte wa ikutsuka no chuuiten ga arimasu.","phonetic_breakdown":["むりょう","とはいえ","りようにあたっては","いくつかの","ちゅういてんがあります"]}'::jsonb, '{"expected_transcript":"無料とはいえ、利用にあたってはいくつかの注意点があります。"}'::jsonb, '無料とはいえ (meskipun gratis) sangat lazim dalam penjelasan layanan dan perjanjian.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: オンライン会議が定着した___、重要な信頼構築には対面での対話が有効だ。', '{"options":["とはいえ","なりに","に足らず","いかんによらず"],"translation":"Meskipun rapat daring sudah mengakar, dialog tatap muka tetap efektif untuk membangun kepercayaan penting.","sentence_template":"オンライン会議が定着した[blank]、重要な信頼構築には対面での対話が有効だ。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '定着したとはいえ mengakui tren kerja digital sambil mempertahankan nilai pertemuan langsung.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan pakar pendidikan. Apa catatannya terhadap pembelajaran digital?', '{"audio_text":"タブレット教材は便利だとはいえ、紙に書いて思考を整理する力の育成も軽視すべきではない。","options":[{"id":"opt_1","text":"Semua buku tulis kertas harus dibuang dari sekolah"},{"id":"opt_2","text":"Tablet sama sekali tidak berguna untuk belajar"},{"id":"opt_3","text":"Meskipun materi tablet praktis, pengembangan kemampuan menata pikiran dengan menulis di kertas tidak boleh diremehkan"},{"id":"opt_4","text":"Siswa tidak boleh menggunakan komputer sebelum lulus kuliah"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '便利だとはいえ (bentuk biasa kata sifat-na + とはいえ) menyajikan argumen seimbang.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun hanya proyek kecil, kita harus mengerjakannya dengan penuh tanggung jawab."', '{"tokens":["とはいえ、","持って","べきだ。","取り組んだ","小さな案件","責任を","取り組む","に至って、"],"target_translation":"Meskipun hanya proyek kecil, kita harus mengerjakannya dengan penuh tanggung jawab.","romaji":"Chiisana anken to wa ie, sekinin o motte torikumu beki da."}'::jsonb, '["小さな案件","とはいえ、","責任を","持って","取り組む","べきだ。"]'::jsonb, '小さな案件とはいえ menegaskan profesionalisme meski skala proyek kecil.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan tanggapan manajer risiko. Apa peringatan beliau meski penjualan naik?', '{"audio_text":"今期の売上が過去最高を更新したとはいえ、利益率の低下から目を背けるわけにはいかない。","options":[{"id":"opt_1","text":"Meskipun penjualan periode ini memecahkan rekor tertinggi, kita tidak boleh menutup mata dari penurunan margin laba"},{"id":"opt_2","text":"Margin laba perusahaan juga mencapai rekor tertinggi"},{"id":"opt_3","text":"Penjualan periode ini turun drastis dibanding tahun lalu"},{"id":"opt_4","text":"Perusahaan tidak perlu memantau laporan keuangan lagi"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '更新したとはいえ mengakui rekor penjualan sambil mengingatkan risiko penurunan 利益率.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun sudah pensiun dari jabatan resmi, beliau masih aktif memberi nasihat."', '{"tokens":["退いた","先生は今も","続けている。","を余儀なくされ、","現役を","とはいえ、","助言を","退く"],"target_translation":"Meskipun sudah pensiun dari jabatan resmi, beliau masih aktif memberi nasihat.","romaji":"Geneki o shirizoita to wa ie, sensei wa ima mo jogen o tsuzukete iru."}'::jsonb, '["現役を","退いた","とはいえ、","先生は今も","助言を","続けている。"]'::jsonb, '現役を退いたとはいえ mengakui status pensiun sebelum kontras aktivitas sekarang.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 都市部に比べて物価が安い___、車がないと生活しにくい地域もある。', '{"options":["とはいえ","極まりない","ずにはおかない","ともなると"],"translation":"Meskipun biaya hidup lebih murah dibanding perkotaan, ada juga daerah yang sulit ditinggali tanpa mobil.","sentence_template":"都市部に比べて物価が安い[blank]、車がないと生活しにくい地域もある。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, 'Kata sifat-i (安い) langsung tersambung ke とはいえ.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun telah meminta maaf secara resmi, memulihkan kepercayaan pelanggan butuh waktu lama."', '{"display_text":"公式に謝罪したとはいえ、失った信頼を取り戻すには長い時間がかかります。","romaji":"Koushiki ni shazai shita to wa ie, ushinatta shinrai o torimodosu ni wa nagai jikan ga kakarimasu.","phonetic_breakdown":["こうしきに","しゃざいしたとはいえ","うしなったしんらいを","とりもどすには","ながいじかんがかかります"]}'::jsonb, '{"expected_transcript":"公式に謝罪したとはいえ、失った信頼を取り戻すには長い時間がかかります。"}'::jsonb, '公式に謝罪したとはいえ menyajikan realitas manajemen krisis secara objektif.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 自由な校風___、最低限の規律やマナーは厳しく指導される。', '{"options":["とはいえ","をもって","に至って","に足る"],"translation":"Meskipun memiliki budaya sekolah yang bebas, disiplin dan tata krama dasar tetap dibimbing dengan tegas.","sentence_template":"自由な校風[blank]、最低限の規律やマナーは厳しく指導される。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '自由な校風とはいえ mengontraskan kebebasan budaya sekolah dengan ketegasan disiplin dasar.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kritik pengamat lingkungan. Apa masalah yang masih tersisa?', '{"audio_text":"再生可能エネルギーの比率が高まったとはいえ、送電網の整備が追いついていないのが実情だ。","options":[{"id":"opt_1","text":"Jaringan transmisi listrik sudah jauh melampaui kebutuhan"},{"id":"opt_2","text":"Energi terbarukan belum pernah digunakan di negara ini"},{"id":"opt_3","text":"Biaya listrik turun menjadi gratis di seluruh kota"},{"id":"opt_4","text":"Meskipun rasio energi terbarukan meningkat, kenyataannya pembangunan jaringan transmisi belum mampu mengejar"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '高まったとはいえ dikontraskan dengan 送電網の整備が追いついていないのが実情だ.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun disebut bahasa yang sulit, jika belajar rutin pasti akan ada kemajuan."', '{"tokens":["とはいえ、","必ず","する。","極まりなく、","難しい言語","毎日続ければ","上達","上達した"],"target_translation":"Meskipun disebut bahasa yang sulit, jika belajar rutin pasti akan ada kemajuan.","romaji":"Muzukashii gengo to wa ie, mainichi tsuzukereba kanarazu joutatsu suru."}'::jsonb, '["難しい言語","とはいえ、","毎日続ければ","必ず","上達","する。"]'::jsonb, '難しい言語とはいえ mengakui kesulitan sambil memberi dorongan realistis.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun hanya untuk sementara waktu, perubahan prosedur ini sangat membantu tim lapangan."', '{"display_text":"一時的な措置とはいえ、この手続き変更は現場の負担を大きく減らしました。","romaji":"Ichijiteki na sochi to wa ie, kono tetsuzuki henkou wa genba no futan o ookiku herashimashita.","phonetic_breakdown":["いちじてきな","そちとはいえ","このてつづきへんこうは","げんばのふたんを","おおきくへらしました"]}'::jsonb, '{"expected_transcript":"一時的な措置とはいえ、この手続き変更は現場の負担を大きく減らしました。"}'::jsonb, '一時的な措置とはいえ (meskipun langkah sementara) lazim dalam evaluasi operasional.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: 暫定的な___とはいえ、両国の対話が再開された意義は大きい。', '{"options":["合意","決裂","拒否","撤退"],"translation":"Meskipun baru kesepakatan sementara, makna dimulainya kembali dialog kedua negara sangatlah besar.","sentence_template":"暫定的な[blank]とはいえ、両国の対話が再開された意義は大きい。"}'::jsonb, '{"selected":"合意"}'::jsonb, '暫定的な合意 (kesepakatan sementara) adalah kolokasi diplomasi dan hukum bisnis N1.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun masih dalam tahap uji coba, hasilnya menunjukkan potensi yang menjanjikan."', '{"display_text":"まだ試験段階とはいえ、十分に実用化が期待できる結果です。","romaji":"Mada shiken dankai to wa ie, juubun ni jitsuyouka ga kitai dekiru kekka desu.","phonetic_breakdown":["まだ","しけんだんかいとはいえ","じゅうぶんに","じつようかがきたいできる","けっかです"]}'::jsonb, '{"expected_transcript":"まだ試験段階とはいえ、十分に実用化が期待できる結果です。"}'::jsonb, '試験段階とはいえ (meskipun masih tahap uji coba) umum dalam laporan R&D.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Manakah ringkasan yang paling akurat?', '{"audio_text":"仕事が忙しいとはいえ、家族と過ごす時間まで削ってしまっては本末転倒だ。","options":[{"id":"opt_1","text":"Mengorbankan waktu bersama keluarga karena sibuk kerja adalah hal yang keliru tujuan meskipun pekerjaan memang padat"},{"id":"opt_2","text":"Pekerjaan harus selalu mengalahkan waktu bersama keluarga"},{"id":"opt_3","text":"Pembicara sedang tidak memiliki pekerjaan sama sekali"},{"id":"opt_4","text":"Keluarga tidak perlu menghabiskan waktu bersama"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '本末転倒 (terbalik antara tujuan dan sarana) menegaskan evaluasi kritis setelah 忙しいとはいえ.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan struktur yang tepat: 予算が限られている___、品質を妥協するつもりはない。', '{"options":["とはいえ","を余儀なくされ","をもって","なりに"],"translation":"Meskipun anggaran memang terbatas, kami tidak berniat mengorbankan kualitas.","sentence_template":"予算が限られている[blank]、品質を妥協するつもりはない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '限られているとはいえ mengakui keterbatasan anggaran sebelum menegaskan komitmen kualitas.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun mendapat dukungan mayoritas, kita tetap perlu mendengarkan suara minoritas."', '{"tokens":["得た","少数意見にも","べきだ。","に至って、","多数の支持を","とはいえ、","耳を傾ける","得る"],"target_translation":"Meskipun mendapat dukungan mayoritas, kita tetap perlu mendengarkan suara minoritas.","romaji":"Tasuu no shiji o eta to wa ie, shousuu iken ni mo mimi o katamukeru beki da."}'::jsonb, '["多数の支持を","得た","とはいえ、","少数意見にも","耳を傾ける","べきだ。"]'::jsonb, '耳を傾ける (mendengarkan dengan saksama) + とはいえ menonjolkan prinsip demokrasi berimbang.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan arsitektur. Apa penilaian pengamat tentang gedung bersejarah itu?', '{"audio_text":"築百年を超える古い建物とはいえ、保存状態が極めて良好で現代の耐震基準も満たしている。","options":[{"id":"opt_1","text":"Gedung itu sudah runtuh karena terlalu tua"},{"id":"opt_2","text":"Meskipun bangunan tua berusia lebih dari seratus tahun, kondisi pemeliharaannya amat baik dan memenuhi standar tahan gempa modern"},{"id":"opt_3","text":"Gedung itu tidak boleh dikunjungi oleh siapa pun"},{"id":"opt_4","text":"Gedung itu baru selesai dibangun tahun lalu"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '古い建物とはいえ mengakui usianya sambil memuji kondisi pemeliharaan dan keamanannya.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 専門外___、基本的な財務諸表くらいは読めるようにしておきたい。', '{"options":["とはいえ","ともなると","に足らず","いかんによらず"],"translation":"Meskipun di luar bidang keahlian saya, setidaknya saya ingin bisa membaca laporan keuangan dasar.","sentence_template":"専門外[blank]、基本的な財務諸表くらいは読めるようにしておきたい。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '専門外とはいえ adalah ungkapan rendah hati sekaligus proaktif dalam pengembangan diri.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun hanya sumbangsih kecil, saya berharap dapat berguna bagi masyarakat lokal."', '{"display_text":"微力とはいえ、地域社会の発展に貢献できれば幸いです。","romaji":"Biryoku to wa ie, chiiki shakai no hatten ni kouken dekireba saiwai desu.","phonetic_breakdown":["びりょく","とはいえ","ちいきしゃかいのはってんに","こうけんできれば","さいわいです"]}'::jsonb, '{"expected_transcript":"微力とはいえ、地域社会の発展に貢献できれば幸いです。"}'::jsonb, '微力とはいえ (meskipun tenaga/kontribusi saya kecil) adalah ungkapan rendah hati yang sangat elegan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan analisis berita teknologi. Apa kesimpulan narasumber?', '{"audio_text":"電池の性能が飛躍的に向上したとはいえ、寒冷地での航続距離にはまだ課題が残る。","options":[{"id":"opt_1","text":"Baterai kendaraan listrik sudah tidak punya kelemahan sama sekali"},{"id":"opt_2","text":"Kendaraan listrik tidak bisa berjalan di musim panas"},{"id":"opt_3","text":"Meskipun performa baterai meningkat pesat, jarak tempuh di daerah beriklim dingin masih menyisakan tantangan"},{"id":"opt_4","text":"Teknologi baterai tidak mengalami perkembangan selama dua puluh tahun"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '向上したとはいえ diikuti catatan teknis objektif 課題が残る.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun dikatakan sebagai rekan dekat, ada batas privasi yang harus dijaga."', '{"tokens":["とはいえ、","配慮","だ。","極まりない。","親しい仲間","プライバシーには","すべき","配慮した"],"target_translation":"Meskipun dikatakan sebagai rekan dekat, ada batas privasi yang harus dijaga.","romaji":"Shitashii nakama to wa ie, puraibashii ni wa hairyo subeki da."}'::jsonb, '["親しい仲間","とはいえ、","プライバシーには","配慮","すべき","だ。"]'::jsonb, '親しい仲間とはいえ menegaskan etika menjaga batas privasi.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pengumuman resmi penutupan pendaftaran berikut: 本日の午後五時___、今年度の応募受付を終了いたします。', '{"options":["をもって","とはいえ","なりに","ともなると"],"translation":"Terhitung pukul 17.00 hari ini, penerimaan pendaftaran tahun fiskal ini resmi ditutup.","sentence_template":"本日の午後五時[blank]、今年度の応募受付を終了いたします。"}'::jsonb, '{"selected":"をもって"}'::jsonb, 'Waktu/tanggal + をもって menandai batas akhir atau titik pemberlakuan secara sangat resmi.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk sarana resmi dalam surat bisnis: 選考結果につきましては、書面___ご通知申し上げます。', '{"options":["をもって","に至って","を余儀なくされ","極まりなく"],"translation":"Mengenai hasil seleksi, kami akan memberitahukannya secara resmi melalui surat tertulis.","sentence_template":"選考結果につきましては、書面[blank]ご通知申し上げます。"}'::jsonb, '{"selected":"をもって"}'::jsonb, '書面をもって (dengan/melalui dokumen tertulis) menyatakan sarana resmi formal.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman penutupan pameran. Kapan pameran tersebut berakhir?', '{"audio_text":"皆様にご愛顧いただきました特別展は、今月末日をもって閉幕いたします。","options":[{"id":"opt_1","text":"Pameran diperpanjang tanpa batas waktu"},{"id":"opt_2","text":"Pameran khusus tersebut resmi berakhir pada hari terakhir bulan ini"},{"id":"opt_3","text":"Pameran baru akan dibuka awal bulan depan"},{"id":"opt_4","text":"Pameran ditutup mendadak hari ini karena hujan"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '今月末日をもって閉幕いたします berarti resmi berakhir terhitung hari terakhir bulan ini.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dengan ini, saya akhiri sambutan pembukaan saya."', '{"tokens":["をもって、","挨拶","いただきます。","挨拶した","以上","開会の","とさせて","とはいえ、"],"target_translation":"Dengan ini, saya akhiri sambutan pembukaan saya.","romaji":"Ijou o motte, kaikai no aisatsu to sasete itadakimasu."}'::jsonb, '["以上","をもって、","開会の","挨拶","とさせて","いただきます。"]'::jsonb, '以上をもって adalah penutup pidato resmi paling klasik dalam bahasa Jepang formal.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan menangani setiap masukan pelanggan dengan ketulusan penuh."', '{"display_text":"お客様のご意見には、誠意をもって対応させていただきます。","romaji":"Okyakusama no goiken ni wa, seii o motte taiou sasete itadakimasu.","phonetic_breakdown":["おきゃくさまの","ごいけんには","せいいをもって","たいおうさせて","いただきます"]}'::jsonb, '{"expected_transcript":"お客様のご意見には、誠意をもって対応させていただきます。"}'::jsonb, '誠意をもって (dengan ketulusan penuh) adalah kolokasi korporasi yang wajib dikuasai di N1.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat resmi berikut: 三月三十一日___、現行の旧システムは完全に運用を終了する。', '{"options":["をもって","ずにはおかず","に足らず","いかんによらず"],"translation":"Terhitung tanggal 31 Maret, sistem lama yang berlaku saat ini akan sepenuhnya mengakhiri operasionalnya.","sentence_template":"三月三十一日[blank]、現行の旧システムは完全に運用を終了する。"}'::jsonb, '{"selected":"をもって"}'::jsonb, 'Tanggal + をもって menyatakan tenggat resmi berakhirnya suatu layanan atau sistem.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan. Bagaimana cara pemberitahuan pengumuman pemenang?', '{"audio_text":"当選者の発表は、賞品の発送をもって代えさせていただきます。","options":[{"id":"opt_1","text":"Daftar pemenang akan diumumkan di televisi nasional"},{"id":"opt_2","text":"Pemenang harus datang sendiri mengambil sertifikat"},{"id":"opt_3","text":"Pengumuman pemenang digantikan langsung oleh pengiriman hadiahnya"},{"id":"opt_4","text":"Undian dibatalkan karena peserta kurang"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '発送をもって代えさせていただきます adalah kalimat baku kampanye/undian resmi di Jepang.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kami menyampaikan ucapan selamat secara resmi melalui surat ini."', '{"tokens":["をもって、","お祝い","ます。","申し上げた","書中","心より","申し上げ","なりに、"],"target_translation":"Kami menyampaikan ucapan selamat secara resmi melalui surat ini.","romaji":"Shochuu o motte kokoro yori oiwai moushiagemasu."}'::jsonb, '["書中","をもって、","心より","お祝い","申し上げ","ます。"]'::jsonb, '書中をもって (melalui surat ini) adalah ungkapan super-formal dalam korespondensi korporasi.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman direksi. Kapan perubahan struktur organisasi resmi berlaku?', '{"audio_text":"来る四月一日をもって、営業本部と海外事業部を統合し、新体制へ移行いたします。","options":[{"id":"opt_1","text":"Mulai 1 April mendatang, divisi penjualan dan bisnis luar negeri resmi digabung menuju struktur baru"},{"id":"opt_2","text":"Perusahaan menutup seluruh divisi penjualan mulai 1 April"},{"id":"opt_3","text":"Penggabungan divisi dibatalkan hingga tahun depan"},{"id":"opt_4","text":"Divisi luar negeri dipisahkan menjadi perusahaan mandiri"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '来る四月一日をもって (terhitung 1 April mendatang) menyatakan tanggal efektif keputusan organisasi.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dengan upacara ini, seluruh rangkaian acara peringatan resmi berakhir."', '{"tokens":["をもって、","全日程を","いたします。","終了した","これ","記念行事の","終了","とはいえ、"],"target_translation":"Dengan upacara ini, seluruh rangkaian acara peringatan resmi berakhir.","romaji":"Kore o motte, kinen gyoushi no zen nittei o shuuryou itashimasu."}'::jsonb, '["これ","をもって、","記念行事の","全日程を","終了","いたします。"]'::jsonb, 'これをもって (dengan ini) adalah penutup resmi upacara dan rapat formal.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 弊社は品質の安定と迅速な対応___、顧客満足の向上に努めている。', '{"options":["をもって","に至って","を余儀なくされ","極まりなく"],"translation":"Perusahaan kami berupaya meningkatkan kepuasan pelanggan melalui stabilitas kualitas dan respons cepat.","sentence_template":"弊社は品質の安定と迅速な対応[blank]、顧客満足の向上に努めている。"}'::jsonb, '{"selected":"をもって"}'::jsonb, '～をもって menyatakan sarana/prinsip utama yang dijadikan landasan upaya perusahaan.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terhitung akhir bulan ini, saya resmi mengundurkan diri dari jabatan ini."', '{"display_text":"今月末をもちまして、退職することとなりました。","romaji":"Kongetsumatsu o mochimashite, taishoku suru koto to narimashita.","phonetic_breakdown":["こんげつまつを","もちまして","たいしょくすることと","なりました"]}'::jsonb, '{"expected_transcript":"今月末をもちまして、退職することとなりました。"}'::jsonb, '～をもちまして adalah versi lebih sopan (teineigo) dari ～をもって dalam surat atau pidato perpisahan.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 規則に反する行為に対しては、厳正な態度___臨む方針だ。', '{"options":["をもって","なりに","に足る","ともなると"],"translation":"Terhadap tindakan yang melanggar aturan, kebijakan kami adalah menghadapinya dengan sikap tegas dan adil.","sentence_template":"規則に反する行為に対しては、厳正な態度[blank]臨む方針だ。"}'::jsonb, '{"selected":"をもって"}'::jsonb, '厳正な態度をもって臨む (menghadapi dengan sikap tegas dan objektif) adalah kolokasi N1.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman di gedung pertemuan. Apa yang baru saja diumumkan?', '{"audio_text":"ただいまの発表をもちまして、本日のシンポジウムの全プログラムを終了させていただきます。","options":[{"id":"opt_1","text":"Simposium baru saja dimulai"},{"id":"opt_2","text":"Akan ada sesi tambahan selama dua jam"},{"id":"opt_3","text":"Peserta diminta pindah ke gedung sebelah"},{"id":"opt_4","text":"Dengan berakhirnya presentasi barusan, seluruh rangkaian program simposium hari ini resmi ditutup"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '～をもちまして…終了させていただきます adalah frasa penutup acara resmi tingkat N1.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kami akan menjawab harapan masyarakat melalui hasil penelitian yang nyata."', '{"tokens":["成果","社会の期待に","たい。","いかんによらず、","研究の","をもって、","応え","に応えた"],"target_translation":"Kami akan menjawab harapan masyarakat melalui hasil penelitian yang nyata.","romaji":"Kenkyuu no seika o motte, shakai no kitai ni kotaetai."}'::jsonb, '["研究の","成果","をもって、","社会の期待に","応え","たい。"]'::jsonb, '成果をもって (dengan hasil nyata sebagai sarana/bukti) berpasangan alami dengan 期待に応える.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terhitung hari ini, layanan konsultasi daring kami resmi dibuka untuk umum."', '{"display_text":"本日をもって、オンライン相談窓口の運用を開始いたします。","romaji":"Honjitsu o motte, onrain soudan madoguchi no unyou o kaishi itashimasu.","phonetic_breakdown":["ほんじつをもって","おんらいんそうだんまどぐちの","うんようを","かいしいたします"]}'::jsonb, '{"expected_transcript":"本日をもって、オンライン相談窓口の運用を開始いたします。"}'::jsonb, '本日をもって (terhitung hari ini) menegaskan titik awal resmi beroperasinya layanan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: 本日の会議はこれをもって___といたします。', '{"options":["閉会","開会","欠席","延期"],"translation":"Dengan ini, rapat hari ini resmi dinyatakan selesai/ditutup.","sentence_template":"本日の会議はこれをもって[blank]といたします。"}'::jsonb, '{"selected":"閉会"}'::jsonb, 'これをもって閉会といたします adalah kalimat penutup rapat resmi.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami mengucapkan terima kasih yang tulus melalui pesan tertulis ini."', '{"display_text":"略儀ながら書中をもって厚く御礼申し上げます。","romaji":"Ryakugi nagara shochuu o motte atsuku orei moushiagemasu.","phonetic_breakdown":["りゃくぎながら","しょちゅうをもって","あつくおれい","もうしあげます"]}'::jsonb, '{"expected_transcript":"略儀ながら書中をもって厚く御礼申し上げます。"}'::jsonb, '略儀ながら書中をもって (meski secara singkat melalui surat ini) adalah salam surat formal klasik.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Fungsi apakah yang dimiliki ～をもって di sini?', '{"audio_text":"本件に関するお申し込みは、明日正午をもって締め切らせていただきます。","options":[{"id":"opt_1","text":"Menyatakan batas akhir resmi pendaftaran, yaitu besok pukul 12 siang"},{"id":"opt_2","text":"Menyatakan alasan pembatalan acara"},{"id":"opt_3","text":"Menyatakan perbandingan antara dua produk"},{"id":"opt_4","text":"Menyatakan keterpaksaan karena bencana"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '明日正午をもって締め切る menggunakan をもって untuk menandai tenggat akhir resmi.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan bentuk sopan: 本年十二月末日___、当該店舗は営業を終了いたします。', '{"options":["をもちまして","に至りまして","とはいえまして","なりまして"],"translation":"Terhitung hari terakhir Desember tahun ini, gerai tersebut resmi mengakhiri operasionalnya.","sentence_template":"本年十二月末日[blank]、当該店舗は営業を終了いたします。"}'::jsonb, '{"selected":"をもちまして"}'::jsonb, '～をもちまして adalah padanan sopan resmi dari ～をもって untuk pengumuman publik.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kami berupaya memecahkan masalah melalui dialog yang sabar dan terbuka."', '{"tokens":["対話","問題の平和的な","図る。","とはいえ、","粘り強い","をもって、","解決を","図った"],"target_translation":"Kami berupaya memecahkan masalah melalui dialog yang sabar dan terbuka.","romaji":"Taiwa o motte, mondai no heiwa-teki na kaiketsu o hakaru."}'::jsonb, '["粘り強い","対話","をもって、","問題の平和的な","解決を","図る。"]'::jsonb, '対話をもって (dengan sarana dialog) lazim dalam pernyataan diplomatik dan korporasi.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman universitas. Bagaimana hasil kelulusan diumumkan?', '{"audio_text":"合格発表は、大学公式サイトへの受験番号の掲載をもって行います。","options":[{"id":"opt_1","text":"Hasil kelulusan dikirim melalui telepon satu per satu"},{"id":"opt_2","text":"Pengumuman kelulusan dilakukan melalui penayangan nomor ujian di situs resmi universitas"},{"id":"opt_3","text":"Peserta harus datang ke kantor pos pusat"},{"id":"opt_4","text":"Hasil kelulusan tidak akan diumumkan kepada publik"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '掲載をもって行います menyatakan mekanisme resmi pengumuman.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼の実績___すれば、次期部長に推されるのも当然だ。', '{"options":["をもって","なりに","極まりなく","ずにはおかず"],"translation":"Jika dilihat dari rekam jejak prestasinya, wajar saja bila ia dicalonkan sebagai kepala divisi berikutnya.","sentence_template":"彼の実績[blank]すれば、次期部長に推されるのも当然だ。"}'::jsonb, '{"selected":"をもって"}'::jsonb, '～をもってすれば berarti ''jika berdasarkan kemampuan/prestasi tersebut''.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan penuh rasa hormat, saya menyampaikan apresiasi atas kerja keras seluruh tim."', '{"display_text":"敬意をもって、チーム全員の尽力に感謝の意を表します。","romaji":"Keii o motte, chiimu zenin no jinryoku ni kansha no i o hyoushimasu.","phonetic_breakdown":["けいいをもって","ちーむぜんいんの","じんりょくに","かんしゃのいを","ひょうします"]}'::jsonb, '{"expected_transcript":"敬意をもって、チーム全員の尽力に感謝の意を表します。"}'::jsonb, '敬意をもって (dengan penuh rasa hormat) cocok untuk pidato penghargaan formal.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan. Apa isi pemberitahuan tersebut?', '{"audio_text":"定款の変更は、株主総会における特別決議をもって効力を生じるものとする。","options":[{"id":"opt_1","text":"Perubahan anggaran dasar dapat dilakukan tanpa rapat"},{"id":"opt_2","text":"Anggaran dasar perusahaan tidak boleh diubah selamanya"},{"id":"opt_3","text":"Perubahan anggaran dasar resmi berlaku melalui resolusi khusus dalam rapat umum pemegang saham"},{"id":"opt_4","text":"Pemegang saham dilarang menghadiri rapat umum"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '特別決議をもって効力を生じる adalah bahasa hukum korporasi (会社法) tingkat N1.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Dengan berlakunya peraturan baru ini, aturan lama resmi dicabut."', '{"tokens":["施行","旧規則は","される。","を余儀なくされ、","新規則の","をもって、","廃止","廃止した"],"target_translation":"Dengan berlakunya peraturan baru ini, aturan lama resmi dicabut.","romaji":"Shinkisoku no shikou o motte, kyuukisoku wa haishi sareru."}'::jsonb, '["新規則の","施行","をもって、","旧規則は","廃止","される。"]'::jsonb, '施行をもって (terhitung berlakunya peraturan) lazim dalam dokumen legislasi.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi komentar editorial berikut: 十分な安全確認を怠ったまま運行を続けたのは、無責任___行為だ。', '{"options":["極まりない","とはいえ","に足る","なりに"],"translation":"Terus beroperasi sambil melalaikan pemeriksaan keselamatan yang memadai adalah tindakan yang amat sangat tidak bertanggung jawab.","sentence_template":"十分な安全確認を怠ったまま運行を続けたのは、無責任[blank]行為だ。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, 'Kata sifat-na stem (無責任) + 極まりない menyatakan tingkat ekstrem ''luar biasa / tanpa tandingan''.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk ungkapan formal rasa syukur: 国際的な賞を受賞でき、光栄___。', '{"options":["極まりない","を余儀なくされた","に至った","ともなると"],"translation":"Dapat meraih penghargaan internasional ini sungguh merupakan kehormatan yang tiada tara.","sentence_template":"国際的な賞を受賞でき、光栄[blank]。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, '光栄極まりない / 感激の極み adalah penggunaan positif super-formal dari ～極まりない.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan tanggapan pengamat hukum. Bagaimana penilaian beliau terhadap pernyataan pejabat tersebut?', '{"audio_text":"被害者の心情を全く顧みないあの発言は、公人として不適切極まりないと言わざるを得ない。","options":[{"id":"opt_1","text":"Pernyataan itu dianggap sangat bijaksana dan menenangkan"},{"id":"opt_2","text":"Pernyataan yang sama sekali tidak memedulikan perasaan korban itu amat tidak pantas bagi seorang pejabat publik"},{"id":"opt_3","text":"Pejabat tersebut belum pernah memberikan pernyataan apa pun"},{"id":"opt_4","text":"Pengamat hukum mendukung penuh pernyataan tersebut"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '不適切極まりない berarti amat sangat tidak pantas (kritik tajam formal).', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Mengemudi dengan kecepatan tinggi di gang sempit adalah tindakan yang sangat berbahaya."', '{"tokens":["高速で走るのは、","極まり","行為だ。","とはいえ、","狭い路地を","危険","ない","極まりなく"],"target_translation":"Mengemudi dengan kecepatan tinggi di gang sempit adalah tindakan yang sangat berbahaya.","romaji":"Semai roji o kousoku de hashiru no wa kiken kiwamarinai."}'::jsonb, '["狭い路地を","高速で走るのは、","危険","極まり","ない","行為だ。"]'::jsonb, '危険極まりない行為 berarti tindakan yang luar biasa berbahaya.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sungguh amat disayangkan bahwa proyek yang telah lama disiapkan itu terpaksa batal."', '{"display_text":"長年準備してきた計画が中止となり、残念極まりありません。","romaji":"Naganen junbi shite kita keikaku ga chuushi to nari, zannen kiwamari arimasen.","phonetic_breakdown":["ながねんじゅんびしてきた","けいかくがちゅうしとなり","ざんねん","きわまりありません"]}'::jsonb, '{"expected_transcript":"長年準備してきた計画が中止となり、残念極まりありません。"}'::jsonb, '残念極まりありません adalah bentuk sopan dari 残念極まりない untuk menyatakan penyesalan mendalam.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 会議中に何度も相手の話を遮るのは、失礼___態度だ。', '{"options":["極まりない","をもって","ずにはおかない","いかんによらず"],"translation":"Berkali-kali memotong pembicaraan orang lain saat rapat adalah sikap yang luar biasa tidak sopan.","sentence_template":"会議中に何度も相手の話を遮るのは、失礼[blank]態度だ。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, '失礼 (kata sifat-na) + 極まりない menekankan ketidaksopanan pada level ekstrem.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan berita lingkungan. Apa keluhan warga tentang pembangunan jalan baru?', '{"audio_text":"住民への説明もなしに工事を強行するやり方は、強引極まりないと強い反発を招いている。","options":[{"id":"opt_1","text":"Warga memuji transparansi proyek pembangunan jalan"},{"id":"opt_2","text":"Pembangunan jalan sudah disetujui seratus persen warga"},{"id":"opt_3","text":"Cara memaksakan konstruksi tanpa penjelasan ke warga dikecam sebagai amat sangat memaksa"},{"id":"opt_4","text":"Warga meminta proyek konstruksi dipercepat dua kali lipat"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '強引極まりない berarti luar biasa memaksa/otoriter.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kesalahan manajemen data pribadi tersebut sungguh keterlaluan dan tidak bisa dimaafkan."', '{"tokens":["ずさんな管理は、","極まり","事態だ。","なりに","個人情報の","遺憾","ない","に足る"],"target_translation":"Kesalahan manajemen data pribadi tersebut sungguh keterlaluan dan tidak bisa dimaafkan.","romaji":"Kojin jouhou no zusan na kanri wa ikan kiwamarinai."}'::jsonb, '["個人情報の","ずさんな管理は、","遺憾","極まり","ない","事態だ。"]'::jsonb, '遺憾極まりない (amat sangat disesalkan) adalah frasa pernyataan resmi perusahaan/pemerintah.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pidato penerimaan penghargaan. Apa perasaan yang diungkapkan pembicara?', '{"audio_text":"このような栄誉ある賞を賜り、研究者として光栄極まりない思いでございます。","options":[{"id":"opt_1","text":"Pembicara merasa sangat terhormat sebagai peneliti atas penghargaan bergengsi tersebut"},{"id":"opt_2","text":"Pembicara menolak menerima penghargaan tersebut"},{"id":"opt_3","text":"Pembicara merasa penelitiannya belum layak dinilai"},{"id":"opt_4","text":"Pembicara mengkritik panitia penyelenggara"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '光栄極まりない思いでございます mengekspresikan rasa terhormat yang luar biasa tinggi.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Berjalan sendirian di gunung bersalju tanpa perlengkapan adalah tindakan amat sembrono."', '{"tokens":["雪山に入るのは、","極まり","ことだ。","をもって、","装備なしで","無謀","ない","無謀な"],"target_translation":"Berjalan sendirian di gunung bersalju tanpa perlengkapan adalah tindakan amat sembrono.","romaji":"Soubi nashi de yukiyama ni hairu no wa mubou kiwamarinai."}'::jsonb, '["装備なしで","雪山に入るのは、","無謀","極まり","ない","ことだ。"]'::jsonb, '無謀極まりない (amat sangat nekat/sembrono) memakai akar kata sifat-na 無謀.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk adverbial yang tepat: 彼の言動は周囲に誤解を与えるもので、不愉快___感じられた。', '{"options":["極まりなく","極まりない","極まりな","極まりに"],"translation":"Ucapan dan tindakannya menimbulkan kesalahpahaman di sekitar sehingga terasa amat sangat tidak menyenangkan.","sentence_template":"彼の言動は周囲に誤解を与えるもので、不愉快[blank]感じられた。"}'::jsonb, '{"selected":"極まりなく"}'::jsonb, 'Sebelum verba (感じられた), 極まりない berubah menjadi bentuk adverbial 極まりなく.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tindakan memalsukan data uji klinis sungguh sangat tercela secara etika."', '{"display_text":"臨床試験のデータを改ざんするとは、言語道断、悪質極まりない行為です。","romaji":"Rinshou shiken no deeta o kaizan suru to wa, gongodoudan, akushitsu kiwamarinai koui desu.","phonetic_breakdown":["りんしょうしけんの","でーたをかいざんするとは","ごんごどうだん","あくしつきわまりない","こういです"]}'::jsonb, '{"expected_transcript":"臨床試験のデータを改ざんするとは、言語道断、悪質極まりない行為です。"}'::jsonb, '悪質極まりない (amat sangat jahat/berniat buruk) sering muncul dalam berita hukum N1.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 難関資格に一発で合格した知らせを聞き、痛快___。', '{"options":["極まりなかった","とはいえなかった","に足らなかった","を余儀なくされた"],"translation":"Mendengar kabar lulus ujian sertifikasi sulit dalam sekali coba, rasanya sungguh luar biasa memuaskan.","sentence_template":"難関資格に一発で合格した知らせを聞き、痛快[blank]。"}'::jsonb, '{"selected":"極まりなかった"}'::jsonb, '痛快極まりなかった adalah bentuk lampau dari 痛快極まりない (luar biasa memuaskan/melegakan).', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan konsultan bisnis. Mengapa beliau mengkritik prosedur persetujuan di perusahaan itu?', '{"audio_text":"些細な備品購入にまで十人もの承認印を必要とする仕組みは、非効率極まりないと言えます。","options":[{"id":"opt_1","text":"Sistem persetujuan sudah sangat cepat dan ringkas"},{"id":"opt_2","text":"Semua pembelian perlengkapan kantor digratiskan"},{"id":"opt_3","text":"Karyawan tidak perlu meminta izin siapa pun"},{"id":"opt_4","text":"Mewajibkan cap persetujuan sepuluh orang bahkan untuk membeli alat tulis kecil adalah sistem yang amat tidak efisien"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '非効率極まりない berarti luar biasa tidak efisien.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kebijakan yang tidak konsisten itu membuat para pelaku usaha merasa sangat bingung."', '{"tokens":["政策は、","迷惑","ない。","に至って、","一貫性のない","事業者にとって","極まり","迷惑な"],"target_translation":"Kebijakan yang tidak konsisten itu membuat para pelaku usaha merasa sangat bingung.","romaji":"Ikkansei no nai seisaku wa jigyousha ni totte meiwaku kiwamarinai."}'::jsonb, '["一貫性のない","政策は、","事業者にとって","迷惑","極まり","ない。"]'::jsonb, '迷惑極まりない (amat sangat merepotkan/mengganggu) lazim dipakai dalam kritik kebijakan.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Membiarkan fasilitas umum rusak selama bertahun-tahun adalah kelalaian yang amat berbahaya."', '{"display_text":"老朽化した公共施設を放置するのは、危険極まりない怠慢です。","romaji":"Roukyuuka shita koukyou shisetsu o houchi suru no wa, kiken kiwamarinai taiman desu.","phonetic_breakdown":["ろうきゅうかした","こうきょうしせつを","ほうちするのは","きけんきわまりない","たいまんです"]}'::jsonb, '{"expected_transcript":"老朽化した公共施設を放置するのは、危険極まりない怠慢です。"}'::jsonb, '危険極まりない怠慢 (kelalaian yang luar biasa berbahaya) adalah gaya bahasa editorial N1.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: 根拠のない誹謗中傷は、極めて___極まりない行為だ。', '{"options":["悪質","円満","誠実","謙虚"],"translation":"Fitnah dan pencemaran nama baik tanpa dasar adalah tindakan yang amat sangat tercela/jahat.","sentence_template":"根拠のない誹謗中傷は、[blank]極まりない行為だ。"}'::jsonb, '{"selected":"悪質"}'::jsonb, '悪質極まりない (sangat jahat/berniat buruk) berpasangan erat dengan 誹謗中傷 (fitnah/pencemaran nama baik).', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sungguh merupakan kehormatan tak terhingga dapat diundang sebagai pembicara utama."', '{"display_text":"基調講演にお招きいただき、身に余る光栄、感激極まりございません。","romaji":"Kichou kouen ni omaneki itadaki, mi ni amaru kouei, kangeki kiwamari gozaimasen.","phonetic_breakdown":["きちょうこうえんに","おまねきいただき","みにあまるこうえい","かんげききわまりございません"]}'::jsonb, '{"expected_transcript":"基調講演にお招きいただき、身に余る光栄、感激極まりございません。"}'::jsonb, '感激極まりございません adalah bentuk super-sopan untuk mengekspresikan rasa haru dan terima kasih.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Bagaimana nuansa penilaian pembicara?', '{"audio_text":"緊急時の連絡体制が全く機能していなかったとは、お粗末極まりない。","options":[{"id":"opt_1","text":"Pembicara melontarkan kritik tajam bahwa sistem komunikasi darurat yang tak berfungsi itu amat sangat buruk/ceroboh"},{"id":"opt_2","text":"Pembicara memuji kecepatan sistem komunikasi darurat"},{"id":"opt_3","text":"Pembicara menyatakan belum ada situasi darurat yang terjadi"},{"id":"opt_4","text":"Pembicara mengusulkan agar sistem komunikasi dihapus saja"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, 'お粗末極まりない berarti amat sangat buruk/tidak memadai.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan kata sifat-na yang tepat: 深夜に大音量で音楽を流すのは、近所にとって___極まりない。', '{"options":["迷惑","親切","丁寧","清潔"],"translation":"Memutar musik dengan volume keras di tengah malam sungguh amat mengganggu bagi tetangga.","sentence_template":"深夜に大音量で音楽を流すのは、近所にとって[blank]極まりない。"}'::jsonb, '{"selected":"迷惑"}'::jsonb, '迷惑 (kata sifat-na) + 極まりない menyatakan gangguan pada tingkat ekstrem.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Pernyataan yang mengabaikan fakta sejarah tersebut amat sangat tidak bertanggung jawab."', '{"tokens":["無視した発言は、","極まり","ものだ。","とはいえ、","歴史の事実を","無責任","ない","無責任に"],"target_translation":"Pernyataan yang mengabaikan fakta sejarah tersebut amat sangat tidak bertanggung jawab.","romaji":"Rekishi no jijitsu o mushi shita hatsugen wa musekinin kiwamarinai."}'::jsonb, '["歴史の事実を","無視した発言は、","無責任","極まり","ない","ものだ。"]'::jsonb, '無責任極まりないものだ adalah ungkapan kritik tajam khas kolom opini.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar warga kota. Apa yang mereka keluhkan tentang proyek renovasi?', '{"audio_text":"事前通知もなしに夜通し騒音を出し続けるとは、非常識極まりないと苦情が殺到した。","options":[{"id":"opt_1","text":"Warga senang karena renovasi berlangsung cepat"},{"id":"opt_2","text":"Keluhan membanjir karena menimbulkan kebisingan semalaman tanpa pemberitahuan dianggap amat tidak masuk akal/tidak beradab"},{"id":"opt_3","text":"Warga meminta konstruksi dilakukan pada tengah malam saja"},{"id":"opt_4","text":"Tidak ada satu pun warga yang mengeluh"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '非常識極まりない berarti luar biasa tidak tahu aturan/tidak masuk akal.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 貴重な文化財が管理不足で破損したとは、残念___。', '{"options":["極まりない","を余儀なくされる","をもって","なりに"],"translation":"Sungguh amat disayangkan bahwa cagar budaya berharga rusak akibat kurangnya pemeliharaan.","sentence_template":"貴重な文化財が管理不足で破損したとは、残念[blank]。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, '残念極まりない menyatakan penyesalan yang sangat mendalam.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Aturan yang melarang diskusi terbuka di rapat inovasi sungguh amat tidak masuk akal."', '{"display_text":"革新を目指す会議で自由な発言を禁じるなど、不合理極まりありません。","romaji":"Kakushin o mezasu kaigi de jiyuu na hatsugen o kinjiru nado, fugouri kiwamari arimasen.","phonetic_breakdown":["かくしんをめざす","かいぎでじゆうなはつげんを","きんじるなど","ふごうりきわまりありません"]}'::jsonb, '{"expected_transcript":"革新を目指す会議で自由な発言を禁じるなど、不合理極まりありません。"}'::jsonb, '不合理極まりありません berarti amat sangat tidak rasional.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan pengamat keamanan siber. Mengapa ia mengkritik perusahaan tersebut?', '{"audio_text":"顧客のパスワードを暗号化せず平文で保存していたとは、杜撰極まりない管理体制だ。","options":[{"id":"opt_1","text":"Perusahaan telah menerapkan enkripsi tercanggih di dunia"},{"id":"opt_2","text":"Pelanggan tidak perlu menggunakan kata sandi"},{"id":"opt_3","text":"Menyimpan kata sandi pelanggan tanpa enkripsi menunjukkan sistem manajemen yang amat sangat ceroboh"},{"id":"opt_4","text":"Sistem keamanan perusahaan tidak pernah mengalami celah"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '杜撰極まりない (zusan kiwamarinai) berarti luar biasa ceroboh/asal-asalan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Membuat keputusan besar tanpa data pendukung adalah tindakan yang sangat gegabah."', '{"tokens":["重大な判断は、","極まり","行為だ。","をもって、","根拠のない","軽率","ない","軽率に"],"target_translation":"Membuat keputusan besar tanpa data pendukung adalah tindakan yang sangat gegabah.","romaji":"Konkyo no nai handan wa keisotsu kiwamarinai."}'::jsonb, '["根拠のない","重大な判断は、","軽率","極まり","ない","行為だ。"]'::jsonb, '軽率極まりない行為 berarti tindakan yang luar biasa gegabah.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat refleksi berikut: 経験が浅い新入社員でも、彼___工夫を重ねて業務に取り組んでいる。', '{"options":["なりに","をもって","に至って","極まりなく"],"translation":"Meskipun masih karyawan baru yang minim pengalaman, ia berusaha dengan caranya sendiri yang penuh kreativitas.","sentence_template":"経験が浅い新入社員でも、彼[blank]工夫を重ねて業務に取り組んでいる。"}'::jsonb, '{"selected":"なりに"}'::jsonb, '～なりに berarti ''dengan cara/kapasitas yang sesuai dengan subjeknya sendiri''.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk penyambung kata benda yang tepat: 完璧ではなくても、私___答えを論文にまとめて提出した。', '{"options":["なりの","なりに","なる","なれば"],"translation":"Meskipun tidak sempurna, saya merangkum jawaban versi saya sendiri ke dalam makalah dan menyerahkannya.","sentence_template":"完璧ではなくても、私[blank]答えを論文にまとめて提出した。"}'::jsonb, '{"selected":"なりの"}'::jsonb, 'Sebelum kata benda (答え), digunakan bentuk ～なりの.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar kepala departemen tentang anggota baru. Apa sikap beliau?', '{"audio_text":"まだ成果は小さいかもしれないが、彼女は彼女なりに毎日必死に努力しているのを評価したい。","options":[{"id":"opt_1","text":"Ia ingin menegur anggota baru karena tidak berusaha"},{"id":"opt_2","text":"Ia ingin mengapresiasi usaha gigih anggota baru tersebut sesuai kapasitasnya meski hasilnya masih kecil"},{"id":"opt_3","text":"Ia berencana memindahkan anggota baru ke divisi lain"},{"id":"opt_4","text":"Ia menilai anggota baru sudah melampaui semua senior"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '彼女は彼女なりに menunjukkan empati pemimpin yang menghargai usaha sesuai tahap kemampuan individu.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setiap generasi memiliki cara pandang dan kesulitannya masing-masing."', '{"tokens":["その世代","悩みが","ものだ。","とはいえ、","どの世代にも、","なりの","ある","なりに"],"target_translation":"Setiap generasi memiliki cara pandang dan kesulitannya masing-masing.","romaji":"Dono sedai ni mo, sono sedai nari no nayami ga aru."}'::jsonb, '["どの世代にも、","その世代","なりの","悩みが","ある","ものだ。"]'::jsonb, 'その世代なりの悩み (kesulitan khas generasi tersebut) menggunakan ～なりの + kata benda.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun kemampuan saya terbatas, saya ingin berkontribusi dengan cara saya sendiri."', '{"display_text":"微力ではありますが、私なりに精一杯貢献したいと考えております。","romaji":"Biryoku dewa arimasu ga, watashi nari ni seiippai kouken shitai to kangaete orimasu.","phonetic_breakdown":["びりょくではありますが","わたしなりに","せいいっぱい","こうけんしたいと","かんがえております"]}'::jsonb, '{"expected_transcript":"微力ではありますが、私なりに精一杯貢献したいと考えております。"}'::jsonb, '私なりに精一杯 (sekuat tenaga dengan cara saya sendiri) adalah ungkapan rendah hati profesional.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予算が少ないプロジェクトには、少ない___進め方や面白さがある。', '{"options":["なりの","をもって","いかんによらず","ずにはおかない"],"translation":"Pada proyek beranggaran kecil, ada cara menjalankan dan daya tarik tersendiri sesuai keterbatasannya.","sentence_template":"予算が少ないプロジェクトには、少ない[blank]進め方や面白さがある。"}'::jsonb, '{"selected":"なりの"}'::jsonb, 'Kata sifat-i (少ない) + なりの menyatakan kesesuaian dengan kondisi tersebut.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan wawancara penulis novel. Bagaimana ia memandang kritik pembaca?', '{"audio_text":"厳しい意見であっても、読者なりの期待や作品への愛着があるからこそだと受け止めている。","options":[{"id":"opt_1","text":"Ia mengabaikan semua masukan dari pembaca"},{"id":"opt_2","text":"Ia berhenti menulis novel karena kritik"},{"id":"opt_3","text":"Ia memaknai kritik tajam sebagai wujud harapan dan keterikatan pembaca dengan caranya sendiri"},{"id":"opt_4","text":"Ia hanya membaca ulasan yang memuji karyanya"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '読者なりの期待 berarti harapan khas dari sudut pandang pembaca.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meski tidak mahir berbicara di depan umum, ia menyampaikan pesan dengan caranya sendiri."', '{"tokens":["彼","思いを","のだ。","ともなると、","話が上手ではなくても、","なりに","伝えた","なりの"],"target_translation":"Meski tidak mahir berbicara di depan umum, ia menyampaikan pesan dengan caranya sendiri.","romaji":"Hanashi ga jouzu dewa nakutemo, kare nari ni omoi o tsutaeta."}'::jsonb, '["話が上手ではなくても、","彼","なりに","思いを","伝えた","のだ。"]'::jsonb, '彼なりに (dengan caranya sendiri) menekankan ketulusan penyampaian.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan dua orang tua. Apa yang mereka bicarakan tentang anak mereka?', '{"audio_text":"子どもは子どもなりに親の顔色をよく見ていて、気を遣っていることがあるんだよ。","options":[{"id":"opt_1","text":"Anak-anak pun dengan caranya sendiri memperhatikan ekspresi orang tua dan berusaha menjaga perasaan mereka"},{"id":"opt_2","text":"Anak-anak sama sekali tidak peduli pada orang tuanya"},{"id":"opt_3","text":"Orang tua tidak perlu berbicara dengan anak-anak"},{"id":"opt_4","text":"Anak-anak selalu menuntut mainan mahal setiap hari"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '子どもは子どもなりに adalah pola repetisi XはXなりに yang sangat alami di N1.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Perusahaan kecil memiliki keunggulan kecepatan keputusan sesuai skalanya sendiri."', '{"tokens":["中小企業","強みが","はずだ。","を余儀なくされ、","中小企業には","なりの","ある","なりに"],"target_translation":"Perusahaan kecil memiliki keunggulan kecepatan keputusan sesuai skalanya sendiri.","romaji":"Chuushou kigyou ni wa chuushou kigyou nari no tsuyomi ga aru."}'::jsonb, '["中小企業には","中小企業","なりの","強みが","ある","はずだ。"]'::jsonb, '中小企業なりの強み (keunggulan khas skala UKM) memakai kata benda + なりの.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 都会の便利さはないが、田舎には田舎___豊かな暮らしがある。', '{"options":["なりの","なりに","をもって","に足る"],"translation":"Memang tidak ada kepraktisan kota besar, tetapi di desa ada kehidupan yang kaya sesuai karakteristik desanya sendiri.","sentence_template":"都会の便利さはないが、田舎には田舎[blank]豊かな暮らしがある。"}'::jsonb, '{"selected":"なりの"}'::jsonb, '田舎なりの豊かな暮らし memodifikasi frasa nominal 豊かな暮らし.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya telah memikirkan solusi terbaik menurut pemahaman saya sendiri."', '{"display_text":"自分なりに考え抜いた上で、この改善案を作成しました。","romaji":"Jibun nari ni kangaenuita ue de, kono kaizenan o sakusei shimashita.","phonetic_breakdown":["じぶんなりに","かんがえぬいたうえで","このかいぜんあんを","さくせいしました"]}'::jsonb, '{"expected_transcript":"自分なりに考え抜いた上で、この改善案を作成しました。"}'::jsonb, '自分なりに考え抜く (memikirkan matang-matang dengan cara sendiri) menunjukkan inisiatif mandiri.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 歳を取れば、若い頃とは違う老後___楽しみ方が見つかるものだ。', '{"options":["なりの","に至って","極まりない","ずにはおかない"],"translation":"Jika bertambah usia, akan ditemukan cara menikmati masa tua tersendiri yang berbeda dari masa muda.","sentence_template":"歳を取れば、若い頃とは違う老後[blank]楽しみ方が見つかるものだ。"}'::jsonb, '{"selected":"なりの"}'::jsonb, '老後なりの楽しみ方 menyatakan cara menikmati hidup yang sesuai dengan fase usia lanjut.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan tanggapan manajer proyek. Bagaimana ia mengevaluasi presentasi staf junior?', '{"audio_text":"まだ荒削りな部分はあるものの、データ分析の切り口には君なりの独自性が光っていたよ。","options":[{"id":"opt_1","text":"Presentasi staf junior dinilai gagal total"},{"id":"opt_2","text":"Data analisisnya tidak relevan dengan proyek"},{"id":"opt_3","text":"Staf junior diminta meniru presentasi orang lain persis sama"},{"id":"opt_4","text":"Meski masih ada bagian yang mentah, sudut pandang analisis datanya memancarkan orisinalitas khas dirinya sendiri"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '君なりの独自性 berarti keunikan/orisinalitas yang lahir dari pemikiran staf itu sendiri.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Walaupun sibuk, saya meluangkan waktu belajar bahasa Jepang sesuai ritme saya sendiri."', '{"tokens":["自分","ペースで","勉強している。","勉強した。","忙しい中でも、","なりの","日本語を","なりに"],"target_translation":"Walaupun sibuk, saya meluangkan waktu belajar bahasa Jepang sesuai ritme saya sendiri.","romaji":"Isogashii naka demo, jibun nari no peesu de Nihongo o benkyou shite iru."}'::jsonb, '["忙しい中でも、","自分","なりの","ペースで","日本語を","勉強している。"]'::jsonb, '自分なりのペースで (dengan ritme sendiri) sangat alami untuk menggambarkan kebiasaan belajar.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setiap anggota tim berkontribusi sesuai peran dan keahliannya masing-masing."', '{"display_text":"メンバーそれぞれが、自分の立場なりに最善を尽くしてくれました。","romaji":"Menbaa sorezore ga, jibun no tachiba nari ni saizen o tsukushite kuremashita.","phonetic_breakdown":["めんばーそれぞれが","じぶんのたちばなりに","さいぜんを","つくしてくれました"]}'::jsonb, '{"expected_transcript":"メンバーそれぞれが、自分の立場なりに最善を尽くしてくれました。"}'::jsonb, '立場なりに最善を尽くす berarti melakukan yang terbaik sesuai posisi masing-masing.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 限られた資源の中でも、現場なりの___を凝らして成果を出した。', '{"options":["工夫","撤退","放棄","欠席"],"translation":"Di tengah sumber daya yang terbatas pun, tim lapangan memeras kreativitas dengan caranya sendiri hingga membuahkan hasil.","sentence_template":"限られた資源の中でも、現場なりの[blank]を凝らして成果を出した。"}'::jsonb, '{"selected":"工夫"}'::jsonb, '工夫を凝らす (mengupayakan kreativitas/akal budi secara optimal) sangat cocok dengan ～なりの.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun belum sempurna, saya telah merangkum pandangan saya sendiri dalam laporan ini."', '{"display_text":"未熟ながらも、私なりの見解を本報告書にまとめました。","romaji":"Mijuku nagara mo, watashi nari no kenkai o hon houkokusho ni matomemashita.","phonetic_breakdown":["みじくながらも","わたしなりのけんかいを","ほんほうこくしょに","まとめました"]}'::jsonb, '{"expected_transcript":"未熟ながらも、私なりの見解を本報告書にまとめました。"}'::jsonb, '私なりの見解 (pandangan versi saya sendiri) adalah ungkapan akademis dan bisnis yang sopan.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa makna utama dari ～なりに di sini?', '{"audio_text":"相手にも相手なりの事情があるはずだから、一方的に責めるのは良くない。","options":[{"id":"opt_1","text":"Pihak lawan pasti memiliki situasi/alasannya sendiri sehingga tidak baik menyalahkan secara sepihak"},{"id":"opt_2","text":"Pihak lawan tidak punya alasan apa pun"},{"id":"opt_3","text":"Kita harus menyalahkan pihak lawan sekeras mungkin"},{"id":"opt_4","text":"Situasi kedua pihak persis sama"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '相手なりの事情 menekankan empati terhadap keadaan khusus yang dimiliki pihak lain.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 初心者には初心者___上達する楽しみがある。', '{"options":["なりの","なりに","をもって","とはいえ"],"translation":"Bagi pemula, ada kesenangan tersendiri dalam berkembang sesuai tahap pemula.","sentence_template":"初心者には初心者[blank]上達する楽しみがある。"}'::jsonb, '{"selected":"なりの"}'::jsonb, 'Sebelum frasa nominal 上達する楽しみ, gunakan bentuk ～なりの.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Setiap daerah memiliki kebijaksanaan tradisionalnya sendiri dalam menghadapi bencana."', '{"tokens":["その土地","防災の知恵が","いる。","受け継いだ。","その土地には","なりの","受け継がれて","なりに"],"target_translation":"Setiap daerah memiliki kebijaksanaan tradisionalnya sendiri dalam menghadapi bencana.","romaji":"Sono tochi ni wa sono tochi nari no bousai no chie ga aru."}'::jsonb, '["その土地には","その土地","なりの","防災の知恵が","受け継がれて","いる。"]'::jsonb, 'その土地なりの知恵 (kearifan lokal khas daerah tersebut) adalah konteks budaya yang tepat.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar pelatih. Mengapa ia memuji pemain cadangan itu?', '{"audio_text":"試合に出られない時期も腐らず、彼なりにチームを支える役割を果たしてくれた。","options":[{"id":"opt_1","text":"Karena pemain itu mencetak sepuluh gol di final"},{"id":"opt_2","text":"Karena meski tidak turun bermain, ia tidak patah semangat dan menjalankan peran mendukung tim dengan caranya sendiri"},{"id":"opt_3","text":"Karena pemain itu pindah ke klub lain"},{"id":"opt_4","text":"Karena pemain itu menolak berlatih bersama tim"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '彼なりにチームを支える役割を果たす berarti berkontribusi sesuai posisinya.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 高い道具がなくても、手元にある材料___おいしい料理は作れる。', '{"options":["なりに","極まりなく","ずにはおかず","いかんによらず"],"translation":"Meski tanpa peralatan mahal, masakan lezat bisa dibuat sesuai bahan yang ada di tangan.","sentence_template":"高い道具がなくても、手元にある材料[blank]おいしい料理は作れる。"}'::jsonb, '{"selected":"なりに"}'::jsonb, '材料なりに (sesuai kondisi bahan yang ada) memodifikasi verba 作れる.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya ingin terus belajar dan bertumbuh dengan kecepatan saya sendiri tanpa terburu-buru."', '{"display_text":"焦らず、自分なりに一歩ずつ成長していきたいと思っています。","romaji":"Aserazu, jibun nari ni ippo zutsu seichou shite ikitai to omotte imasu.","phonetic_breakdown":["あせらず","じぶんなりに","いっぽずつ","せいちょうしていきたいと","おもっています"]}'::jsonb, '{"expected_transcript":"焦らず、自分なりに一歩ずつ成長していきたいと思っています。"}'::jsonb, '自分なりに一歩ずつ mengekspresikan sikap bertumbuh yang tenang dan konsisten.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan wawancara direktur seni. Apa filosofi beliau dalam membimbing desainer muda?', '{"audio_text":"型にはめるのではなく、それぞれの感性なりに表現の幅を広げてほしいと願っています。","options":[{"id":"opt_1","text":"Semua desainer muda harus meniru satu gaya yang sama"},{"id":"opt_2","text":"Desainer muda tidak boleh menyampaikan ide sendiri"},{"id":"opt_3","text":"Beliau berharap tiap desainer memperluas daya ekspresi sesuai kepekaan masing-masing tanpa dikekang cetakan kaku"},{"id":"opt_4","text":"Beliau hanya menerima desainer yang sudah berpengalaman dua puluh tahun"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'それぞれの感性なりに berarti sesuai sensitivitas estetika masing-masing.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun hasilnya belum maksimal, saya sudah berupaya sebaik mungkin dengan cara saya."', '{"tokens":["不十分だが、","なりに","尽くした。","を余儀なくされた。","結果は","私","全力を","なりの"],"target_translation":"Meskipun hasilnya belum maksimal, saya sudah berupaya sebaik mungkin dengan cara saya.","romaji":"Kekka wa manzoku dewa nai ga, watashi nari ni zenryoku o tsukushita."}'::jsonb, '["結果は","不十分だが、","私","なりに","全力を","尽くした。"]'::jsonb, '私なりに全力を尽くした (saya sudah mengerahkan segenap tenaga sesuai kapasitas saya).', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi ulasan seni berikut: 彼女の圧倒的な歌唱力は、聴く者すべてを感動させ___。', '{"options":["ずにはおかない","を余儀なくされない","に足らない","極まりない"],"translation":"Kemampuan bernyanyinya yang luar biasa pasti akan membuat setiap pendengarnya terharu tanpa terkecuali.","sentence_template":"彼女の圧倒的な歌唱力は、聴く者すべてを感動させ[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, 'V-nai (tanpa い) + ずにはおかない menyatakan dampak psikologis/sosial yang pasti dan tak terhindarkan.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih konjugasi yang tepat untuk kata kerja する: この画期的な発見は、今後の医学界に大きな変革をもたら___。', '{"options":["さずにはおかない","しずにはおかない","せずにはおかない","すずにはおかない"],"translation":"Penemuan terobosan ini pasti akan membawa perubahan besar bagi dunia kedokteran ke depan.","sentence_template":"この画期的な発見は、今後の医学界に大きな変革をもたら[blank]。"}'::jsonb, '{"selected":"さずにはおかない"}'::jsonb, 'もたらす (golongan 1) -> もたらさ + ずにはおかない.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan kritikus film. Apa dampak film dokumenter tersebut pada penonton?', '{"audio_text":"戦火の現実を淡々と映し出したそのドキュメンタリーは、見る者に深い問いを投げかけずにはおかない。","options":[{"id":"opt_1","text":"Film dokumenter itu membuat penonton tertidur di bioskop"},{"id":"opt_2","text":"Film dokumenter yang menampilkan realitas perang secara lugas itu pasti menggugah pertanyaan mendalam di benak penonton"},{"id":"opt_3","text":"Film dokumenter itu hanya berisi komedi ringan"},{"id":"opt_4","text":"Penonton tidak memahami bahasa yang digunakan dalam film itu"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '深い問いを投げかけずにはおかない berarti pasti menimbulkan perenungan/pertanyaan mendalam.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Skandal korupsi besar tersebut pasti akan mengguncang kepercayaan publik."', '{"tokens":["国民の信頼を","ずには","ない。","とはいえ、","その汚職事件は、","揺るがさ","おか","揺るがす"],"target_translation":"Skandal korupsi besar tersebut pasti akan mengguncang kepercayaan publik.","romaji":"Sono oshoku jiken wa kokumin no shinrai o yurugasazu ni wa okanai."}'::jsonb, '["その汚職事件は、","国民の信頼を","揺るがさ","ずには","おか","ない。"]'::jsonb, '揺るがす (mengguncang) -> 揺るがさずにはおかない.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Keindahan arsitektur kuno itu pasti membuat siapa pun yang melihatnya terpukau."', '{"display_text":"その古建築の壮麗な美しさは、訪れる人々を魅了せずにはおきません。","romaji":"Sono kokenchiku no sourei na utsukushisa wa, otozureru hitobito o miryou sezu ni wa okimasen.","phonetic_breakdown":["そのこけんちくの","そうれいなうつくしさは","おとずれるひとびとを","みりょうせずには","おきません"]}'::jsonb, '{"expected_transcript":"その古建築の壮麗な美しさは、訪れる人々を魅了せずにはおきません。"}'::jsonb, '魅了する (memukau) -> 魅了せずにはおきません (bentuk する selalu menjadi せずにはおかない).', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat editorial: 新税の導入は、家計の負担増を通じて消費動向に影響を与え___。', '{"options":["ずにはおかない","なりに","をもって","ともなると"],"translation":"Penerapan pajak baru pasti akan memberi pengaruh pada tren konsumsi melalui meningkatnya beban rumah tangga.","sentence_template":"新税の導入は、家計の負担増を通じて消費動向に影響を与え[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, '影響を与えずにはおかない menyatakan dampak ekonomi yang niscaya terjadi.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar pakar sejarah. Apa efek dari penemuan naskah kuno tersebut?', '{"audio_text":"今回発見された古文書は、従来の定説を根底から覆さずにはおかない極めて重要な資料だ。","options":[{"id":"opt_1","text":"Naskah kuno itu tidak memiliki nilai sejarah apa pun"},{"id":"opt_2","text":"Naskah kuno itu memperkuat teori lama tanpa perubahan"},{"id":"opt_3","text":"Naskah kuno yang baru ditemukan ini adalah materi amat penting yang pasti akan membalikkan teori mapan sebelumnya dari akarnya"},{"id":"opt_4","text":"Naskah kuno itu hilang sebelum sempat diteliti"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '定説を根底から覆さずにはおかない berarti pasti membalikkan teori baku dari dasarnya.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Pidato yang penuh semangat itu pasti membangkitkan keberanian para pendengarnya."', '{"tokens":["聞く人に","与え","おかない。","極まりない。","その熱弁は、","勇気を","ずには","与えた"],"target_translation":"Pidato yang penuh semangat itu pasti membangkitkan keberanian para pendengarnya.","romaji":"Sono netsuben wa kiku hito ni yuuki o ataezu ni wa okanai."}'::jsonb, '["その熱弁は、","聞く人に","勇気を","与え","ずには","おかない。"]'::jsonb, '勇気を与えずにはおかない (pasti menumbuhkan keberanian) memakai golongan 2 与える -> 与え + ずにはおかない.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan analisis media. Bagaimana reaksi pasar terhadap penggabungan dua raksasa teknologi itu?', '{"audio_text":"業界一位と二位の電撃的な経営統合は、国内外の競合他社に激しい危機感を抱かせずにはおかないだろう。","options":[{"id":"opt_1","text":"Merger mengejutkan dua pemimpin industri itu pasti akan memicu rasa waspada/krisis tajam di kalangan pesaing domestik maupun asing"},{"id":"opt_2","text":"Pesaing menyambut gembira merger tersebut tanpa kekhawatiran"},{"id":"opt_3","text":"Merger tersebut dibatalkan sebelum diumumkan"},{"id":"opt_4","text":"Industri teknologi tidak terpengaruh sama sekali"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '危機感を抱かせずにはおかない (bentuk kausatif 抱かせる + ずにはおかない) berarti pasti membuat mereka merasakan krisis.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Ketidakadilan yang terang-terangan itu pasti akan memicu kemarahan masyarakat luas."', '{"tokens":["市民の怒りを","ずには","ない。","なりに、","その不公正な処置は、","招か","おか","招いた"],"target_translation":"Ketidakadilan yang terang-terangan itu pasti akan memicu kemarahan masyarakat luas.","romaji":"Sono fukousei na shochi wa shimin no ikari o manekazu ni wa okanai."}'::jsonb, '["その不公正な処置は、","市民の怒りを","招か","ずには","おか","ない。"]'::jsonb, '招く -> 招かずにはおかない menyatakan reaksi sosial yang tak terbendung.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 彼の誠実な人柄は、接するすべての人に好感を抱か___。', '{"options":["せずにはおかない","さずにはおかない","すずにはおかない","しずにはおかない"],"translation":"Kepribadiannya yang tulus pasti membuat setiap orang yang berinteraksi dengannya menaruh simpati.","sentence_template":"彼の誠実な人柄は、接するすべての人に好感を抱か[blank]。"}'::jsonb, '{"selected":"せずにはおかない"}'::jsonb, '抱かせる (kausatif, membuat orang lain merasakan) -> 抱かせ + ずにはおかない.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karya sastra klasik ini pasti meninggalkan kesan mendalam bagi pembaca lintas zaman."', '{"display_text":"この名作文学は、時代を超えて読者の心に深い余韻を残さずにはおきません。","romaji":"Kono meisaku bungaku wa, jidai o koete dokusha no kokoro ni fukai yoin o nokosazu ni wa okimasen.","phonetic_breakdown":["このめいさくぶんがくは","じだいをこえて","どくしゃのこころに","ふかいよいんを","のこさずにはおきません"]}'::jsonb, '{"expected_transcript":"この名作文学は、時代を超えて読者の心に深い余韻を残さずにはおきません。"}'::jsonb, '余韻を残す (meninggalkan kesan mendalam yang membekas) + ずにはおきません.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 気候変動の加速は、世界の食料供給体制に深刻な打撃を与え___。', '{"options":["ずにはおかない","を余儀なくされる","に足る","いかんによらず"],"translation":"Percepatan perubahan iklim pasti akan memberikan pukulan serius bagi sistem pasokan pangan dunia.","sentence_template":"気候変動の加速は、世界の食料供給体制に深刻な打撃を与え[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, '打撃を与えずにはおかない menyatakan konsekuensi besar yang niscaya terjadi.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan pameran foto. Apa yang dirasakan pengunjung melihat foto-foto alam liar itu?', '{"audio_text":"極限の自然を捉えた写真の数々は、見る者に畏敬の念を覚えさせずにはおかない迫力がある。","options":[{"id":"opt_1","text":"Pengunjung merasa foto-foto itu biasa saja"},{"id":"opt_2","text":"Foto-foto itu diambil di dalam studio tertutup"},{"id":"opt_3","text":"Pameran foto itu ditutup karena sepi pengunjung"},{"id":"opt_4","text":"Deretan foto alam ekstrem tersebut memiliki kekuatan yang pasti menumbuhkan rasa takjub mendalam pada siapa pun yang melihatnya"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '畏敬の念を覚えさせずにはおかない berarti pasti menimbulkan rasa hormat dan takjub.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Perubahan demografi yang cepat pasti akan memaksa peninjauan ulang sistem pensiun."', '{"tokens":["年金制度の","迫ら","おかない。","をもって、","人口構造の変化は、","見直しを","ずには","迫った"],"target_translation":"Perubahan demografi yang cepat pasti akan memaksa peninjauan ulang sistem pensiun.","romaji":"Jinkou kouzou no henka wa nenkin seido no minaoshi o semarazu ni wa okanai."}'::jsonb, '["人口構造の変化は、","年金制度の","見直しを","迫ら","ずには","おかない。"]'::jsonb, '迫る (mendesak) -> 迫らずにはおかない.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dedikasi para relawan di lokasi bencana pasti menyentuh hati siapa pun yang menyaksikannya."', '{"display_text":"被災地でのボランティアの方々の献身は、見る人の胸を打たずにはおきません。","romaji":"Hisaichi de no borantia no katagata no kenshin wa, miru hito no mune o utazu ni wa okimasen.","phonetic_breakdown":["ひさいちでの","ぼらんてぃあのかたがたの","けんしんは","みるひとのむねを","うたずにはおきません"]}'::jsonb, '{"expected_transcript":"被災地でのボランティアの方々の献身は、見る人の胸を打たずにはおきません。"}'::jsonb, '胸を打つ (menyentuh hati secara mendalam) -> 胸を打たずにはおきません.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: この法案の可決は、社会全体に大きな___を呼ばずにはおかない。', '{"options":["波紋","休暇","祝賀","平穏"],"translation":"Pengesahan rancangan undang-undang ini pasti akan mengundang perdebatan/gelombang reaksi besar di seluruh masyarakat.","sentence_template":"この法案の可決は、社会全体に大きな[blank]を呼ばずにはおかない。"}'::jsonb, '{"selected":"波紋"}'::jsonb, '波紋を呼ぶ (menimbulkan riak/dampak polemik luas) adalah kolokasi media N1 yang erat dengan ずにはおかない.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kinerja luar biasa tim muda itu pasti akan menarik perhatian seluruh dunia olahraga."', '{"display_text":"若手チームの目覚ましい活躍は、スポーツ界全体の注目を集めずにはおきません。","romaji":"Wakate chiimu no mezamashii katsuyaku wa, supootsukai zentai no chuumoku o atsumezu ni wa okimasen.","phonetic_breakdown":["わかてちーむの","めざましいかつやくは","すぽーつかいぜんたいの","ちゅうもくをあつめずには","おきません"]}'::jsonb, '{"expected_transcript":"若手チームの目覚ましい活躍は、スポーツ界全体の注目を集めずにはおきません。"}'::jsonb, '注目を集めずにはおきません berarti pasti menyita perhatian publik.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa perbedaan nuansa ～ずにはおかない di sini?', '{"audio_text":"あの映画の結末は、どんな冷静な観客であっても涙を誘わずにはおかない。","options":[{"id":"opt_1","text":"Akhir film itu pasti secara alami mengundang air mata penonton setenang apa pun"},{"id":"opt_2","text":"Penonton dilarang menangis di dalam bioskop"},{"id":"opt_3","text":"Akhir film itu sangat lucu dan mengundang tawa"},{"id":"opt_4","text":"Film itu tidak memiliki akhir cerita"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '涙を誘わずにはおかない menunjukkan efek emosional yang tak terhindarkan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan konjugasi yang benar: 真実を知った彼女は、真犯人を徹底的に追及___。', '{"options":["せずにはおかないだろう","しずにはおかないだろう","すずにはおかないだろう","さずにはおかないだろう"],"translation":"Setelah mengetahui kebenaran, ia pasti akan mengusut pelaku sebenarnya sampai tuntas (tekad tak terbendung).","sentence_template":"真実を知った彼女は、真犯人を徹底的に追及[blank]。"}'::jsonb, '{"selected":"せずにはおかないだろう"}'::jsonb, '追及する -> 追及せずにはおかない juga dipakai untuk tekad kuat ''pasti akan melakukan''.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Keputusan mendadak itu pasti akan menimbulkan kebingungan di pasar keuangan."', '{"tokens":["金融市場に","もたらさ","おかない。","とはいえ、","突然の決定は、","混乱を","ずには","もたらす"],"target_translation":"Keputusan mendadak itu pasti akan menimbulkan kebingungan di pasar keuangan.","romaji":"Totsuzen no kettei wa kinyuu shijou ni konran o motarasazu ni wa okanai."}'::jsonb, '["突然の決定は、","金融市場に","混乱を","もたらさ","ずには","おかない。"]'::jsonb, '混乱をもたらさずにはおかない adalah gaya bahasa laporan ekonomi N1.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan buku ilmiah. Apa keunggulan buku tersebut?', '{"audio_text":"宇宙の起源を平易な言葉で解き明かした本書は、科学への知的好奇心を刺激せずにはおかない。","options":[{"id":"opt_1","text":"Buku itu terlalu sulit dipahami oleh pembaca umum"},{"id":"opt_2","text":"Buku yang menjelaskan asal-usul alam semesta dengan bahasa sederhana ini pasti merangsang rasa ingin tahu intelektual terhadap sains"},{"id":"opt_3","text":"Buku itu tidak membahas topik astronomi sama sekali"},{"id":"opt_4","text":"Buku itu sudah ditarik dari peredaran"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '知的好奇心を刺激せずにはおかない berarti pasti memacu rasa ingin tahu intelektual.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼の情熱的な演奏は、会場の空気を一変させ___。', '{"options":["ずにはおかなかった","を余儀なくされた","極まりなかった","に足らなかった"],"translation":"Permainan musiknya yang penuh gairah pasti mengubah suasana aula dalam sekejap.","sentence_template":"彼の情熱的な演奏は、会場の空気を一変させ[blank]。"}'::jsonb, '{"selected":"ずにはおかなかった"}'::jsonb, '一変させずにはおかなかった (bentuk lampau) menyatakan dampak nyata yang benar-benar terjadi.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Temuan arkeologi ini pasti akan menarik minat para peneliti dari seluruh penjuru dunia."', '{"display_text":"この考古学的発見は、世界中の研究者の関心を惹かずにはおきません。","romaji":"Kono koukogakuteki hakken wa, sekaijuu no kenkyuusha no kanshin o hikazu ni wa okimasen.","phonetic_breakdown":["このこうこがくてき","はっけんは","せかいじゅうのけんきゅうしゃの","かんしんをひかずには","おきません"]}'::jsonb, '{"expected_transcript":"この考古学的発見は、世界中の研究者の関心を惹かずにはおきません。"}'::jsonb, '関心を惹く (menarik perhatian/minat) -> 関心を惹かずにはおきません.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar kritikus sosial. Apa dampak urbanisasi ekstrem yang disoroti?', '{"audio_text":"地域コミュニティの希薄化は、災害時の助け合い体制に深刻な影を落とさずにはおかない。","options":[{"id":"opt_1","text":"Melemahnya ikatan komunitas memperkuat gotong royong saat bencana"},{"id":"opt_2","text":"Tidak ada hubungan antara komunitas lokal dan kesiapsiagaan bencana"},{"id":"opt_3","text":"Melemahnya komunitas lokal pasti akan memberi dampak negatif serius pada sistem saling tolong saat bencana"},{"id":"opt_4","text":"Semua bencana alam dapat dicegah oleh pemerintah daerah"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '影を落とさずにはおかない berarti pasti meninggalkan bayang-bayang/dampak buruk serius.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kegigihan atlet difabel itu pasti akan menginspirasi generasi muda."', '{"tokens":["若い世代を","ずには","ない。","ともなると、","彼の不屈の精神は、","奮い立たせ","おか","奮い立たせた"],"target_translation":"Kegigihan atlet difabel itu pasti akan menginspirasi generasi muda.","romaji":"Kare no fukutsu no seishin wa wakai sedai o furuitatasezu ni wa okanai."}'::jsonb, '["彼の不屈の精神は、","若い世代を","奮い立たせ","ずには","おか","ない。"]'::jsonb, '奮い立たせる (membangkitkan semangat) -> 奮い立たせずにはおかない.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 国際的な大企業の社長___、一つの発言が株価を大きく左右する。', '{"options":["ともなると","なりに","とはいえ","をもって"],"translation":"Jika sudah sampai pada posisi direktur utama perusahaan multinasional besar, satu pernyataan saja sangat memengaruhi harga saham.","sentence_template":"国際的な大企業の社長[blank]、一つの発言が株価を大きく左右する。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, '～ともなると / ～ともなれば menyoroti standar, dampak, atau tuntutan khusus ketika mencapai level/skala tinggi.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk tingkat keahlian: プロのオーケストラの演奏者___、わずかな音程のずれも許されない。', '{"options":["ともなれば","に至っては","を余儀なくされ","極まりなく"],"translation":"Jika sudah mencapai level musisi orkestra profesional, penyimpangan nada sekecil apa pun tidak ditoleransi.","sentence_template":"プロのオーケストラの演奏者[blank]、わずかな音程のずれも許されない。"}'::jsonb, '{"selected":"ともなれば"}'::jsonb, '～ともなれば adalah varian kondisional yang sangat alami dengan ～ともなると.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan wawancara direktur konstruksi. Apa yang membedakan proyek berskala nasional?', '{"audio_text":"総事業費が数百億円規模の国家プロジェクトともなると、関係省庁との調整だけでも膨大な時間を要します。","options":[{"id":"opt_1","text":"Proyek skala nasional bisa diselesaikan dalam dua hari tanpa koordinasi"},{"id":"opt_2","text":"Jika sudah sampai proyek nasional bernilai puluhan miliar yen, koordinasi dengan kementerian terkait saja memakan waktu sangat besar"},{"id":"opt_3","text":"Proyek nasional tidak memerlukan persetujuan pemerintah"},{"id":"opt_4","text":"Anggaran proyek nasional selalu lebih kecil dari proyek lokal"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '国家プロジェクトともなると menekankan kompleksitas khusus pada skala proyek raksasa.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah memasuki bulan Desember, pusat kota dipenuhi suasana akhir tahun."', '{"tokens":["とも","都心は","包まれる。","包まれた。","十二月","なると、","師走の雰囲気に","なりに、"],"target_translation":"Jika sudah memasuki bulan Desember, pusat kota dipenuhi suasana akhir tahun.","romaji":"Juunigatsu to mo naru to, toshin wa shiwasu no funiki ni tsutsumareru."}'::jsonb, '["十二月","とも","なると、","都心は","師走の雰囲気に","包まれる。"]'::jsonb, '十二月ともなると (jika sudah sampai bulan Desember) menandai perubahan suasana khas musim.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjabat kepala departemen, kita harus memikirkan strategi seluruh perusahaan."', '{"display_text":"部長クラスともなると、自部署だけでなく全社的な視点が求められます。","romaji":"Buchou kurasu to mo naru to, jibusho dake de naku zenshateki na shiten ga motomeraremasu.","phonetic_breakdown":["ぶちょうくらす","ともなると","じぶしょだけでなく","ぜんしゃてきなしてんが","もとめられます"]}'::jsonb, '{"expected_transcript":"部長クラスともなると、自部署だけでなく全社的な視点が求められます。"}'::jsonb, '部長クラスともなると menegaskan ekspektasi kepemimpinan tingkat eksekutif.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 大学院の博士課程___、自ら独自の研究テーマを切り開く力が不可欠だ。', '{"options":["ともなると","ずにはおかず","に足らず","いかんによらず"],"translation":"Jika sudah masuk jenjang doktoral pascasarjana, kemampuan merintis topik penelitian orisinal sendiri mutlak diperlukan.","sentence_template":"大学院の博士課程[blank]、自ら独自の研究テーマを切り開く力が不可欠だ。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, '博士課程ともなると membedakan tuntutan jenjang doktoral dari jenjang sebelumnya.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan percakapan dua peneliti. Apa tantangan jika hasil riset dipublikasikan di jurnal top dunia?', '{"audio_text":"世界最高峰の学術誌に論文を載せるレベルともなれば、査読の厳しさは想像を超えるよ。","options":[{"id":"opt_1","text":"Jurnal ilmiah top dunia tidak memiliki proses penelaahan sejawat"},{"id":"opt_2","text":"Siapa saja bisa langsung menerbitkan tulisan dalam satu jam"},{"id":"opt_3","text":"Jika sudah sampai level memuat makalah di jurnal ilmiah puncak dunia, ketatnya proses peer-review melampaui bayangan"},{"id":"opt_4","text":"Peneliti tidak perlu menyertakan data eksperimen"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, 'レベルともなれば menyoroti standar ketat yang menyertai pencapaian level tertinggi.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah mencapai tingkat JLPT N1, Anda diharapkan mampu memahami tajuk rencana koran."', '{"tokens":["とも","新聞の社説を","期待される。","期待した。","N1レベル","なると、","理解する力が","とはいえ、"],"target_translation":"Jika sudah mencapai tingkat JLPT N1, Anda diharapkan mampu memahami tajuk rencana koran.","romaji":"N1 reberu to mo naru to, shinbun no shasetsu o rikai suru chikara ga kitai sareru."}'::jsonb, '["N1レベル","とも","なると、","新聞の社説を","理解する力が","期待される。"]'::jsonb, 'N1レベルともなると menegaskan standar kompetensi bahasa tingkat lanjut.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar direktur keamanan. Apa standar untuk konferensi tingkat tinggi internasional?', '{"audio_text":"各国首脳が一堂に会する国際サミットともなると、警備体制は数ヶ月前から万全を期して準備されます。","options":[{"id":"opt_1","text":"Persiapan pengamanan untuk KTT internasional yang dihadiri para kepala negara sudah disiapkan matang sejak beberapa bulan sebelumnya"},{"id":"opt_2","text":"KTT internasional hanya dijaga oleh dua petugas keamanan"},{"id":"opt_3","text":"Persiapan pengamanan baru dimulai satu jam sebelum acara"},{"id":"opt_4","text":"KTT internasional selalu diadakan secara daring tanpa pengamanan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '国際サミットともなると menjelaskan standar pengamanan luar biasa sesuai skalanya.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah menjadi atlet nasional, menjaga pola makan sehari-hari pun bagian dari pekerjaan."', '{"tokens":["とも","日々の食事管理も","仕事だ。","仕事だった。","代表選手","なれば、","重要な","なりに、"],"target_translation":"Jika sudah menjadi atlet nasional, menjaga pola makan sehari-hari pun bagian dari pekerjaan.","romaji":"Daihyou senshu to mo nareba, shokuji kanri mo juuyou na shigoto da."}'::jsonb, '["代表選手","とも","なれば、","日々の食事管理も","重要な","仕事だ。"]'::jsonb, '代表選手ともなれば menyoroti kedisiplinan profesional seorang atlet timnas.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 創業百年の老舗___、伝統を守りつつ革新を続ける重圧も大きい。', '{"options":["ともなると","をもって","を余儀なくされ","極まりない"],"translation":"Jika sudah menjadi perusahaan mapan berusia seratus tahun, tekanan untuk menjaga tradisi sambil terus berinovasi pun besar.","sentence_template":"創業百年の老舗[blank]、伝統を守りつつ革新を続ける重圧も大きい。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, '老舗ともなると menunjukkan beban sekaligus kehormatan status perusahaan berusia seabad.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah mengelola tim beranggotakan lima puluh orang, pendelegasian tugas menjadi kunci."', '{"display_text":"五十人規模のチームを率いる立場ともなると、権限委譲が鍵になります。","romaji":"Gojuunin kibo no chiimu o hikiiru tachiba to mo naru to, kengen ijou ga kagi ni narimasu.","phonetic_breakdown":["ごじゅうにんきぼの","ちーむをひきいる","たちばともなると","けんげんいじょうが","かぎになります"]}'::jsonb, '{"expected_transcript":"五十人規模のチームを率いる立場ともなると、権限委譲が鍵になります。"}'::jsonb, '権限委譲 (pendelegasian wewenang) adalah kosakata manajemen tingkat N1.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 標高三千メートル級の登山___、夏場でも防寒具の携行が欠かせない。', '{"options":["ともなると","に至って","に足る","ずにはおかない"],"translation":"Jika sudah pendakian gunung kelas ketinggian 3.000 meter, membawa pakaian hangat mutlak diperlukan meski di musim panas.","sentence_template":"標高三千メートル級の登山[blank]、夏場でも防寒具の携行が欠かせない。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, '標高三千メートル級の登山ともなると menekankan syarat keselamatan khusus level ekstrem.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan ulasan pengamat properti. Apa ciri gedung pencakar langit di pusat Tokyo?', '{"audio_text":"都心の一等地に建つ超高層ビルともなれば、最先端の免震構造と環境性能が標準仕様となっている。","options":[{"id":"opt_1","text":"Gedung pencakar langit di pusat kota dibangun tanpa standar tahan gempa"},{"id":"opt_2","text":"Semua gedung di pusat kota hanya setinggi dua lantai"},{"id":"opt_3","text":"Gedung pencakar langit tidak memperhatikan efisiensi energi"},{"id":"opt_4","text":"Jika sudah gedung pencakar langit di lokasi premium pusat kota, struktur peredam gempa mutakhir dan performa ramah lingkungan menjadi standar baku"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '超高層ビルともなれば menunjukkan ekspektasi spesifikasi kelas atas.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah menjadi pemimpin proyek global, kemampuan negosiasi lintas budaya sangat dibutuhkan."', '{"tokens":["リーダー","異文化交渉力が","だ。","不可欠だった。","グローバル案件の","ともなれば、","不可欠","とはいえ、"],"target_translation":"Jika sudah menjadi pemimpin proyek global, kemampuan negosiasi lintas budaya sangat dibutuhkan.","romaji":"Guroobaru anken no riidaa to mo nareba, ibunka koushouryoku ga fukaketsu da."}'::jsonb, '["グローバル案件の","リーダー","ともなれば、","異文化交渉力が","不可欠","だ。"]'::jsonb, 'リーダーともなれば menegaskan kompetensi kunci bagi posisi pimpinan.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjadi perusahaan terbuka, tanggung jawab keterbukaan informasi kepada investor jauh lebih ketat."', '{"display_text":"上場企業ともなると、投資家への情報開示責任が一層厳しくなります。","romaji":"Joujou kigyou to mo naru to, toushika e no jouhou kaiji sekinin ga issou kibishiku narimasu.","phonetic_breakdown":["じょうじょうきぎょう","ともなると","とうしかへの","じょうほうかいじせきにんが","いっそうきびしくなります"]}'::jsonb, '{"expected_transcript":"上場企業ともなると、投資家への情報開示責任が一層厳しくなります。"}'::jsonb, '上場企業ともなると (jika sudah menjadi emiten/perusahaan terbuka) sangat lazim di wacana bisnis N1.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: 役員クラスともなると、長期的な経営___を描く力が求められる。', '{"options":["戦略","趣味","雑談","休暇"],"translation":"Jika sudah mencapai kelas direksi, dituntut kemampuan merancang strategi/visi manajemen jangka panjang.","sentence_template":"役員クラスともなると、長期的な経営[blank]を描く力が求められる。"}'::jsonb, '{"selected":"戦略"}'::jsonb, '経営戦略を描く (merancang strategi manajemen) adalah kolokasi bisnis tingkat eksekutif.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjadi restoran bintang tiga, detail pelayanan terkecil pun diperhatikan dengan saksama."', '{"display_text":"三つ星レストランともなると、接客の細部まで完璧に配慮されています。","romaji":"Mitsuboshi resutoran to mo naru to, sekkyaku no saibu made kanpeki ni hairyo sarete imasu.","phonetic_breakdown":["みつぼしれすとらんと","もなると","せっきゃくのさいぶまで","かんぺきにはいりょ","されています"]}'::jsonb, '{"expected_transcript":"三つ星レストランともなると、接客の細部まで完璧に配慮されています。"}'::jsonb, '細部まで完璧に配慮する menggambarkan standar layanan kelas dunia.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa poin yang ditekankan dengan ～ともなると?', '{"audio_text":"プロ野球の主力選手ともなると、オフシーズンでも休む間もなくトレーニングを続ける。","options":[{"id":"opt_1","text":"Pemain inti bisbol profesional bahkan di luar musim tetap berlatih tanpa henti sesuai standar levelnya"},{"id":"opt_2","text":"Pemain bisbol profesional tidak pernah berlatih di luar musim"},{"id":"opt_3","text":"Hanya pemain amatir yang perlu berlatih keras"},{"id":"opt_4","text":"Musim bisbol berlangsung hanya satu minggu"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '主力選手ともなると menyoroti dedikasi luar biasa yang menyertai status pemain inti.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 子どもが三人___、毎月の食費や教育費の負担もかなりの額になる。', '{"options":["ともなると","なりに","をもって","いかんによらず"],"translation":"Jika sudah memiliki tiga orang anak, beban biaya makan dan pendidikan tiap bulan pun mencapai jumlah yang cukup besar.","sentence_template":"子どもが三人[blank]、毎月の食費や教育費の負担もかなりの額になる。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, 'Jumlah/skala (三人) + ともなると menyatakan konsekuensi yang tak terhindarkan saat mencapai skala itu.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah memasuki musim panas yang terik, risiko sengatan panas meningkat drastis."', '{"tokens":["とも","熱中症の","急激に高まる。","高まった。","真夏","なると、","リスクが","とはいえ、"],"target_translation":"Jika sudah memasuki musim panas yang terik, risiko sengatan panas meningkat drastis.","romaji":"Manatsu to mo naru to, netchuushou no risuku ga kyuugeki ni takamaru."}'::jsonb, '["真夏","とも","なると、","熱中症の","リスクが","急激に高まる。"]'::jsonb, '真夏ともなると (jika sudah puncak musim panas) sangat alami untuk peringatan kesehatan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar kurator museum. Apa keistimewaan pameran berskala internasional?', '{"audio_text":"世界遺産級の美術品を展示する展覧会ともなれば、温度や湿度の管理には細心の注意が払われる。","options":[{"id":"opt_1","text":"Museum membuka jendela lebar-lebar tanpa pengaturan suhu"},{"id":"opt_2","text":"Untuk pameran yang menampilkan karya seni kelas warisan dunia, pengaturan suhu dan kelembapan dilakukan dengan ketelitian maksimal"},{"id":"opt_3","text":"Karya seni boleh disentuh langsung oleh pengunjung"},{"id":"opt_4","text":"Pameran berlangsung di lapangan terbuka"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '細心の注意が払われる berarti perhatian paling cermat diberikan sesuai kelas pamerannya.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 国の政策を左右する審議会___、各分野の第一人者が委員に選ばれる。', '{"options":["ともなると","極まりなく","ずにはおかず","を余儀なくされ"],"translation":"Jika sudah dewan pertimbangan yang menentukan kebijakan negara, tokoh terkemuka dari tiap bidang yang dipilih menjadi anggotanya.","sentence_template":"国の政策を左右する審議会[blank]、各分野の第一人者が委員に選ばれる。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, '第一人者 (pakar terkemuka) berpasangan alami dengan standar tinggi ～ともなると.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjadi duta besar, setiap tindak tanduk membawa kehormatan negara."', '{"display_text":"一国の大使ともなれば、日々の振る舞い一つにも国の威信がかかっています。","romaji":"Ikkoku no taishi to mo nareba, hibi no furumai hitotsu ni mo kuni no ishin ga kakatte imasu.","phonetic_breakdown":["いっこくのたいし","ともなれば","ひびのふるまいひとつにも","くにのいしんが","かかっています"]}'::jsonb, '{"expected_transcript":"一国の大使ともなれば、日々の振る舞い一つにも国の威信がかかっています。"}'::jsonb, '国の威信がかかる (mempertaruhkan wibawa negara) cocok dengan peran tinggi 大使ともなれば.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan wawancara direktur bank. Apa yang ia katakan tentang transaksi bernilai triliunan?', '{"audio_text":"兆円単位の国際融資ともなると、単一の金融機関ではなく複数の銀行が協調してリスクを分担する。","options":[{"id":"opt_1","text":"Transaksi bernilai triliunan yen selalu ditangani satu staf saja"},{"id":"opt_2","text":"Bank tidak pernah bekerja sama dalam pinjaman internasional"},{"id":"opt_3","text":"Jika sudah pembiayaan internasional berskala triliunan yen, beberapa bank berkolaborasi membagi risiko alih-alih satu lembaga saja"},{"id":"opt_4","text":"Pinjaman internasional tidak memiliki risiko sama sekali"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '協調してリスクを分担する menjelaskan mekanisme sindikasi bank pada skala triliunan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah menjadi peneliti senior, membimbing generasi penerus juga merupakan tugas utama."', '{"tokens":["とも","後輩の育成も","任務だ。","任務だった。","中堅研究者","なると、","重要な","なりに、"],"target_translation":"Jika sudah menjadi peneliti senior, membimbing generasi penerus juga merupakan tugas utama.","romaji":"Chuuken kenkyuusha to mo naru to, kouhai no ikusei mo juuyou na ninmu da."}'::jsonb, '["中堅研究者","とも","なると、","後輩の育成も","重要な","任務だ。"]'::jsonb, '中堅研究者ともなると menyoroti perluasan tanggung jawab pada tahap karier menengah-senior.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi klausul kepatuhan perusahaan berikut: 役職や勤続年数の___、ハラスメント行為には厳正に対処する。', '{"options":["いかんによらず","に至って","極まりなく","なりに"],"translation":"Tanpa memandang jabatan maupun masa kerja, tindakan pelecehan akan ditindak secara tegas dan adil.","sentence_template":"役職や勤続年数の[blank]、ハラスメント行為には厳正に対処する。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, 'Kata benda + の + いかんによらず menyatakan prinsip tegas yang berlaku tanpa pengecualian apa pun.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih varian formal yang setara dalam dokumen hukum: 理由の___、期限を過ぎた申請書は一切受理しない。', '{"options":["いかんを問わず","とはいえ","ともなると","に足る"],"translation":"Apa pun alasannya, formulir permohonan yang melewati batas waktu tidak akan diterima sama sekali.","sentence_template":"理由の[blank]、期限を過ぎた申請書は一切受理しない。"}'::jsonb, '{"selected":"いかんを問わず"}'::jsonb, '～のいかんを問わず adalah pasangan super-formal yang sepadan dengan ～のいかんによらず.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman aturan ujian sertifikasi. Bagaimana kebijakan bagi peserta yang melanggar aturan?', '{"audio_text":"故意か過失かのいかんによらず、試験会場で不正行為が確認された場合は直ちに失格となります。","options":[{"id":"opt_1","text":"Pelanggaran tidak disengaja tetap diberikan nilai lulus"},{"id":"opt_2","text":"Tanpa memandang disengaja atau kelalaian, jika kecurangan terbukti di ruang ujian maka peserta langsung didiskualifikasi"},{"id":"opt_3","text":"Peserta boleh mengulang ujian pada hari yang sama"},{"id":"opt_4","text":"Aturan ujian hanya berlaku bagi peserta baru"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '故意か過失かのいかんによらず berarti tanpa memandang apakah dilakukan sengaja atau karena kelalaian.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang hasil akhirnya, proses yang jujur tetap harus dijunjung tinggi."', '{"tokens":["いかん","公正なプロセスが","べきだ。","守った","結果の","によらず、","守られる","とはいえ、"],"target_translation":"Tanpa memandang hasil akhirnya, proses yang jujur tetap harus dijunjung tinggi.","romaji":"Kekka no ikan ni yorazu, kousei na purosesu ga mamorareru beki da."}'::jsonb, '["結果の","いかん","によらず、","公正なプロセスが","守られる","べきだ。"]'::jsonb, '結果のいかんによらず menegaskan prinsip integritas prosedur tanpa bergantung hasil.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang kewarganegaraan atau usia, hak asasi setiap individu harus dihormati."', '{"display_text":"国籍や年齢のいかんによらず、すべての人の権利が平等に尊重されます。","romaji":"Kokuseki ya nenrei no ikan ni yorazu, subete no hito no kenri ga byoudou ni sonchou saremasu.","phonetic_breakdown":["こくせきや","ねんれいの","いかんによらず","すべてのひとのけんりが","びょうどうにそんちょうされます"]}'::jsonb, '{"expected_transcript":"国籍や年齢のいかんによらず、すべての人の権利が平等に尊重されます。"}'::jsonb, '権利が平等に尊重される (hak dihormati secara setara) adalah bahasa konstitusi/HAM N1.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi pasal perjanjian berikut: 損害額の___、情報漏洩が判明した際は速やかに報告する義務がある。', '{"options":["いかんによらず","をもって","を余儀なくされ","ずにはおかず"],"translation":"Tanpa memandang besar kecilnya nilai kerugian, saat kebocoran informasi terungkap wajib segera melapor.","sentence_template":"損害額の[blank]、情報漏洩が判明した際は速やかに報告する義務がある。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, '損害額のいかんによらず (berapa pun nilai kerugiannya) adalah klausul standar keamanan data.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan penjelasan bagian kepegawaian. Bagaimana sistem evaluasi promosi di perusahaan tersebut?', '{"audio_text":"弊社では性別や出身大学のいかんによらず、実力と実績のみで昇進を判断しています。","options":[{"id":"opt_1","text":"Promosi hanya diberikan kepada lulusan universitas tertentu"},{"id":"opt_2","text":"Promosi ditentukan berdasarkan kedekatan pribadi"},{"id":"opt_3","text":"Perusahaan menilai promosi semata berdasarkan kemampuan dan prestasi tanpa memandang gender maupun almamater"},{"id":"opt_4","text":"Perusahaan tidak memiliki sistem promosi jabatan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '性別や出身大学のいかんによらず menegaskan prinsip meritokrasi.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang cuaca, acara peringatan di dalam aula tetap dilaksanakan sesuai jadwal."', '{"tokens":["いかん","ホール内の式典は","実施される。","実施した。","天候の","によらず、","予定通り","に至って、"],"target_translation":"Tanpa memandang cuaca, acara peringatan di dalam aula tetap dilaksanakan sesuai jadwal.","romaji":"Tenkou no ikan ni yorazu, hoori nai no shikiten wa yotei doori jisshi sareru."}'::jsonb, '["天候の","いかん","によらず、","ホール内の式典は","予定通り","実施される。"]'::jsonb, '天候のいかんによらず (bagaimanapun cuacanya) lazim pada surat undangan resmi.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kutipan pedoman medis. Prinsip apa yang dipegang rumah sakit darurat tersebut?', '{"audio_text":"救急医療の現場では、患者の社会的地位や経済状況のいかんによらず、命の緊急度に応じて処置を行う。","options":[{"id":"opt_1","text":"Di unit gawat darurat, penanganan dilakukan sesuai tingkat kegawatan nyawa tanpa memandang status sosial atau kondisi ekonomi pasien"},{"id":"opt_2","text":"Pasien kaya selalu dilayani lebih dahulu meski tidak gawat"},{"id":"opt_3","text":"Rumah sakit hanya menerima pasien dengan asuransi swasta"},{"id":"opt_4","text":"Unit gawat darurat tutup pada akhir pekan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '社会的地位や経済状況のいかんによらず menyatakan prinsip etika medis universal.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang pengalaman kerja sebelumnya, semua staf baru wajib mengikuti pelatihan kepatuhan."', '{"tokens":["いかん","全社員は","受講が必須だ。","受講した。","経験の","によらず、","コンプライアンス研修の","なりに、"],"target_translation":"Tanpa memandang pengalaman kerja sebelumnya, semua staf baru wajib mengikuti pelatihan kepatuhan.","romaji":"Keiken no ikan ni yorazu, shain wa konpuraiansu kenshuu no jukou ga hissu da."}'::jsonb, '["経験の","いかん","によらず、","全社員は","コンプライアンス研修の","受講が必須だ。"]'::jsonb, '経験のいかんによらず (tanpa memandang ada tidaknya pengalaman) umum di aturan SDM.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 金額の___、取引先からの不適切な金品の受領は就業規則で禁じられている。', '{"options":["いかんによらず","極まりなく","ともなると","に足らず"],"translation":"Tanpa memandang besar kecilnya nominal, penerimaan uang atau barang tak pantas dari mitra bisnis dilarang oleh peraturan kerja.","sentence_template":"金額の[blank]、取引先からの不適切な金品の受領は就業規則で禁じられている。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, '金額のいかんによらず menegaskan kebijakan nol toleransi terhadap gratifikasi.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang skala perusahaan, kepatuhan terhadap hukum lingkungan adalah kewajiban mutlak."', '{"display_text":"企業規模のいかんによらず、環境法令の遵守は絶対的な義務です。","romaji":"Kigyou kibo no ikan ni yorazu, kankyou hourei no junshu wa zettaiteki na gimu desu.","phonetic_breakdown":["きぎょうきぼの","いかんによらず","かんきょうほうれいの","じゅんしゅは","ぜったいてきなぎむです"]}'::jsonb, '{"expected_transcript":"企業規模のいかんによらず、環境法令の遵守は絶対的な義務です。"}'::jsonb, '法令の遵守 (kepatuhan terhadap peraturan perundang-undangan) adalah istilah kunci compliance N1.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 勝敗の___、最後まで全力を出し切った選手たちに拍手を送りたい。', '{"options":["いかんによらず","とはいえ","をもって","に至って"],"translation":"Tanpa memandang menang atau kalah, saya ingin memberikan tepuk tangan kepada para atlet yang mengerahkan segenap tenaga hingga akhir.","sentence_template":"勝敗の[blank]、最後まで全力を出し切った選手たちに拍手を送りたい。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, '勝敗のいかんによらず (menang ataupun kalah) memuji sportivitas atlet.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pengumuman kebijakan pengembalian barang. Dalam kondisi apa barang rusak dapat ditukar?', '{"audio_text":"購入店舗のいかんによらず、製造上の欠陥が確認された製品は無償で交換いたします。","options":[{"id":"opt_1","text":"Barang hanya bisa ditukar jika dibeli di kantor pusat"},{"id":"opt_2","text":"Produk cacat produksi tidak dapat ditukar"},{"id":"opt_3","text":"Pelanggan harus membayar biaya tambahan untuk penukaran"},{"id":"opt_4","text":"Tanpa memandang di cabang mana produk dibeli, produk yang terbukti cacat produksi akan diganti secara gratis"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '購入店舗のいかんによらず memberikan jaminan layanan konsumen menyeluruh.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang latar belakang budaya, setiap pendapat dihargai dalam forum ini."', '{"tokens":["いかん","すべての意見が","される。","を余儀なくされ、","文化的背景の","によらず、","尊重","尊重した"],"target_translation":"Tanpa memandang latar belakang budaya, setiap pendapat dihargai dalam forum ini.","romaji":"Bunka-teki haikei no ikan ni yorazu, subete no iken ga sonchou sareru."}'::jsonb, '["文化的背景の","いかん","によらず、","すべての意見が","尊重","される。"]'::jsonb, '文化的背景のいかんによらず menegaskan inklusivitas forum internasional.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang alasan apa pun, pelanggaran kerahasiaan data akan dikenai sanksi berat."', '{"display_text":"理由のいかんによらず、機密情報の不正持ち出しは厳罰の対象となります。","romaji":"Riyuu no ikan ni yorazu, kimitsu jouhou no fusei mochidashi wa genbatsu no taishou to narimasu.","phonetic_breakdown":["りゆうの","いかんによらず","きみつじょうほうの","ふせいもちだしは","げんばつのたいしょうとなります"]}'::jsonb, '{"expected_transcript":"理由のいかんによらず、機密情報の不正持ち出しは厳罰の対象となります。"}'::jsonb, '厳罰の対象となる (menjadi sasaran sanksi berat) adalah gaya bahasa aturan keamanan informasi.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata hukum/bisnis N1 yang tepat: 理由のいかんによらず、契約違反には___が科される。', '{"options":["違約金","奨学金","祝儀","補助金"],"translation":"Tanpa memandang alasan apa pun, pelanggaran kontrak akan dikenai denda/penalti.","sentence_template":"理由のいかんによらず、契約違反には[blank]が科される。"}'::jsonb, '{"selected":"違約金"}'::jsonb, '違約金 (iyakukin = denda pelanggaran kontrak) berpasangan sangat erat dengan klausul いかんによらず.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang hasil pemilihan, kami akan menghormati keputusan suara terbanyak."', '{"display_text":"投票結果のいかんによらず、民主的な決定を尊重いたします。","romaji":"Touhyou kekka no ikan ni yorazu, minshuteki na kettei o sonchou itashimasu.","phonetic_breakdown":["とうひょうけっかの","いかんによらず","みんしゅてきなけっていを","そんちょういたします"]}'::jsonb, '{"expected_transcript":"投票結果のいかんによらず、民主的な決定を尊重いたします。"}'::jsonb, '投票結果のいかんによらず mencerminkan sikap kenegarawanan yang formal.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa makna utama dari ～いかんによらず?', '{"audio_text":"本人の意思のいかんによらず、法律で定められた手続きは遵守しなければならない。","options":[{"id":"opt_1","text":"Prosedur yang ditetapkan hukum wajib dipatuhi tanpa memandang kehendak pribadi seseorang"},{"id":"opt_2","text":"Seseorang bebas mengabaikan hukum jika tidak setuju"},{"id":"opt_3","text":"Hukum hanya berlaku jika seseorang menginginkannya"},{"id":"opt_4","text":"Prosedur hukum bisa diubah oleh siapa saja"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '本人の意思のいかんによらず menegaskan keberlakuan hukum yang objektif.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan partikel penghubung yang tepat: 資格の有無___いかんによらず、意欲のある方を歓迎します。', '{"options":["の","を","に","で"],"translation":"Tanpa memandang ada tidaknya sertifikat, kami menyambut siapa saja yang memiliki motivasi tinggi.","sentence_template":"資格の有無[blank]いかんによらず、意欲のある方を歓迎します。"}'::jsonb, '{"selected":"の"}'::jsonb, 'Struktur baku adalah [Kata Benda] + の + いかんによらず (atau langsung kata benda + いかんによらず pada beberapa frasa, namun の adalah bentuk paling standar dan formal).', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang untung atau rugi, keselamatan konsumen harus selalu dinomorsatukan."', '{"tokens":["いかん","消費者の安全が","べきだ。","とはいえ、","損益の","によらず、","最優先される","最優先した"],"target_translation":"Tanpa memandang untung atau rugi, keselamatan konsumen harus selalu dinomorsatukan.","romaji":"Soneki no ikan ni yorazu, shouhisha no anzen ga saiyuu-sen sareru beki da."}'::jsonb, '["損益の","いかん","によらず、","消費者の安全が","最優先される","べきだ。"]'::jsonb, '損益のいかんによらず (tanpa memandang untung-rugi) adalah prinsip etika bisnis.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan peraturan perpustakaan nasional. Siapa yang dapat mengakses arsip digital?', '{"audio_text":"居住地域のいかんによらず、所定の利用登録を行えば誰でもデジタルアーカイブを閲覧できる。","options":[{"id":"opt_1","text":"Hanya penduduk ibu kota yang boleh mengakses arsip"},{"id":"opt_2","text":"Siapa saja dapat mengakses arsip digital setelah melakukan registrasi resmi tanpa memandang wilayah tempat tinggal"},{"id":"opt_3","text":"Arsip digital hanya dibuka satu jam dalam setahun"},{"id":"opt_4","text":"Pengguna harus membeli buku cetak terlebih dahulu"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '居住地域のいかんによらず berarti tanpa memandang daerah domisili.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 相手との関係性の___、監査業務は客観的かつ中立に遂行される。', '{"options":["いかんによらず","極まりなく","ずにはおかず","に足らず"],"translation":"Tanpa memandang hubungan dengan pihak terkait, tugas audit dijalankan secara objektif dan netral.","sentence_template":"相手との関係性の[blank]、監査業務は客観的かつ中立に遂行される。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, '関係性のいかんによらず menegaskan independensi auditor.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang skala proyek, standar kualitas kami tidak pernah berubah."', '{"display_text":"案件規模のいかんによらず、弊社の品質基準は一切変わりません。","romaji":"Anken kibo no ikan ni yorazu, heisha no hinshitsu kijun wa issai kawarimasen.","phonetic_breakdown":["あんけんきぼの","いかんによらず","へいしゃのひんしつきじゅんは","いっさいかわりません"]}'::jsonb, '{"expected_transcript":"案件規模のいかんによらず、弊社の品質基準は一切変わりません。"}'::jsonb, '品質基準は一切変わりません menguatkan komitmen mutu yang konsisten.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kutipan aturan ketenagakerjaan. Apa isi ketentuan tersebut?', '{"audio_text":"雇用形態のいかんによらず、同一の労働に対しては同一の賃金が支払われるべきである。","options":[{"id":"opt_1","text":"Pekerja kontrak selalu dibayar setengah dari pekerja tetap untuk pekerjaan sama"},{"id":"opt_2","text":"Upah tidak berkaitan dengan jenis pekerjaan"},{"id":"opt_3","text":"Tanpa memandang status kepegawaian, pekerjaan yang sama harus menerima upah yang sama"},{"id":"opt_4","text":"Perusahaan dilarang mempekerjakan staf paruh waktu"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '雇用形態のいかんによらず (tanpa memandang status kerja tetap/kontrak) adalah prinsip 同一労働同一賃金.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang hasilnya nanti, pengalaman ini pasti menjadi bekal berharga."', '{"tokens":["いかん","この経験は","なるはずだ。","をもって、","合否の","によらず、","貴重な糧に","なった。"],"target_translation":"Tanpa memandang hasilnya nanti, pengalaman ini pasti menjadi bekal berharga.","romaji":"Gouhi no ikan ni yorazu, kono keiken wa kichou na kate ni naru."}'::jsonb, '["合否の","いかん","によらず、","この経験は","貴重な糧に","なるはずだ。"]'::jsonb, '合否のいかんによらず (tanpa memandang lulus atau tidaknya) lazim dalam refleksi ujian.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi ulasan akademis berikut: 長年の実証データに基づく彼の理論は、十分に信頼___ものだ。', '{"options":["するに足る","したに足る","してに足る","せに足る"],"translation":"Teorinya yang didasarkan pada data empiris bertahun-tahun adalah hal yang sangat layak untuk dipercaya.","sentence_template":"長年の実証データに基づく彼の理論は、十分に信頼[blank]ものだ。"}'::jsonb, '{"selected":"するに足る"}'::jsonb, 'V-dict (信頼する) + に足る menyatakan bahwa sesuatu memiliki nilai/kualitas yang cukup layak untuk dinilai demikian.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk negatif yang tepat (tidak layak dianggap serius): 根拠を欠いた噂話など、議論する___。', '{"options":["に足りない","に足る","を余儀なくされる","ずにはおかない"],"translation":"Gosip yang tidak memiliki dasar bukti seperti itu sama sekali tidak layak untuk diperdebatkan.","sentence_template":"根拠を欠いた噂話など、議論する[blank]。"}'::jsonb, '{"selected":"に足りない"}'::jsonb, '～に足りない / ～に足らない berarti ''tidak sepadan / tidak layak untuk...''.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan evaluasi komite investasi. Mengapa mereka menyetujui pendanaan startup tersebut?', '{"audio_text":"技術的な優位性と市場の成長性を踏まえ、同社は長期的な投資に足る極めて有望な企業と判断した。","options":[{"id":"opt_1","text":"Karena perusahaan itu meminta dana sangat kecil"},{"id":"opt_2","text":"Berdasarkan keunggulan teknologi dan potensi pasar, komite menilai perusahaan itu sangat menjanjikan dan layak menerima investasi jangka panjang"},{"id":"opt_3","text":"Karena komite tidak sempat memeriksa laporan keuangan"},{"id":"opt_4","text":"Karena seluruh pesaing perusahaan itu sudah bangkrut"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '投資に足る (kata benda 投資 + に足る) berarti layak untuk diinvestasikan.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Ia adalah seorang pemimpin yang memiliki rekam jejak layak dihormati."', '{"tokens":["尊敬","立派な実績を","リーダーだ。","とはいえ、","彼は","に足る","持つ","に足らない"],"target_translation":"Ia adalah seorang pemimpin yang memiliki rekam jejak layak dihormati.","romaji":"Kare wa sonkei ni taru rippa na jisseki o motsu riidaa da."}'::jsonb, '["彼は","尊敬","に足る","立派な実績を","持つ","リーダーだ。"]'::jsonb, '尊敬に足る (layak dihormati) menggunakan kata benda aksi 尊敬 + に足る.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Proposal ini dilengkapi analisis tajam yang sangat layak untuk dipertimbangkan secara serius."', '{"display_text":"この提案書は、真剣に検討するに足る鋭い分析を備えています。","romaji":"Kono teiansho wa, shinken ni kentou suru ni taru surudoi bunseki o sonaete imasu.","phonetic_breakdown":["このていあんしょは","しんけんに","けんとうするにたる","するどいぶんせきを","そなえています"]}'::jsonb, '{"expected_transcript":"この提案書は、真剣に検討するに足る鋭い分析を備えています。"}'::jsonb, '検討するに足る (layak untuk ditelaah/dipertimbangkan) adalah ungkapan evaluasi eksekutif N1.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 今回見つかった新事実は、歴史の教科書を書き換える___重大な発見だ。', '{"options":["に足る","なりに","をもって","いかんによらず"],"translation":"Fakta baru yang ditemukan kali ini adalah penemuan besar yang cukup layak untuk menulis ulang buku teks sejarah.","sentence_template":"今回見つかった新事実は、歴史の教科書を書き換える[blank]重大な発見だ。"}'::jsonb, '{"selected":"に足る"}'::jsonb, '書き換えるに足る menegaskan bobot penemuan yang sepadan dengan tindakan sebesar itu.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar juri lomba sastra. Bagaimana penilaian beliau terhadap karya pemenang?', '{"audio_text":"構成の緻密さと人間描写の深さは、まさに大賞を受賞するに足る傑作であった。","options":[{"id":"opt_1","text":"Karya itu dinilai terlalu dangkal dan terburu-buru"},{"id":"opt_2","text":"Juri tidak jadi memilih pemenang tahun ini"},{"id":"opt_3","text":"Ketelitian struktur dan kedalaman penggambaran manusianya menjadikannya mahakarya yang sungguh layak meraih hadiah utama"},{"id":"opt_4","text":"Karya itu didiskualifikasi karena melebihi batas halaman"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '受賞するに足る傑作 berarti mahakarya yang pantas meraih penghargaan.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Masalah sekecil itu tidak layak untuk terlalu dikhawatirkan."', '{"tokens":["小さな問題は、","に","ない。","極まりない。","そんな","心配する","足ら","足る"],"target_translation":"Masalah sekecil itu tidak layak untuk terlalu dikhawatirkan.","romaji":"Sonna chiisana mondai wa shinpai suru ni taranai."}'::jsonb, '["そんな","小さな問題は、","心配する","に","足ら","ない。"]'::jsonb, '心配するに足らない (tidak layak dikhawatirkan) adalah bentuk negatif alami dari ～に足る.', 8);
            INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
            INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
            VALUES
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan pernyataan kepala penelitian. Apa syarat data agar bisa dijadikan bukti ilmiah?', '{"audio_text":"再現性が確認されていない実験結果は、科学的な証拠として採用するに足らない。","options":[{"id":"opt_1","text":"Hasil eksperimen yang belum terverifikasi keterulangannya tidak layak dipakai sebagai bukti ilmiah"},{"id":"opt_2","text":"Semua hasil eksperimen otomatis diterima sebagai bukti ilmiah"},{"id":"opt_3","text":"Eksperimen ilmiah tidak memerlukan keterulangan hasil"},{"id":"opt_4","text":"Peneliti tidak perlu mempublikasikan metode eksperimennya"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '採用するに足らない menegaskan standar ketelitian ilmiah tingkat N1.', 1),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Usaha keras dan ketulusannya adalah hal yang sungguh patut dipuji."', '{"tokens":["誠実さは、","に","ものだ。","ともなると、","彼の努力と","称賛","足る","に足りない"],"target_translation":"Usaha keras dan ketulusannya adalah hal yang sungguh patut dipuji.","romaji":"Kare no doryoku to seijitsusa wa shousan ni taru mono da."}'::jsonb, '["彼の努力と","誠実さは、","称賛","に","足る","ものだ。"]'::jsonb, '称賛に足る (patut/layak mendapat pujian) adalah ungkapan apresiasi formal.', 2),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 国際会議で発表するからには、専門家からの評価___完成度を目指すべきだ。', '{"options":["に足る","なりに","をもって","極まりない"],"translation":"Karena akan mempresentasikan di konferensi internasional, kita harus menargetkan tingkat kematangan yang layak dinilai para pakar.","sentence_template":"国際会議で発表するからには、専門家からの評価[blank]完成度を目指すべきだ。"}'::jsonb, '{"selected":"に足る"}'::jsonb, '評価に足る (layak untuk dinilai/diapresiasi) memakai kata benda 評価 + に足る.', 3),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pengalaman kegagalan sekalipun bukan hal yang patut disesali jika menjadi pelajaran berharga."', '{"display_text":"失敗の経験であっても、次につながるなら嘆くに足りません。","romaji":"Shippai no keiken de attemo, tsugi ni tsunagaru nara nageku ni tarimasen.","phonetic_breakdown":["しっぱいのけいけんであっても","つぎにつながるなら","なげくに","たりません"]}'::jsonb, '{"expected_transcript":"失敗の経験であっても、次につながるなら嘆くに足りません。"}'::jsonb, '嘆くに足りません (tidak layak untuk diratapi/disesali) adalah ungkapan reflektif formal N1.', 4),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 彼の長年にわたる社会貢献は、まさに賞賛___立派なものだ。', '{"options":["に足る","に至って","を余儀なくされ","とはいえ"],"translation":"Kontribusi sosialnya selama bertahun-tahun sungguh luar biasa dan patut mendapat pujian.","sentence_template":"彼の長年にわたる社会貢献は、まさに賞賛[blank]立派なものだ。"}'::jsonb, '{"selected":"に足る"}'::jsonb, '賞賛に足る (layak dipuji) memodifikasi フレーズ 立派なものだ.', 5),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan tanggapan direktur riset. Mengapa ia menolak usulan proyek tersebut?', '{"audio_text":"市場規模の裏付けが全くなく、このままでは役員会に提出するに足りない企画だ。","options":[{"id":"opt_1","text":"Proposal itu sudah sangat matang dan siap disahkan"},{"id":"opt_2","text":"Dewan direksi telah menyetujui seluruh anggaran proposal"},{"id":"opt_3","text":"Ukuran pasarnya melampaui seluruh perkiraan"},{"id":"opt_4","text":"Karena sama sekali tidak ada data pendukung ukuran pasar, proposal itu belum layak diajukan ke rapat direksi"}]}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, '提出するに足りない berarti tidak cukup memenuhi standar untuk diajukan.', 6),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Mereka adalah mitra kerja yang sungguh layak untuk dipercaya sepenuhnya."', '{"tokens":["心から","に","パートナーだ。","いかんによらず、","彼らは","信頼する","足る","足らない"],"target_translation":"Mereka adalah mitra kerja yang sungguh layak untuk dipercaya sepenuhnya.","romaji":"Karera wa kokoro kara shinrai suru ni taru paatonaa da."}'::jsonb, '["彼らは","心から","信頼する","に","足る","パートナーだ。"]'::jsonb, '信頼するに足る (layak dipercaya) adalah kolokasi yang sangat sering diujikan pada JLPT N1.', 7),
                (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan kesiapan ini, Anda telah memiliki kemampuan yang layak untuk menantang JLPT N1."', '{"display_text":"これまでの研鑽の成果は、十分に自信を持つに足るものです。","romaji":"Kore made no kensan no seika wa, juubun ni jishin o motsu ni taru mono desu.","phonetic_breakdown":["これまでの","けんさんのせいかは","じゅうぶんに","じしんをもつに","たるものです"]}'::jsonb, '{"expected_transcript":"これまでの研鑽の成果は、十分に自信を持つに足るものです。"}'::jsonb, '自信を持つに足る (layak untuk merasa percaya diri) menjadi penutup motivasi kurikulum N1.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: この報告書は経営判断の材料として十分に___に足る。', '{"options":["信頼","撤回","放棄","無視"],"translation":"Laporan ini sangat layak dipercaya sebagai bahan pengambilan keputusan manajemen.","sentence_template":"この報告書は経営判断の材料として十分に[blank]に足る。"}'::jsonb, '{"selected":"信頼"}'::jsonb, '信頼に足る (layak dipercaya) adalah pasangan kosakata paling klasik dengan ～に足る.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karya inovasi tersebut benar-benar patut dibanggakan kepada dunia."', '{"display_text":"この革新的な技術は、世界に誇るに足る偉業です。","romaji":"Kono kakushinteki na gijutsu wa, sekai ni hokoru ni taru igyou desu.","phonetic_breakdown":["このかくしんてきな","ぎじゅつは","せかいにほこるにたる","いぎょうです"]}'::jsonb, '{"expected_transcript":"この革新的な技術は、世界に誇るに足る偉業です。"}'::jsonb, '世界に誇るに足る (layak dibanggakan kepada dunia) adalah ungkapan formal tingkat tinggi.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa arti ～に足らない di sini?', '{"audio_text":"些細な意見の相違など、両社の強固な提携関係から見れば取るに足らない問題だ。","options":[{"id":"opt_1","text":"Perbedaan pendapat kecil itu masalah sepele yang tidak berarti dibanding kuatnya aliansi kedua perusahaan"},{"id":"opt_2","text":"Perbedaan pendapat kecil itu langsung membatalkan aliansi"},{"id":"opt_3","text":"Kedua perusahaan tidak pernah bekerja sama"},{"id":"opt_4","text":"Perbedaan pendapat itu memerlukan sidang pengadilan"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '取るに足らない adalah idiom baku N1 yang berarti ''sepele / tidak layak diperhitungkan''.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Lengkapi kalimat dengan kata kerja yang tepat: 彼の証言は客観的な証拠と一致しており、___に足る。', '{"options":["信じる","信じた","信じて","信じない"],"translation":"Kesaksiannya konsisten dengan bukti objektif sehingga layak untuk dipercaya.","sentence_template":"彼の証言は客観的な証拠と一致しており、[blank]に足る。"}'::jsonb, '{"selected":"信じる"}'::jsonb, 'Di depan に足る, kata kerja selalu menggunakan bentuk kamus (信じるに足る).', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Kualitas layanan mereka tidak layak dijadikan alasan untuk mengeluh."', '{"tokens":["サービスは、","に","ほど立派だ。","とはいえ、","彼らの","非難する","足らない","足る"],"target_translation":"Kualitas layanan mereka tidak layak dijadikan alasan untuk mengeluh.","romaji":"Karera no saabisu wa fuman o iu ni taranai hodo yoi."}'::jsonb, '["彼らの","サービスは、","非難する","に","足らない","ほど立派だ。"]'::jsonb, '非難するに足らない (tidak pantas dikritik/dicela) memakai bentuk negatif に足らない.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan komentar editor jurnal. Mengapa artikel tersebut terpilih sebagai artikel utama?', '{"audio_text":"多角的な視点と厳密な検証により、本論文は今後の議論の出発点とするに足る高い学術的価値を持つ。","options":[{"id":"opt_1","text":"Artikel itu dipilih karena halamannya paling sedikit"},{"id":"opt_2","text":"Karena sudut pandang multidimensional dan verifikasi ketat, makalah ini bernilai akademis tinggi dan layak menjadi titik tolak diskusi ke depan"},{"id":"opt_3","text":"Artikel itu tidak memiliki referensi ilmiah"},{"id":"opt_4","text":"Artikel itu ditolak oleh seluruh tim penelaah"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '出発点とするに足る berarti layak dijadikan titik awal pembahasan ilmiah.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'reading', 'fill_blank', 'Pilih pola yang tepat: 一時的な流行にすぎない現象は、長期戦略の根拠___。', '{"options":["とするに足りない","とするに至った","とせざるを得ない","極まりない"],"translation":"Fenomena yang sekadar tren sesaat tidak layak dijadikan dasar strategi jangka panjang.","sentence_template":"一時的な流行にすぎない現象は、長期戦略の根拠[blank]。"}'::jsonb, '{"selected":"とするに足りない"}'::jsonb, '根拠とするに足りない berarti tidak layak dijadikan landasan.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Keberhasilan reformasi ini adalah teladan yang patut dipelajari oleh organisasi lain."', '{"display_text":"この改革の成功事例は、他団体が参考にするに足る優れたモデルです。","romaji":"Kono kaikaku no seikou jirei wa, tadantai ga sankou ni suru ni taru sugureta moderu desu.","phonetic_breakdown":["このかいかくの","せいこうじれいは","ただんたいがさんこうにするに","たるすぐれたもでるです"]}'::jsonb, '{"expected_transcript":"この改革の成功事例は、他団体が参考にするに足る優れたモデルです。"}'::jsonb, '参考にするに足る (layak dijadikan rujukan/teladan) sering dipakai dalam studi kasus bisnis.', 8);
                INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
                VALUES
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'listening', 'listening_choice', 'Dengarkan sambutan penutup seminar N1. Apa pesan pembicara kepada para peserta?', '{"audio_text":"皆さんの論理的な分析力と表現力は、国際的なビジネス現場で活躍するに足る水準に達しています。","options":[{"id":"opt_1","text":"Peserta diminta mengulang seluruh pelajaran dari tingkat dasar"},{"id":"opt_2","text":"Peserta belum siap menggunakan bahasa Jepang di kantor"},{"id":"opt_3","text":"Kemampuan analisis logis dan ekspresi para peserta telah mencapai standar yang layak berkiprah di dunia bisnis internasional"},{"id":"opt_4","text":"Seminar N1 dibatalkan untuk tahun depan"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '活躍するに足る水準 (standar yang layak untuk berkiprah) merangkum kesiapan praktis JLPT N1.', 7),
                    (gen_random_uuid(), v_lesson_id, v_gp_id, 'writing', 'sentence_builder', 'Susun kalimat: "Hasil riset jangka panjang itu benar-benar patut mendapat perhatian dunia internasional."', '{"tokens":["成果は、","に","価値がある。","極まりない。","長期研究の","注目","足る","に足りない"],"target_translation":"Hasil riset jangka panjang itu benar-benar patut mendapat perhatian dunia internasional.","romaji":"Chouki kenkyuu no seika wa chuumoku ni taru kachi ga aru."}'::jsonb, '["長期研究の","成果は、","注目","に","足る","価値がある。"]'::jsonb, '注目に足る (layak mendapat perhatian) menutup rangkaian sintesis N1 Unit 10.', 8);
        INSERT INTO units (id, level_id, title, description, unit_type, order_index)
        INSERT INTO lessons (id, unit_id, title, short_title, slug, icon_name, xp_reward, order_index)
        INSERT INTO exercises (id, lesson_id, grammar_point_id, skill_pillar, exercise_type, prompt, content, correct_answer, explanation, order_index)
        VALUES
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N1-001' LIMIT 1), 'reading', 'fill_blank', 'Simulasi N1 (1/10): Lengkapi kalimat formal berikut: 顧客データの流出が発覚する___、経営陣はようやく抜本的な安全対策に着手した。', '{"options":["に至って","とはいえ","なりに","に足る"],"translation":"Baru setelah kebocoran data pelanggan terungkap, manajemen akhirnya mulai menerapkan langkah keamanan mendasar.","sentence_template":"顧客データの流出が発覚する[blank]、経営陣はようやく抜本的な安全対策に着手した。"}'::jsonb, '{"selected":"に至って"}'::jsonb, '～に至って menandai titik kritis ekstrem yang baru memicu kesadaran atau tindakan.', 1),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N1-002' LIMIT 1), 'listening', 'listening_choice', 'Simulasi N1 (2/10): Dengarkan berita internasional berikut. Apa konsekuensi yang dialami industri manufaktur?', '{"audio_text":"国際的な供給網の寸断により、主要メーカーの多くが一時的な生産停止を余儀なくされている。","options":[{"id":"opt_1","text":"Banyak produsen utama terpaksa menghentikan produksi sementara akibat terputusnya rantai pasok internasional"},{"id":"opt_2","text":"Rantai pasok internasional berjalan lebih lancar dari sebelumnya"},{"id":"opt_3","text":"Semua produsen melipatgandakan kapasitas pabriknya"},{"id":"opt_4","text":"Industri manufaktur tidak bergantung pada pasokan luar negeri"}]}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, '生産停止を余儀なくされている berarti terpaksa menghentikan produksi akibat faktor eksternal.', 2),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N1-003' LIMIT 1), 'reading', 'fill_blank', 'Simulasi N1 (3/10): Pilih pola argumen berimbang yang tepat: 自動化技術が大きく進展した___、危機発生時の最終判断は人間に委ねられる。', '{"options":["とはいえ","をもって","極まりなく","いかんによらず"],"translation":"Meskipun teknologi otomatisasi telah berkembang pesat, keputusan akhir saat krisis tetap diserahkan kepada manusia.","sentence_template":"自動化技術が大きく進展した[blank]、危機発生時の最終判断は人間に委ねられる。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, '～とはいえ mengakui fakta kemajuan otomatisasi sambil menegaskan catatan kritisnya.', 3),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N1-004' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Terhitung pukul 17.00 hari ini, penerimaan pendaftaran peserta resmi ditutup."', '{"tokens":["をもって、","受付を","いたします。","終了した","本日午後五時","参加申込の","終了","に至って、"],"target_translation":"Terhitung pukul 17.00 hari ini, penerimaan pendaftaran peserta resmi ditutup.","romaji":"Honjitsu gogo goji o motte, sanka moushikomi no uketsuke o shuuryou itashimasu."}'::jsonb, '["本日午後五時","をもって、","参加申込の","受付を","終了","いたします。"]'::jsonb, 'Waktu + をもって menandai batas akhir resmi dalam pengumuman korporasi.', 4),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N1-005' LIMIT 1), 'reading', 'fill_blank', 'Simulasi N1 (5/10): Lengkapi kritik editorial berikut: 住民の安全を軽視した計画強行は、無責任___と言わざるを得ない。', '{"options":["極まりない","に足る","ともなると","なりに"],"translation":"Memaksakan rencana sambil meremehkan keselamatan warga mau tidak mau harus disebut amat sangat tidak bertanggung jawab.","sentence_template":"住民の安全を軽視した計画強行は、無責任[blank]と言わざるを得ない。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, '無責任極まりない menyatakan kritik tajam pada tingkat ekstrem.', 5),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N1-006' LIMIT 1), 'listening', 'listening_choice', 'Simulasi N1 (6/10): Dengarkan komentar mentor berikut. Bagaimana beliau menilai usaha staf baru?', '{"audio_text":"まだ荒削りな点はあるが、彼は彼なりに現場の課題を分析して独自の提案をまとめてくれた。","options":[{"id":"opt_1","text":"Staf baru itu dianggap tidak memahami masalah lapangan sama sekali"},{"id":"opt_2","text":"Meski masih ada kekurangan, staf baru itu telah menganalisis masalah lapangan dan menyusun usulan orisinal dengan caranya sendiri"},{"id":"opt_3","text":"Staf baru itu menyalin laporan orang lain tanpa izin"},{"id":"opt_4","text":"Mentor meminta staf baru membatalkan usulannya"}]}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, '彼は彼なりに mengapresiasi kontribusi sesuai tahap kemampuan dan perannya.', 6),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N1-007' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karya dokumenter yang jujur itu pasti menggugah kesadaran setiap penontonnya."', '{"display_text":"現実を直視したその記録映画は、見る者の良心を揺さぶらずにはおきません。","romaji":"Genjitsu o chokushi shita sono kiroku eiga wa, miru mono no ryoushin o yusaburazu ni wa okimasen.","phonetic_breakdown":["げんじつをちょくしした","そのきろくえいがは","みるもののりょうしんを","ゆさぶらずには","おきません"]}'::jsonb, '{"expected_transcript":"現実を直視したその記録映画は、見る者の良心を揺さぶらずにはおきません。"}'::jsonb, '揺さぶらずにはおきません menyatakan dampak emosional dan moral yang niscaya terjadi.', 7),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N1-008' LIMIT 1), 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah menjadi proyek berskala internasional, standar keamanannya pun sangat ketat."', '{"tokens":["とも","安全基準も","厳しい。","厳しかった。","国際プロジェクト","なると、","極めて","とはいえ、"],"target_translation":"Jika sudah menjadi proyek berskala internasional, standar keamanannya pun sangat ketat.","romaji":"Kokusai purojekuto to mo naru to, anzen kijun mo kiwamete kibishii."}'::jsonb, '["国際プロジェクト","とも","なると、","安全基準も","極めて","厳しい。"]'::jsonb, '～ともなると menyoroti ekspektasi dan standar ketat pada level prestisius.', 8),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N1-009' LIMIT 1), 'listening', 'listening_choice', 'Simulasi N1 (9/10): Dengarkan pasal kepatuhan hukum berikut. Bagaimana prinsip penegakan aturan di organisasi ini?', '{"audio_text":"役職や貢献度のいかんによらず、法令違反が確認された場合には厳正な処分を科すものとする。","options":[{"id":"opt_1","text":"Pejabat tinggi dibebaskan dari sanksi jika kontribusinya besar"},{"id":"opt_2","text":"Sanksi hanya berlaku bagi karyawan baru"},{"id":"opt_3","text":"Tanpa memandang jabatan maupun tingkat kontribusi, pelanggaran hukum yang terbukti akan dikenai sanksi tegas"},{"id":"opt_4","text":"Organisasi tidak memiliki aturan kepatuhan hukum"}]}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, '役職や貢献度のいかんによらず menegaskan keadilan hukum tanpa pengecualian.', 9),
            (gen_random_uuid(), v_lesson_id, (SELECT id FROM grammar_points WHERE code = 'GP-JA-N1-010' LIMIT 1), 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Analisis mendalam yang didukung bukti objektif ini sungguh layak untuk dipercaya."', '{"display_text":"客観的な証拠に裏打ちされたこの分析は、十分に信頼するに足るものです。","romaji":"Kyakkanteki na shouko ni urauchi sareta kono bunseki wa, juubun ni shinrai suru ni taru mono desu.","phonetic_breakdown":["きゃっかんてきな","しょうこにうらうちされた","このぶんせきは","じゅうぶんに","しんらいするにたるものです"]}'::jsonb, '{"expected_transcript":"客観的な証拠に裏打ちされたこの分析は、十分に信頼するに足るものです。"}'::jsonb, '信頼するに足る (layak dipercaya) menutup simulasi kesiapan JLPT N1.', 10);
